            ["I'm right here."] = "dwarf-male\\npc_poke_3.ogg",
            ["Careful, now."] = "dwarf-male\\npc_poke_4.ogg",
            ["Ha! You're a funny one."] = "dwarf-male\\npc_poke_5.ogg",
            ["Need something?"] = "dwarf-male\\npc_poke_6.ogg",
            ["Still here, still with you."] = "dwarf-male\\npc_poke_7.ogg",
            ["What is it? Did you see something?"] = "dwarf-male\\npc_poke_8.ogg",
            ["If that's how you say hello where you're from, all right."] = "dwarf-male\\npc_poke_9.ogg",
            ["I'm listening."] = "dwarf-male\\npc_poke_10.ogg",
            ["Still breathing, if that's what you're checking."] = "dwarf-male\\npc_poke_11.ogg",
            ["Was that a poke or a question?"] = "dwarf-male\\npc_poke_12.ogg",
            ["Easy! I bruise like a peach."] = "dwarf-male\\npc_poke_13.ogg",
            ["You have my full attention. Mostly."] = "dwarf-male\\npc_poke_14.ogg",
            ["Hm? Sorry, I was miles away."] = "dwarf-male\\npc_poke_15.ogg",
            ["Ask away."] = "dwarf-male\\npc_poke_16.ogg",
            ["Ow. Was that necessary?"] = "dwarf-male\\npc_poke_17.ogg",
            ["What, did I miss something?"] = "dwarf-male\\npc_poke_18.ogg",
            ["Present and accounted for."] = "dwarf-male\\npc_poke_19.ogg",
