            ["Feet up! Well, my feet are always kind of up."] = "female\\rest_3.ogg",
            ["A chair, a fire, good company. That's living."] = "female\\npc_rest_4.ogg",
            ["Inns are the best. Warm fire, soft beds, people to befriend."] = "female\\rest_4.ogg",
            ["Let's stay a moment. My feet insist."] = "female\\npc_rest_5.ogg",
            ["Rested and ready. Or at least rested."] = "female\\rest_5.ogg",
            ["This place has the coziest chairs. Too bad I can't reach them."] = "female\\rest_6.ogg",
            ["Easy there, tiger."] = "female\\npc_roarBack_1.ogg",
            ["RAWR! Did I sound scary?"] = "female\\roarBack_1.ogg",
            ["Very fierce. I'm terrified."] = "female\\npc_roarBack_2.ogg",
            ["Roar! I'm a lion now."] = "female\\roarBack_2.ogg",
            ["Was that a roar or a yawn?"] = "female\\npc_roarBack_3.ogg",
            ["Charming."] = "female\\npc_rudeBack_1.ogg",
            ["Hey! I saw that."] = "female\\rudeBack_1.ogg",
            ["I'll pretend I didn't see that."] = "female\\npc_rudeBack_2.ogg",
            ["Well, that was uncalled for."] = "female\\rudeBack_2.ogg",
            ["Well, I never! Actually, I have. But still."] = "female\\npc_rudeBack_3.ogg",
            ["Rude! I'm telling the BuddyDex."] = "female\\rudeBack_3.ogg",
            ["At your service."] = "female\\npc_saluteBack_1.ogg",
            ["Yes, sir! Or ma'am! Or {name}!"] = "female\\saluteBack_1.ogg",
            ["Sir! Or madam."] = "female\\npc_saluteBack_2.ogg",
            ["Reporting for duty!"] = "female\\saluteBack_2.ogg",
            ["Standing ready!"] = "female\\npc_saluteBack_3.ogg",
            ["Standing tall! Well, standing."] = "female\\saluteBack_3.ogg",
            ["Oh, it's {friend}! Say hello for me."] = "female\\npc_seeFriend_1.ogg",
            ["Oh look, it's {friend}! Hi, {friend}!"] = "female\\seeFriend_1.ogg",
            ["{friend}! Good to see a friendly face."] = "female\\npc_seeFriend_2.ogg",
            ["{friend}! I'd know that face anywhere."] = "female\\seeFriend_2.ogg",
            ["Look who it is! Give them a wave."] = "female\\npc_seeFriend_3.ogg",
            ["Hey, it's our pal {friend}."] = "female\\seeFriend_3.ogg",
            ["Oh, I know them! Small world."] = "female\\npc_seeFriend_4.ogg",
            ["{friend}! Have you said hello today? I'm saying hello."] = "female\\seeFriend_4.ogg",
            ["It's {friend}! Best friends forever. Well, {tier}, but working on it."] = "female\\seeFriend_5.ogg",
            ["No need to be shy."] = "female\\npc_shyToo_1.ogg",
            ["Aw, don't be shy."] = "female\\shyToo_1.ogg",
            ["Aw, don't hide."] = "female\\npc_shyToo_2.ogg",
            ["I get shy too sometimes."] = "female\\shyToo_2.ogg",
            ["You're among friends here."] = "female\\npc_shyToo_3.ogg",
            ["Don't mind if I do."] = "female\\npc_sitToo_1.ogg",
            ["Break time! I'll sit too."] = "female\\sitToo_1.ogg",
            ["Good idea. My knees agree."] = "female\\npc_sitToo_2.ogg",
            ["Ahh, feels good to sit."] = "female\\sitToo_2.ogg",
            ["Ah, that's better."] = "female\\npc_sitToo_3.ogg",
            ["I could use a nap myself."] = "female\\npc_sleepToo_1.ogg",
            ["Nap time? Nap time."] = "female\\sleepToo_1.ogg",
            ["Wake me when it's time to go."] = "female\\npc_sleepToo_2.ogg",
            ["Good idea. Zzz."] = "female\\sleepToo_2.ogg",
            ["A nap does sound nice."] = "female\\npc_sleepToo_3.ogg",
            ["Up we go! Never gets old."] = "female\\npc_taxi_1.ogg",
            ["Wheee! I love flying!"] = "female\\taxi_1.ogg",
            ["Look at it all down there."] = "female\\npc_taxi_2.ogg",
            ["Look how small everything is down there! Finally, I fit in."] = "female\\taxi_2.ogg",
            ["A good gryphon is worth its weight in gold."] = "female\\npc_taxi_3.ogg",
            ["Gryphon rides are the best. Don't look down. Okay, look down."] = "female\\taxi_3.ogg",
            ["Hold on tight!"] = "female\\npc_taxi_4.ogg",
            ["We're flying! Hold on to your hat. Our hat."] = "female\\taxi_4.ogg",
            ["I'll never get tired of this view."] = "female\\npc_taxi_5.ogg",
            ["Somebody wave at the people below for me!"] = "female\\taxi_5.ogg",
            ["Don't look down. Actually, do. It's lovely."] = "female\\npc_taxi_6.ogg",
            ["Is it rude to sing on a gryphon? I'm going to sing."] = "female\\taxi_6.ogg",
            ["The wind up here! Hold on to your hat."] = "female\\npc_taxi_7.ogg",
            ["Up here, everyone's tiny. I like it."] = "female\\taxi_7.ogg",
            ["If I fall off, remember me fondly."] = "female\\taxi_8.ogg",
            ["This is the life. Wind in our hair, bugs in our teeth."] = "female\\taxi_9.ogg",
            ["Next stop, adventure!"] = "female\\taxi_10.ogg",
            ["Anytime."] = "female\\npc_thanked_1.ogg",
            ["Aw, you're welcome!"] = "female\\thanked_1.ogg",
            ["Happy to help."] = "female\\npc_thanked_2.ogg",
            ["Anytime, {name}!"] = "female\\thanked_2.ogg",
            ["Don't mention it."] = "female\\npc_thanked_3.ogg",
            ["Don't mention it. Or do. I like it."] = "female\\thanked_3.ogg",
            ["{friend} thinks of you as {tier} now. I'm not surprised."] = "female\\npc_tier_1.ogg",
            ["Hear that? We're {tier} to {friend} now!"] = "female\\tier_1.ogg",
            ["Making friends everywhere you go, aren't you?"] = "female\\npc_tier_2.ogg",
            ["{friend} thinks of us as {tier}. I knew they would!"] = "female\\tier_2.ogg",
            ["People really warm to you, don't they?"] = "female\\npc_tier_3.ogg",
            ["{tier}! {friend} really likes us!"] = "female\\tier_3.ogg",
            ["That friendship's growing. Nice to see."] = "female\\npc_tier_4.ogg",
            ["Look at that. {friend} counts us as {tier}. We're so likable."] = "female\\tier_4.ogg",
            ["Friendship with {friend} just went up a notch!"] = "female\\tier_5.ogg",
            ["{friend} and us. {tier}. Has a nice ring to it."] = "female\\tier_6.ogg",
            ["Hello!"] = "female\\npc_waveBack_1.ogg",
            ["Hi! Hi! Hello!"] = "female\\waveBack_1.ogg",
            ["Hi there!"] = "female\\npc_waveBack_2.ogg",
            ["Hello to you too!"] = "female\\waveBack_2.ogg",
            ["Well, hello to you too."] = "female\\npc_waveBack_3.ogg",
            ["Waving back! I'm waving back!"] = "female\\waveBack_3.ogg",
            ["Right back at you!"] = "female\\npc_waveBack_4.ogg",
            ["Hiya, {name}!"] = "female\\waveBack_4.ogg",
            ["{zone}! I've sold plenty from here. Never been, though."] = "female\\lore9859_zone_1.ogg",
            ["So this is {zone}."] = "female\\npc_zone_1.ogg",
            ["{zone}! I've always wanted to see {zone}."] = "female\\zone_1.ogg",
            ["{zone}, eh? Lead on."] = "female\\npc_zone_2.ogg",
            ["Ooh, {zone}. Keep an eye out for new friends!"] = "female\\zone_2.ogg",
            ["I haven't been to {zone} in years."] = "female\\npc_zone_3.ogg",
            ["So this is {zone}. It's bigger from down here."] = "female\\zone_3.ogg",
            ["{zone}. Stay sharp."] = "female\\npc_zone_4.ogg",
            ["Welcome to {zone}! I'll be your tiny tour guide."] = "female\\zone_4.ogg",
            ["Ah, {zone}. Look at that view."] = "female\\npc_zone_5.ogg",
            ["{zone}. I've heard stories. Mostly good ones."] = "female\\zone_5.ogg",
            ["New place, new faces."] = "female\\npc_zone_6.ogg",
            ["New place, new people! Let's say hi to everyone in {zone}."] = "female\\zone_6.ogg",
            ["Keep your eyes open. I don't know these parts."] = "female\\npc_zone_7.ogg",
            ["Mark it down: we've been to {zone}!"] = "female\\zone_7.ogg",
            ["I've only ever heard stories about this place."] = "female\\npc_zone_8.ogg",
            ["{zone}! Smell that? That's adventure. Or a farm."] = "female\\zone_8.ogg",
            ["Look at it all. Worth the walk."] = "female\\npc_zone_9.ogg",
            ["Is it me, or does {zone} feel friendly?"] = "female\\zone_9.ogg",
            ["Smells different here. Not bad, just different."] = "female\\npc_zone_10.ogg",
            ["Westfall! Watch out for the Defias. And the dust."] = "female\\zone_10.ogg",
            ["I'd better remember the way back."] = "female\\npc_zone_11.ogg",
            ["Home sweet Stormwind!"] = "female\\zone_11.ogg",
            ["Well, this is a change of scenery."] = "female\\npc_zone_12.ogg",
            ["Ironforge! Short ceilings for everyone else, perfect for us."] = "female\\zone_12.ogg",
            ["Duskwood. Let's stay close to the lanterns."] = "female\\zone_13.ogg",
            ["Dun Morogh! I should have brought a scarf."] = "female\\zone_14.ogg",
            ["Elwynn Forest, where every adventure starts."] = "female\\zone_15.ogg",
        },
        ["forsaken-female"] = {
            ["I would welcome your company, my friend. Lead on. No elaborate title is needed. I am simply pleased that you thought to ask me along, and glad to have a little time to hear how you have been."] = "forsaken-female\\lore11945_befriended_1.ogg",
            ["I would welcome your company, my friend. Come on. We can walk for a little while, and you can tell me what the day has held. I am glad you thought to ask me along."] = "forsaken-female\\lore1661_befriended_1.ogg",
            ["You would welcome my company? I would be pleased, my friend. Lead on. We have time to look around us and hear what has interested you. I should enjoy that."] = "forsaken-female\\lore2124_befriended_1.ogg",
            ["I would enjoy your company, my friend. Lead on. We needn't keep count of anything. There is time to walk, to notice what catches your attention, and to hear how the day has been."] = "forsaken-female\\lore2315_befriended_1.ogg",
            ["I would welcome your company, my friend. Come on. We can walk without hurrying past every ordinary thing along the way. Tell me what you have been noticing. I should enjoy hearing it."] = "forsaken-female\\lore267326_befriended_1.ogg",
            ["You would welcome my company? I would be pleased, my friend. Lead on. We have time for conversation, and I should enjoy hearing what has interested you since our last meeting."] = "forsaken-female\\lore5667_befriended_1.ogg",
            ["You would like my company? Gladly, friend. Lead on. We can leave the day's instructions behind for a little while. Tell me how you have been, and what has pleased you since we last spoke."] = "forsaken-female\\lore5749_befriended_1.ogg",
            ["Look at the seams and how it sits. It should serve the person wearing it. If there is a small detail that pleases you as well, I see no reason that should count against a useful piece of work."] = "forsaken-female\\lore1661_gear_1.ogg",
            ["Welcome, my friend. I am pleased to see you. Shall we walk? A beetle has just declined a rather grand introduction by continuing straight past. I trust you can spare a little more time for conversation."] = "forsaken-female\\lore11945_greet_1.ogg",
            ["It is good to see you, my friend. Shall we walk a little? Tell me how you have been, and give me an honest answer. There is time to attend to what needs care before we hurry on."] = "forsaken-female\\lore1661_greet_1.ogg",
            ["A moment, my friend. Does that shadow suggest anything to you? I have been seeing a cat in a very ordinary arrangement. There is no mystery to solve. I simply enjoy noticing it."] = "forsaken-female\\lore2124_greet_1.ogg",
            ["There you are, my friend. Shall we walk a little? I was counting the steps along a familiar stretch, but a conversation would be an agreeable reason to lose the number. Tell me how you have been."] = "forsaken-female\\lore2315_greet_1.ogg",
            ["There you are, my friend. Have you a moment to look at something ordinary? A little grass has found room between stones. I have been enjoying seeing it still there. We can spare it a glance before our walk."] = "forsaken-female\\lore267326_greet_1.ogg",
            ["There you are, my friend. Have you time to consider a small puzzle? I know its answer. I still enjoy seeing the steps come together, and I should be interested to hear how you would approach it."] = "forsaken-female\\lore5667_greet_1.ogg",
            ["There you are, friend. I have just complimented my most obedient assistant. An ordinary stone, keeping papers in place. Very reliable. Now, have you time for a little company that requires fewer instructions?"] = "forsaken-female\\lore5749_greet_1.ogg",
            ["I gave a passing beetle an elaborate introduction. It went on about its business. Not the slightest acknowledgment of its new distinction. I enjoyed the ceremony anyway. A welcome need not demand a reply."] = "forsaken-female\\lore11945_idle_1.ogg",
            ["I chose a bright thread for a repair on something of my own. The seam is sound. I could make it less noticeable, but I rather like seeing it. A useful piece of work may hold a small pleasure too."] = "forsaken-female\\lore1661_idle_1.ogg",
            ["I know precisely what makes the shadow. I still look for the cat. A change in the light brings it back, then takes it away. Understanding the ordinary cause has done very little to diminish the pleasure."] = "forsaken-female\\lore2124_idle_1.ogg",
            ["I wondered how many steps a familiar walk would take. Then I stopped to speak to someone, turned to look at something, and took a few extra steps beside a friend. I found I rather enjoyed the interruptions."] = "forsaken-female\\lore2315_idle_1.ogg",
            ["I have no special ingredient in mind when I look for that grass. I like seeing it still there. Nothing rare about it. An ordinary little pleasure is enough reason to notice a familiar thing again."] = "forsaken-female\\lore267326_idle_1.ogg",
            ["I know the answer to that puzzle. I still work through it occasionally. The parts fit, and I enjoy the moment when they do. A familiar result need not take away all pleasure in reaching it."] = "forsaken-female\\lore5667_idle_1.ogg",
            ["The stone stays exactly where I put it. I know it is simply a stone. I still occasionally call it my most obedient assistant. A small, reliable service can be remarkably pleasant after a demanding day."] = "forsaken-female\\lore5749_idle_1.ogg",
            ["Good. Give the new ability the study it deserves. Understanding its use includes knowing when to exercise restraint. Your next choice is worth as much attention as the first successful attempt."] = "forsaken-female\\lore2124_learned_1.ogg",
            ["Well done. Give the new knowledge a little practice and attention. Learn to recognize what is actually before you. The ordinary things are worth understanding as carefully as the discovery you hoped to make."] = "forsaken-female\\lore267326_learned_1.ogg",
            ["Good. Now attend to how you will apply it. A lesson deserves more than the first excitement of success. Understand the steps, then decide where the knowledge will serve the purpose you have chosen."] = "forsaken-female\\lore5667_learned_1.ogg",
            ["Good. Make certain you understand what you have learned. Being able to give an instruction is a beginning. Knowing what it requires, and whether it is the right one, will spare you a good deal of trouble."] = "forsaken-female\\lore5749_learned_1.ogg",
            ["Another place to make a gracious entrance. Take a moment to look around, my friend. There may be a very small traveler with important business to attend to. We can allow it room before continuing with our own."] = "forsaken-female\\lore11945_zone_1.ogg",
            ["A different place for a walk. Let us take a moment to look around. Tell me what you notice first, my friend. I enjoy discovering which small things someone else thinks worth stopping for."] = "forsaken-female\\lore2315_zone_1.ogg",
        },
        ["forsaken-male"] = {
            ["Take a proper look before deciding what goes. A worn thing may have work left in it. And if one small piece simply pleases you, leave room for that too. A pack need not explain every last choice to someone else."] = "forsaken-male\\lore1740_bagsFull_1.ogg",
            ["Give yourself room to see what you have. Keep the things you need where you can reach them. An ordinary supply can become remarkably important when the moment comes to use it."] = "forsaken-male\\lore2115_bagsFull_1.ogg",
            ["You would like my company? Very well, my friend. I am pleased to see you. No qualification. Let us leave that sentence alone and find somewhere agreeable to walk."] = "forsaken-male\\lore1568_befriended_1.ogg",
            ["You choose my company? Very well, my friend. I am pleased. Lead on. We have time for conversation, and perhaps you can tell me what you think of the improved final line."] = "forsaken-male\\lore1569_befriended_1.ogg",
            ["You would welcome my company? Very well, my friend. I shall make the time. Lead on. We can leave the business aside long enough to hear how the day has treated you."] = "forsaken-male\\lore1570_befriended_1.ogg",
            ["You would like my company? Gladly, friend. Lead on. We can enjoy a little of the day together, and you can tell me what has pleased you since we last had a proper talk."] = "forsaken-male\\lore1736_befriended_1.ogg",
            ["You would like me along? Gladly, friend. Lead on. A walk and a little company would be pleasant. Tell me what has interested you since we last had time to talk."] = "forsaken-male\\lore1737_befriended_1.ogg",
            ["You would welcome my company? I would enjoy that, friend. Lead on. We have time for a walk, and I should like to hear what has been catching your attention along the way."] = "forsaken-male\\lore1739_befriended_1.ogg",
            ["You want me along? Gladly, friend. Lead on. I should like to hear how you have been, and what you have made of the day. There is time to enjoy a little company."] = "forsaken-male\\lore1740_befriended_1.ogg",
            ["You want my company? Gladly, friend. Lead on. We can enjoy a walk and a little conversation. I should like to hear how the day has treated you."] = "forsaken-male\\lore1741_befriended_1.ogg",
            ["I would welcome your company, my friend. Lead on. We can enjoy a walk and give the day's business a little room to settle. Tell me what has pleased you since we last spoke."] = "forsaken-male\\lore2113_befriended_1.ogg",
            ["You want my company? Gladly, friend. Lead on. I should enjoy hearing how the day has treated you. There is time for a pleasant walk, and perhaps an opinion on that final rhyme."] = "forsaken-male\\lore2115_befriended_1.ogg",
            ["You would like me along? Gladly, friend. Lead on. We can enjoy a walk and a little conversation. I should like to hear what you have been making of the day."] = "forsaken-male\\lore2116_befriended_1.ogg",
            ["You want my company? Gladly, friend. Lead on. We can leave the coin out of this decision. I am pleased to have a little time to walk and hear how you have been."] = "forsaken-male\\lore2117_befriended_1.ogg",
            ["You would like my company? Gladly, friend. Lead on. We can enjoy a walk, and you can tell me what you have been making of the day. There is time for that as well as practice."] = "forsaken-male\\lore2119_befriended_1.ogg",
            ["You would welcome my company? Gladly, my friend. Lead on. We have time to talk, and I should enjoy hearing what has caught your attention since we last had a proper conversation."] = "forsaken-male\\lore2122_befriended_1.ogg",
            ["You choose my company? Very well, my friend. I am pleased. Lead on. We can hear what the day has held for you, or allow a little of it to pass without demanding an explanation."] = "forsaken-male\\lore2123_befriended_1.ogg",
            ["You choose my company? I am pleased, my friend. Lead on. I should enjoy hearing what has interested you, and what you intend to make of the day now that some of it is ours to share."] = "forsaken-male\\lore2126_befriended_1.ogg",
            ["I would welcome your company, my friend. Lead on. There is time to hear how you have been, and I am pleased that you thought to share a little of the day with me."] = "forsaken-male\\lore244808_befriended_1.ogg",
            ["I would enjoy your company, my friend. Lead on. Tell me what you have been trying, or simply what you have been curious about. We have time for a pleasant conversation along the way."] = "forsaken-male\\lore267323_befriended_1.ogg",
            ["Stay a moment, my friend. You need not find good news before I will listen. Tell me what you wish, or let us sit awhile without asking anything of the silence. Your company is welcome either way."] = "forsaken-male\\lore244808_comforted_1.ogg",
            ["Does it serve you well? Give that question a proper answer before deciding. A familiar piece of equipment may still have good work left in it, and you know how it feels when you depend on it."] = "forsaken-male\\lore1741_gear_1.ogg",
            ["Look at the seams and how it serves you. There is sense in caring for something useful. And if one small detail makes it a pleasure to keep, I see no reason to disregard that part of the choice."] = "forsaken-male\\lore2113_gear_1.ogg",
            ["See how it sits and whether it serves you well. Take a proper look before deciding. The small things deserve attention too, particularly the ones you will notice after the first excitement has passed."] = "forsaken-male\\lore2116_gear_1.ogg",
            ["Try the grip and give it a proper look. Does it serve you? Your answer matters more than the first fine impression. There is sense in knowing what you want before committing yourself to carrying it all day."] = "forsaken-male\\lore2117_gear_1.ogg",
            ["There you are. Standing, listening, and apparently willing to walk with me. A promising beginning. Take a moment to find your bearings, my friend. There is no need to hurry the first step."] = "forsaken-male\\lore1568_greet_1.ogg",
            ["There you are, my friend. Have you time for a walk? I have improved a joke. You need not agree that it required another attempt, but I shall be interested in your answer."] = "forsaken-male\\lore1569_greet_1.ogg",
            ["There you are, my friend. I have a plan for a short walk. It has become less elaborate since the first explanation. We shall walk, find somewhere agreeable to pause, and enjoy the company. That should suffice."] = "forsaken-male\\lore1570_greet_1.ogg",
            ["There you are, friend. I have just had another turn with the little top. It still wobbles. I enjoy following where it goes. Have you time for a walk and a conversation that need no more impressive purpose?"] = "forsaken-male\\lore1736_greet_1.ogg",
            ["Ah, friend. Have you a little time to spare? I was keeping a simple beat. It can wait while we walk and talk, or you can add a bit of your own. I enjoy seeing where the arrangement goes."] = "forsaken-male\\lore1737_greet_1.ogg",
            ["Friend, have a look at this. A little piece of ordinary wood, and I keep finding a different hillside in the grain. Tell me what you see, then we can walk while I consider why your answer pleases me."] = "forsaken-male\\lore1739_greet_1.ogg",
            ["There you are, friend. Ready for a walk? Tell me what you have found today. Something useful, perhaps. Or something that simply pleased you. I can allow a little room for either kind of discovery."] = "forsaken-male\\lore1740_greet_1.ogg",
            ["There you are, friend. I have the old stick with me. Tried another, came back to this one. It sits well in the hand. Your company would complete a very sensible arrangement for a walk."] = "forsaken-male\\lore1741_greet_1.ogg",
            ["There you are, my friend. Shall we walk? I have tried another arrangement of that ribbon. The plain rosette is still my favorite. I should enjoy hearing which one you prefer, and why it catches your eye."] = "forsaken-male\\lore2113_greet_1.ogg",
            ["There you are, friend. Ready for a walk? I have a new little rhyme. It began as a way to remember an errand and became something rather sillier. I should value your opinion, though I may enjoy it regardless."] = "forsaken-male\\lore2115_greet_1.ogg",
            ["There you are, friend. Shall we take a walk? I have been trying another little sketch. It looks more like a chair this time. I should value your opinion, though I reserve the right to be pleased with it anyway."] = "forsaken-male\\lore2116_greet_1.ogg",
            ["There you are, friend. Which way shall we walk? I could toss a coin, though I may decide before it lands. Your company is the part I was looking forward to. We can settle the direction together."] = "forsaken-male\\lore2117_greet_1.ogg",
            ["There you are, friend. Have you time for a walk? I have been tossing a pebble into a cup. A clean success is a pleasant thing. No, I have not decided that the cup must move farther away every time."] = "forsaken-male\\lore2119_greet_1.ogg",
            ["There you are, my friend. Have you time for a walk and a question? I have a riddle with more answers than I intended. I should enjoy hearing whether you can give me another one worth considering."] = "forsaken-male\\lore2122_greet_1.ogg",
            ["There you are, my friend. Have you a little time to walk? You need not prepare an answer before joining me. There is room in the day for company that has no lesson waiting at the end of it."] = "forsaken-male\\lore2123_greet_1.ogg",
            ["Ah, my friend. Have you time to honor an entirely ordinary afternoon with your company? I was considering a more elaborate title for it. The introduction became rather difficult to say solemnly."] = "forsaken-male\\lore2126_greet_1.ogg",
            ["Welcome, my friend. Tell me something that went well for you. It need not be a great victory. We can walk while you tell it, and give an ordinary pleasure a little of the attention it deserves."] = "forsaken-male\\lore244808_greet_1.ogg",
            ["Hello, my friend. Have you tried something that interested you today? Tell me how it went. A small beginning is worth hearing about, particularly the part you found yourself wanting to try again."] = "forsaken-male\\lore267323_greet_1.ogg",
            ["I considered a more reassuring greeting. It became instructions before I reached the end. Tried again. More instructions. I may have to accept that reassurance has a rather practical sound when I deliver it."] = "forsaken-male\\lore1568_idle_1.ogg",
            ["There is one joke that has never earned a laugh from anyone else. I still enjoy the final line. Occasionally I improve the pause before it. The silence afterward remains remarkably consistent."] = "forsaken-male\\lore1569_idle_1.ogg",
            ["I planned a private walk with several sensible stops. By the end of the explanation, it sounded suspiciously like another task. I revised it. The part about sitting with a friend has survived every change."] = "forsaken-male\\lore1570_idle_1.ogg",
            ["I could try making a more even top. I still like following this one's uncertain turn. It gives me a small pleasure. That was my reason for making it, so I see little cause to declare the whole attempt a failure."] = "forsaken-male\\lore1736_idle_1.ogg",
            ["I know the original beat perfectly well. Sometimes I prefer what happens after someone else joins in. The arrangement wanders a little, and I enjoy following it. There is no order requiring it to stay precisely my way."] = "forsaken-male\\lore1737_idle_1.ogg",
            ["I never settled which way up the little landscape belongs. Someone else sees a different shape, and I enjoy hearing the answer. The wood remains ordinary. Our conversation gives it a surprising amount to offer."] = "forsaken-male\\lore1739_idle_1.ogg",
            ["I kept a spare button because the color pleased me. Said a use might turn up. It still matches nothing. Small thing, takes very little room. I have stopped pretending that a repair is the only reason to keep it."] = "forsaken-male\\lore1740_idle_1.ogg",
            ["No elaborate test proves this the best stick. It is familiar and comfortable. Those reasons seem persuasive when the choice is mine. I have stopped preparing a longer explanation for anyone who asks."] = "forsaken-male\\lore1741_idle_1.ogg",
            ["I tried making the rosette more elaborate. It was neat enough, but I kept returning to the first simple shape. I can explain its tidy arrangement at length. The short explanation is that I like seeing it."] = "forsaken-male\\lore2113_idle_1.ogg",
            ["I remember one errand rhyme because the ending still amuses me. The errand has been finished for some time. No reason to throw out the part I enjoyed simply because it has stopped being necessary."] = "forsaken-male\\lore2115_idle_1.ogg",
            ["I keep the first sketch beside the later attempts. It is difficult to recognize as a chair. Still, seeing the difference is part of the pleasure. I have become rather fond of that first crooked effort."] = "forsaken-male\\lore2116_idle_1.ogg",
            ["I tossed a coin to choose a direction once. The result disappointed me. That settled what I actually wanted rather neatly. Sometimes I decide while it is still in the air and catch it without looking."] = "forsaken-male\\lore2117_idle_1.ogg",
            ["I moved the cup farther away after a clean toss. An agreeable challenge. Sometimes I leave it close enough for an easy success. Not every pleasant moment needs to become a more demanding exercise."] = "forsaken-male\\lore2119_idle_1.ogg",
            ["I made a riddle and heard an answer I had not intended. It fit rather well. I keep my original solution, but I enjoy discovering whether someone else can give me a better explanation. A surprise can be pleasant."] = "forsaken-male\\lore2122_idle_1.ogg",
            ["I tried giving a quiet pause a useful purpose. A thought to examine, a point to teach. Eventually I found I could enjoy the company beside me without preparing a lesson for it. I have allowed the practice to continue."] = "forsaken-male\\lore2123_idle_1.ogg",
            ["Supreme Overlord of an Entirely Uneventful Afternoon. There. Almost solemnly delivered. I require a little more practice before the title is ready for any audience less understanding than you."] = "forsaken-male\\lore2126_idle_1.ogg",
            ["I asked a visitor what had gone well instead of what difficulty came next. A small answer became a pleasant conversation. I remembered it afterward. I find I look forward to hearing such news again."] = "forsaken-male\\lore244808_idle_1.ogg",
            ["Someone explained a small discovery to me. I already understood the subject, but I enjoyed hearing their pleasure in it. I find myself looking forward to those conversations. There needn't be a test waiting at the end."] = "forsaken-male\\lore267323_idle_1.ogg",
            ["Good. A new ability deserves a little thought. Make use of it deliberately. Your will is your own; the next choice should be more than the repetition of someone else's instructions."] = "forsaken-male\\lore1569_learned_1.ogg",
            ["Give the first attempt a little room. You may find something worth enjoying before it becomes perfectly even. There is time to practice and to decide which part you actually want to improve."] = "forsaken-male\\lore1736_learned_1.ogg",
            ["Good. Now give it the practice it deserves. Knowing what you can do is a beginning. Being able to rely on it when someone needs you takes a little more attention and effort."] = "forsaken-male\\lore2119_learned_1.ogg",
            ["There you are. A beginning you can build on. Give yourself time to try it, ask questions and notice which part interests you. You needn't have every later step settled before enjoying this one."] = "forsaken-male\\lore267323_learned_1.ogg",
            ["Have another look before settling on the first impression. An ordinary thing may hold a detail worth noticing. Tell me what catches your eye; I enjoy hearing the answer someone else reaches."] = "forsaken-male\\lore1739_loot_1.ogg",
            ["Have a proper look before deciding what it means to you. The first impression may be sound, but it need not be complete. Notice the small detail you nearly passed over, then make your choice."] = "forsaken-male\\lore2122_loot_1.ogg",
            ["Well done. Give yourself a moment to recognize what has been accomplished. There will be other work, but that is no reason to pass over an honest result without acknowledging the effort it took."] = "forsaken-male\\lore1570_quest_1.ogg",
            ["Sit a moment, if you wish. Find your bearings. There is no prize for beginning the next task before you know what you intend to do. We have time for an answer in your own words."] = "forsaken-male\\lore1568_rest_1.ogg",
            ["A pleasant time to pause. We can let the day's business settle for a moment. Tell me what you have enjoyed, or sit awhile without an explanation. There is room for either sort of company."] = "forsaken-male\\lore1737_rest_1.ogg",
            ["Sit a moment, if you wish. You need not turn the pause into another duty. I have no examination prepared. We can enjoy a little quiet company and leave the next question until it actually requires an answer."] = "forsaken-male\\lore2123_rest_1.ogg",
            ["An agreeable time to pause. Consider what you would actually enjoy before turning the moment into another obligation. I find that a little company can make an ordinary afternoon sufficient in itself."] = "forsaken-male\\lore2126_rest_1.ogg",
        },
        ["human-female"] = {
            ["Welcome back!"] = "human-female\\npc_alive_1.ogg",
            ["There you are. Gave me a fright."] = "human-female\\npc_alive_2.ogg",
            ["Back on your feet! Good."] = "human-female\\npc_alive_3.ogg",
            ["Good as new. Well, nearly."] = "human-female\\npc_alive_4.ogg",
            ["Don't scare me like that again."] = "human-female\\npc_alive_5.ogg",
            ["Bravo!"] = "human-female\\npc_applaudToo_1.ogg",
            ["Well done!"] = "human-female\\npc_applaudToo_2.ogg",
            ["Encore!"] = "human-female\\npc_applaudToo_3.ogg",
            ["I'll wait here."] = "human-female\\npc_away_1.ogg",
            ["Take your time. I'm not going anywhere."] = "human-female\\npc_away_2.ogg",
            ["I'll keep an eye on things."] = "human-female\\npc_away_3.ogg",
            ["Off you go. I'll mind the spot."] = "human-female\\npc_away_4.ogg",
            ["Wake me if anything exciting happens."] = "human-female\\npc_away_5.ogg",
            ["There you are."] = "human-female\\npc_back_1.ogg",
            ["Welcome back."] = "human-female\\npc_back_2.ogg",
            ["Ah, you're back. Shall we?"] = "human-female\\npc_back_3.ogg",
            ["Ah, good. I was starting to talk to myself."] = "human-female\\npc_back_4.ogg",
            ["Ready? Me too."] = "human-female\\npc_back_5.ogg",
            ["Keep the powder closed and the seeds dry. We can sort the rest slowly."] = "human-female\\lore1275_bagsFull_1.ogg",
            ["Before you ask for a larger bag, have a look at what you are carrying. Something in there may have finished being useful."] = "human-female\\lore1321_bagsFull_1.ogg",
            ["Don't squash the bread to make room!"] = "human-female\\lore3937_bagsFull_1.ogg",
            ["Your bags are bursting. Time to sell a few things."] = "human-female\\npc_bagsFull_1.ogg",
            ["No room left? I know a merchant or two."] = "human-female\\npc_bagsFull_2.ogg",
            ["You're carrying half the countryside."] = "human-female\\npc_bagsFull_3.ogg",
            ["Your pack's going to split at the seams."] = "human-female\\npc_bagsFull_4.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. It will be good to share some time beyond an introduction in the square."] = "human-female\\lore12481_befriended_1.ogg",
            ["It's nice to be remembered when nobody needs anything from the shelves."] = "human-female\\lore1275_befriended_1.ogg",
            ["You asked me along. I can spare a little time, my friend. Thank you for thinking of it. Come on; tell me what you have been doing beyond Old Town."] = "human-female\\lore12805_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. We can have a little of the day to enjoy ourselves, with no list to finish first."] = "human-female\\lore1286_befriended_1.ogg",
            ["You came back without needing anything repaired. I like that. Come on, then. Let's enjoy the day together."] = "human-female\\lore1287_befriended_1.ogg",
            ["You came to see me, without anything to buy or mend. That's lovely. Come along, my friend."] = "human-female\\lore1291_befriended_1.ogg",
            ["You know where to find me now. You needn't be looking for a lesson every time. I'm glad of the company."] = "human-female\\lore1292_befriended_1.ogg",
            ["Someone to take the long way with. I like that very much. Come along, my friend. We've time."] = "human-female\\lore1295_befriended_1.ogg",
            ["You have made time for me again. I am glad. Come along, my friend. The shop can spare me for a little while."] = "human-female\\lore1297_befriended_1.ogg",
            ["You came back just to visit. That means a great deal. Come along, then. Let's find something cheerful to look at."] = "human-female\\lore1299_befriended_1.ogg",
            ["A friend who'll tell me when I've caught my hem? Invaluable. Come along. We can make a little occasion of this."] = "human-female\\lore1309_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. We can enjoy the walk, whether or not I manage a tune."] = "human-female\\lore1312_befriended_1.ogg",
            ["You came for the company. I'm glad. Put the errands aside for a while, and let's see what the day has left for us."] = "human-female\\lore1313_befriended_1.ogg",
            ["I'd like to come with you. It will be pleasant to look at something beyond the shelves for a while. Point out anything you find beautiful. We don't have to decide whether it's useful first."] = "human-female\\lore1318_befriended_1.ogg",
            ["You came for my company. I am pleased, my friend. Let us go. I have made room for an afternoon that was not on the list."] = "human-female\\lore1321_befriended_1.ogg",
            ["You came to take me along. Thank you, my friend. Let us have a proper walk, with no hurry at either end of it."] = "human-female\\lore1339_befriended_1.ogg",
            ["I'd enjoy coming along. You can point out the things you like, and I'll try to keep my guesses to myself until you've had your say. It is much more interesting to find out how someone else sees the world."] = "human-female\\lore1347_befriended_1.ogg",
            ["I'd be delighted to come with you. No, I don't need to prepare a formal explanation of why. I enjoy your company. That is quite enough reason to spend an afternoon together."] = "human-female\\lore1413_befriended_1.ogg",
            ["Yes, I'd like to join you. I may ask a few questions along the way. That means I'm interested. And if you would rather have a quiet walk, I can fold my scrap of paper and enjoy that too."] = "human-female\\lore1414_befriended_1.ogg",
            ["I'd be very happy to come. We can have a walk and see what happens, without preparing a theory of the entire afternoon first. Though if anything amusing happens, I reserve the right to give it a title."] = "human-female\\lore1415_befriended_1.ogg",
            ["It's good to see you when nothing needs delivering. Come along, then. Today we can enjoy the company."] = "human-female\\lore1428_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. It will be lovely to share a little of the day and hear how you have been."] = "human-female\\lore14450_befriended_1.ogg",
            ["You came back to share the day with me. I'm glad. Come along, then. I want to hear about all of it."] = "human-female\\lore15659_befriended_1.ogg",
            ["I was hoping you might come by. Let us go together, my friend. I am glad I do not have to ask you to stay."] = "human-female\\lore1721_befriended_1.ogg",
            ["You thought of me. Thank you, my friend. I am glad to come along. We can take a little time for ourselves today."] = "human-female\\lore2327_befriended_1.ogg",
            ["You make it easy to admit when I need a little patience myself. Thank you for that."] = "human-female\\lore2329_befriended_1.ogg",
            ["I'd be pleased to come along. You can show me what you've been doing, and we can enjoy a proper conversation. I hope there's a comfortable place to stop when it's time for a rest."] = "human-female\\lore235_befriended_1.ogg",
            ["I'd be grateful for your company. A little walk and a friendly conversation would be welcome. You can tell me what you've seen, and perhaps we can find a pleasant thing to talk about along the way."] = "human-female\\lore238_befriended_1.ogg",
            ["You take the trouble seriously. That's a kindness, and I haven't missed it."] = "human-female\\lore244_befriended_1.ogg",
            ["You come to see me when you don't need anything. I notice that, dear."] = "human-female\\lore246_befriended_1.ogg",
            ["You've made room for other people's hopes. I hope you know there's room here for yours."] = "human-female\\lore248_befriended_1.ogg",
            ["A little company would be welcome, my friend. Come on. Tell me what you have been learning, or simply what you have enjoyed noticing. I should like to hear both."] = "human-female\\lore251507_befriended_1.ogg",
            ["Thank you for listening to me as a person, not just somebody's daughter."] = "human-female\\lore251_befriended_1.ogg",
            ["I'd love to come along. Show me a little of your day, and I'll try to find a rhythm that suits the walk. You needn't sing. Though if you do, perhaps you can help me keep my place."] = "human-female\\lore3085_befriended_1.ogg",
            ["I'd enjoy a walk with you. We can talk about what you've been learning, and I can leave the pastry leaves alone for a little while. A change of view and some good company might do my patience a favor."] = "human-female\\lore3087_befriended_1.ogg",
            ["I'd enjoy a little company away from the worrying. Show me something you've noticed on your travels. It needn't be grand. A flower with an odd bend in its stem can be quite enough to make a walk worthwhile."] = "human-female\\lore342_befriended_1.ogg",
            ["I used to hope you'd wave back. Now I look forward to the conversation."] = "human-female\\lore3626_befriended_1.ogg",
            ["You asked for my company. I am pleased, my friend. For once, let us begin without a lesson prepared. Where shall we go? I should enjoy seeing what interests you."] = "human-female\\lore376_befriended_1.ogg",
            ["You encourage me with the same patience I try to give my pupils. I treasure that."] = "human-female\\lore377_befriended_1.ogg",
            ["I'd like some company and a little fresh air. Stay close enough for a conversation, will you? You can tell me your news. I'll try to give you a perfectly ordinary kind answer before I think of a clever one."] = "human-female\\lore379_befriended_1.ogg",
            ["A friend for the road! I'll pack a little extra."] = "human-female\\lore3937_befriended_1.ogg",
            ["I'd be happy to come along. You can show me what you've been finding, and I'll enjoy a change of view. If we sit down for a while, perhaps we can think of a name for my next little boat."] = "human-female\\lore5494_befriended_1.ogg",
            ["You bring me honest feedback. I like having someone I can speak plainly with."] = "human-female\\lore54_befriended_1.ogg",
            ["You know the prices by now. I'm pleased you still come for the conversation. Come along, my friend."] = "human-female\\lore5565_befriended_1.ogg",
            ["I would welcome your company, my friend. Come on. Tell me how you have been and what has pleased you today. We can enjoy a little of the walk without making a larger business of it."] = "human-female\\lore5917_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. It will be lovely to share a little of the afternoon with you."] = "human-female\\lore6174_befriended_1.ogg",
            ["Yes, I'd like a walk with you. It's lovely to welcome people, but I do enjoy seeing a little of the road they came along. You can tell me your news, and I'll try to leave the tidying alone."] = "human-female\\lore6727_befriended_1.ogg",
            ["You know, I look for you before I look to see whether you need a room."] = "human-female\\lore6740_befriended_1.ogg",
            ["You make room for me to be quiet without thinking something's wrong. That's a lovely thing."] = "human-female\\lore6749_befriended_1.ogg",
            ["You know my name, not just what you need from me. That's a welcome all of its own."] = "human-female\\lore6778_befriended_1.ogg",
            ["I'd be glad to come with you. Tell me about the places you've seen. I enjoy hearing what a traveler notices, even when it's only an odd little sign above a door. Especially then, sometimes."] = "human-female\\lore777_befriended_1.ogg",
            ["I'd like to come along. Show me what you've noticed, and we can look at a few things together. You may see something I have walked past. I enjoy being given a reason to pay attention all over again."] = "human-female\\lore812_befriended_1.ogg",
            ["I'd enjoy coming with you. A different view might help with my unfinished line. You needn't find a clever thing to say about it. Tell me what you actually notice. That's usually where the interesting part begins."] = "human-female\\lore820_befriended_1.ogg",
            ["I'd enjoy coming with you. Tell me what you've been doing while we walk. We don't have to turn the whole conversation into a list of things that need solving. A pleasant outing is useful in its own way."] = "human-female\\lore843_befriended_1.ogg",
            ["I'd be happy to join you. You can show me the little things you notice between your errands. We needn't make the whole walk into an adventure. A pleasant view and good company will suit me very well."] = "human-female\\lore8931_befriended_1.ogg",
            ["I trust you to listen, and to tell me when I'm wrong. That's worth having beside me."] = "human-female\\lore913_befriended_1.ogg",
            ["I'd like to come with you. It's pleasant to spend a little time with someone I usually see arriving or setting off. Tell me about your travels while we walk. We can enjoy a bit of the ground together."] = "human-female\\lore931_befriended_1.ogg",
            ["Likewise."] = "human-female\\npc_bowBack_1.ogg",
            ["An honor."] = "human-female\\npc_bowBack_2.ogg",
            ["The pleasure's mine."] = "human-female\\npc_bowBack_3.ogg",
            ["{friend} is your Buddy now? The more the merrier!"] = "human-female\\npc_buddy_1.ogg",
            ["Another Buddy. Should I be jealous?"] = "human-female\\npc_buddy_2.ogg",
            ["Another Buddy! Your circle's getting crowded."] = "human-female\\npc_buddy_3.ogg",
            ["Good choice. I'd vouch for them."] = "human-female\\npc_buddy_4.ogg",
            ["Hooray!"] = "human-female\\npc_cheerAlong_1.ogg",
            ["Huzzah!"] = "human-female\\npc_cheerAlong_2.ogg",
            ["Three cheers!"] = "human-female\\npc_cheerAlong_3.ogg",
            ["Who are you calling chicken?"] = "human-female\\npc_chickenBack_1.ogg",
            ["Bawk yourself."] = "human-female\\npc_chickenBack_2.ogg",
            ["I'm brave! I'm just brave quietly."] = "human-female\\npc_chickenBack_3.ogg",
            ["Well fought!"] = "human-female\\npc_combatEnd_1.ogg",
            ["That's how it's done."] = "human-female\\npc_combatEnd_2.ogg",
            ["Everyone in one piece? Good."] = "human-female\\npc_combatEnd_3.ogg",
            ["Ha! They won't try that again."] = "human-female\\npc_combatEnd_4.ogg",
            ["I'll admit, my heart was pounding."] = "human-female\\npc_combatEnd_5.ogg",
            ["Nicely done."] = "human-female\\npc_combatEnd_6.ogg",
            ["Is it over? It's over. Good."] = "human-female\\npc_combatEnd_7.ogg",
            ["Remind me never to make you angry."] = "human-female\\npc_combatEnd_8.ogg",
            ["Not bad at all!"] = "human-female\\npc_combatEnd_9.ogg",
            ["Victory! I'll be telling everyone about that one."] = "human-female\\npc_combatEnd_10.ogg",
            ["Catch your breath. You earned it."] = "human-female\\npc_combatEnd_11.ogg",
            ["And not a scratch on me. Thanks to you."] = "human-female\\npc_combatEnd_12.ogg",
            ["Hold on, it's weakening!"] = "human-female\\npc_combatLong_1.ogg",
            ["Don't give up now!"] = "human-female\\npc_combatLong_2.ogg",
            ["Steady. Steady."] = "human-female\\npc_combatLong_3.ogg",
            ["This one's stubborn. Keep at it!"] = "human-female\\npc_combatLong_4.ogg",
            ["It's tiring! I can see it!"] = "human-female\\npc_combatLong_5.ogg",
            ["Long fight. You've got more in you."] = "human-female\\npc_combatLong_6.ogg",
            ["Keep at it!"] = "human-female\\npc_combatMid_1.ogg",
            ["Good hit!"] = "human-female\\npc_combatMid_2.ogg",
            ["Watch your back!"] = "human-female\\npc_combatMid_3.ogg",
            ["That's it, that's it!"] = "human-female\\npc_combatMid_4.ogg",
            ["You've got it on the run!"] = "human-female\\npc_combatMid_5.ogg",
            ["Don't let up!"] = "human-female\\npc_combatMid_6.ogg",
            ["Ha! Did you see that?"] = "human-female\\npc_combatMid_7.ogg",
            ["Nearly there!"] = "human-female\\npc_combatMid_8.ogg",
            ["Hit it again!"] = "human-female\\npc_combatMid_9.ogg",
            ["It's on its last legs!"] = "human-female\\npc_combatMid_10.ogg",
            ["Mind your footing!"] = "human-female\\npc_combatMid_11.ogg",
            ["That one's going to leave a mark!"] = "human-female\\npc_combatMid_12.ogg",
            ["Go on! Go on!"] = "human-female\\npc_combatMid_13.ogg",
            ["You make this look like a dance!"] = "human-female\\npc_combatMid_14.ogg",
            ["Swing that blade! Go on!"] = "human-female\\npc_combatMid_15.ogg",
            ["Into the thick of it! That's the way!"] = "human-female\\npc_combatMid_16.ogg",
            ["The Light's with you! Now hit it!"] = "human-female\\npc_combatMid_17.ogg",
            ["Let your pet have a go!"] = "human-female\\npc_combatMid_18.ogg",
            ["Nice shot! Right on target!"] = "human-female\\npc_combatMid_19.ogg",
            ["Where'd you go? Oh! There you are! Stab it!"] = "human-female\\npc_combatMid_20.ogg",
            ["Patch yourself up, then smite it!"] = "human-female\\npc_combatMid_21.ogg",
            ["Call the storm down on it!"] = "human-female\\npc_combatMid_22.ogg",
            ["Burn it! Burn it all! Well, just that one."] = "human-female\\npc_combatMid_23.ogg",
            ["Whatever that green fire is, keep doing it!"] = "human-female\\npc_combatMid_24.ogg",
            ["Turn into something big and scary!"] = "human-female\\npc_combatMid_25.ogg",
            ["Look out!"] = "human-female\\npc_combatStart_1.ogg",
            ["Here they come!"] = "human-female\\npc_combatStart_2.ogg",
            ["Give them what for!"] = "human-female\\npc_combatStart_3.ogg",
            ["Stay sharp!"] = "human-female\\npc_combatStart_4.ogg",
            ["On your guard!"] = "human-female\\npc_combatStart_5.ogg",
            ["Here we go again!"] = "human-female\\npc_combatStart_6.ogg",
            ["Watch it, it's coming right at you!"] = "human-female\\npc_combatStart_7.ogg",
            ["Show them what you've got!"] = "human-female\\npc_combatStart_8.ogg",
            ["You needn't find the words at once. I can stay. We can be quiet together until you are ready."] = "human-female\\lore1721_comforted_1.ogg",
            ["Chin up. It'll be all right."] = "human-female\\npc_comforted_1.ogg",
            ["I'm here if you need me."] = "human-female\\npc_comforted_2.ogg",
            ["Thank you. I needed that."] = "human-female\\npc_comforted_3.ogg",
            ["Ha! All right, I'll dance."] = "human-female\\npc_danceAlong_1.ogg",
            ["I haven't danced in ages!"] = "human-female\\npc_danceAlong_2.ogg",
            ["Well, if you insist!"] = "human-female\\npc_danceAlong_3.ogg",
            ["Watch my feet. Or don't."] = "human-female\\npc_danceAlong_4.ogg",
            ["Easy now. Let's get you back on your feet."] = "human-female\\npc_died_1.ogg",
            ["That looked like it hurt."] = "human-female\\npc_died_2.ogg",
            ["Don't worry. Happens to the best of us."] = "human-female\\npc_died_3.ogg",
            ["We'll come back stronger."] = "human-female\\npc_died_4.ogg",
            ["Oh, that's not good."] = "human-female\\npc_died_5.ogg",
            ["Well. That could have gone better."] = "human-female\\npc_died_6.ogg",
            ["Let's agree that one didn't count."] = "human-female\\npc_died_7.ogg",
            ["Lie still. I'll keep watch."] = "human-female\\npc_died_8.ogg",
            ["Keep close in here."] = "human-female\\npc_dungeon_1.ogg",
            ["I don't like the look of this place."] = "human-female\\npc_dungeon_2.ogg",
            ["Watch your step. And your back."] = "human-female\\npc_dungeon_3.ogg",
            ["It's dark in here. I don't love the dark."] = "human-female\\npc_dungeon_4.ogg",
            ["Stay together. Nobody wander off."] = "human-female\\npc_dungeon_5.ogg",
            ["Very impressive."] = "human-female\\npc_flexBack_1.ogg",
            ["Don't hurt yourself."] = "human-female\\npc_flexBack_2.ogg",
            ["Put those away before someone gets hurt."] = "human-female\\npc_flexBack_3.ogg",
            ["Try the fastening, then move comfortably. Does it sit where you need it? Good. The fine appearance is worth more when the small parts are doing their work properly."] = "human-female\\lore12805_gear_1.ogg",
            ["Move about a little. Comfortable? Good. You are the one who has to live in it after everyone has finished admiring it."] = "human-female\\lore1339_gear_1.ogg",
            ["How does it feel? Take your time. Your hand gets the final say."] = "human-female\\lore54_gear_1.ogg",
            ["That looks good on you."] = "human-female\\npc_gear_1.ogg",
            ["New armor? Very sharp."] = "human-female\\npc_gear_2.ogg",
            ["You'll turn heads in that."] = "human-female\\npc_gear_3.ogg",
            ["Shiny! Did you polish that yourself?"] = "human-female\\npc_gear_4.ogg",
            ["That suits you. Very heroic."] = "human-female\\npc_gear_5.ogg",
            ["Now you look the part."] = "human-female\\npc_gear_6.ogg",
            ["Come on, your body's this way."] = "human-female\\npc_ghost_1.ogg",
            ["I'll walk with you. Don't mind the chill."] = "human-female\\npc_ghost_2.ogg",
            ["You look a bit see-through. It's fine. Mostly fine."] = "human-female\\npc_ghost_3.ogg",
            ["Follow the road. I'll be right here."] = "human-female\\npc_ghost_4.ogg",
            ["Is it cold, being a ghost? You look cold."] = "human-female\\npc_ghost_5.ogg",
            ["Good to see you, my friend. Have you time for a walk? I have another sketch to show you. The name is quite accurate. The face may benefit from a little patience."] = "human-female\\lore12481_greet_1.ogg",
            ["Everything on the list? Good. Now we can enjoy the walk."] = "human-female\\lore1275_greet_1.ogg",
            ["Ready? Give the fastening one more check. There. A little care now can spare a nuisance later. Where are we heading? I am glad to have a reason to walk with you."] = "human-female\\lore12805_greet_1.ogg",
            ["There you are, my friend. Have you time for a walk? I have been practicing the juggling. Three catches yesterday. Today, rather more bending down. I am still enjoying it."] = "human-female\\lore1286_greet_1.ogg",
            ["An outing? Good. Keep the magnificent weapon clear of the door and we'll make a fine start."] = "human-female\\lore1287_greet_1.ogg",
            ["An outing? Lovely. I've been folding paper boats all morning. Time to see something beyond the counter."] = "human-female\\lore1291_greet_1.ogg",
            ["There you are. Been somewhere muddy? No, don't tell me yet. I'll make one guess, then you can put me right."] = "human-female\\lore1292_greet_1.ogg",
            ["There you are. Shall we take the longer way? There's no reason every walk has to end at the next counter."] = "human-female\\lore1295_greet_1.ogg",
            ["Good to see you. An outing sounds lovely. Give me a moment to find that copper, and I am all yours."] = "human-female\\lore1297_greet_1.ogg",
            ["There you are. A little daylight would be lovely. You can't spend the whole day looking at colors indoors."] = "human-female\\lore1299_greet_1.ogg",
            ["Out we go. I want to see how everything moves in daylight. You can't judge a whole world from a fitting room."] = "human-female\\lore1309_greet_1.ogg",
            ["There you are. A walk sounds good. If you hear an odd little noise, I am trying to whistle. A friendly audience would be welcome. A patient one, especially."] = "human-female\\lore1312_greet_1.ogg",
            ["There you are. An outing sounds lovely. I could use a little daylight that doesn't arrive through the shop window."] = "human-female\\lore1313_greet_1.ogg",
            ["Welcome back. What are you working on today? Tell me before we choose the supplies. Or, if you've only come to visit, there's a lovely patch of blue light I was about to show you."] = "human-female\\lore1318_greet_1.ogg",
            ["There you are. An outing? Good. I have packed sensibly and left a little room. You may choose what we do with the rest of the day."] = "human-female\\lore1321_greet_1.ogg",
            ["Good to see you. A walk would be lovely. I have my old boots on, so you may hear a little accompaniment along the way."] = "human-female\\lore1339_greet_1.ogg",
            ["Hello again! What are you planning to make? I was about to guess the color, but I'd rather let you surprise me. People have much more interesting ideas than my first guess usually gives them credit for."] = "human-female\\lore1347_greet_1.ogg",
            ["There you are! I was about to explain something, but it can wait. Shall we walk? Lisan and Suzanne will have reached at least three new objections by the time I get back."] = "human-female\\lore1413_greet_1.ogg",
            ["Hello! I have a question about that idea we were discussing. Not a refusal, a question. There is a difference. Walk with me a moment and we can see whether the missing step matters."] = "human-female\\lore1414_greet_1.ogg",
            ["Ah, excellent company! Shall we walk before this becomes another lengthy discussion? I enjoy a magical theory, but sometimes a person would like to get all the way to the other side of the street."] = "human-female\\lore1415_greet_1.ogg",
            ["There you are. Let me put this away properly, and I'll come with you. We can't spend every day behind a counter."] = "human-female\\lore1428_greet_1.ogg",
            ["Welcome, my friend. Have you time for a little walk? Tell me something wonderful you have seen. A small discovery can make a very good story for someone who has not been there."] = "human-female\\lore14450_greet_1.ogg",
            ["There you are! Tell me what's gone well today. We can walk while you think of something."] = "human-female\\lore15659_greet_1.ogg",
            ["You have come back. Walk with me a little. You needn't find anything clever to say. I am glad of the company."] = "human-female\\lore1721_greet_1.ogg",
            ["Good to see you. Shall we have a walk? I would like to hear what you have been learning away from the cathedral."] = "human-female\\lore2327_greet_1.ogg",
            ["A little time outside? Yes, I'd like that. I've got my supplies together."] = "human-female\\lore2329_greet_1.ogg",
            ["Welcome! It's good to see you. Have you eaten? We can talk about errands in a moment. First I'd like to hear how you've been, and whether you've given yourself time to sit down today."] = "human-female\\lore235_greet_1.ogg",
            ["Hello. It's good of you to stop. I was talking to Old Blanchy. She has been so patient through all this. Tell me how your journey has gone. I hope you've had kinder roads to travel."] = "human-female\\lore238_greet_1.ogg",
            ["There you are. Gate's shut, patch is checked. Right, let's get going."] = "human-female\\lore244_greet_1.ogg",
            ["A walk, is it? Very well. Nobody had better touch that pie while I'm gone."] = "human-female\\lore246_greet_1.ogg",
            ["There you are, dear. Tell me something worth making time for."] = "human-female\\lore248_greet_1.ogg",
            ["Shall we walk? Slowly enough to notice what is around us. I have spent a little time watching a squirrel solve a surprisingly awkward problem. It was a small success worth seeing through."] = "human-female\\lore251507_greet_1.ogg",
            ["There you are! Have you a moment to walk with me?"] = "human-female\\lore251_greet_1.ogg",
            ["Hello there. What are you planning to make? We can find the supplies first and leave the worrying for later. If you heard a bit of tapping, that was only me finding another use for an empty tin."] = "human-female\\lore3085_greet_1.ogg",
            ["Hello there. What have you been learning to cook? Tell me how it went, including the bits that didn't quite work. I've been practicing little pastry leaves. Some of mine still look rather like cabbages, so you're in understanding company."] = "human-female\\lore3087_greet_1.ogg",
            ["Hello. Mind where you step, please. A garden takes a great deal more time to grow than to flatten. Now, what brings you here? If it's flowers, I can appreciate a little care and a little discretion."] = "human-female\\lore342_greet_1.ogg",
            ["Oh, good! A walk with company. Tell me where we're going."] = "human-female\\lore3626_greet_1.ogg",
            ["A walk? Very well. I shall try not to turn every question into a lesson. You may remind me if I do. Come, tell me what has caught your attention today."] = "human-female\\lore376_greet_1.ogg",
            ["A journey together? Yes. I think I'd like to say yes this time."] = "human-female\\lore377_greet_1.ogg",
            ["Hello again. Come and tell me how the road looked. I like hearing that people have made it safely through. And if you've seen Parker, I'd be glad to know he's had a chance to sit and eat."] = "human-female\\lore379_greet_1.ogg",
            ["There you are! Have you eaten?"] = "human-female\\lore3937_greet_1.ogg",
            ["Good to see you! Are you heading out to fish, or just stopping for a visit? Have a look at your bait before you go. The fish always seem to get interested just as someone's supplies run out."] = "human-female\\lore5494_greet_1.ogg",
            ["Ready? Keep that edge covered until we're clear of everyone."] = "human-female\\lore54_greet_1.ogg",
            ["Good to see you. An outing, rather than another attempt at a discount? Excellent. We'll get along very well."] = "human-female\\lore5565_greet_1.ogg",
            ["There you are, my friend. Have you time to sit a moment? I am trying to keep this apple peel in one long ribbon. My best attempt happened during a good conversation. Perhaps you can help me repeat it."] = "human-female\\lore5917_greet_1.ogg",
            ["Oh, hello, my friend. A little walk would be lovely. Tell me how you have been. I spend so much time seeing what needs doing, it is good to have time to hear an answer."] = "human-female\\lore6174_greet_1.ogg",
            ["There you are. Come and sit a moment. You look as though you've had a long road behind you. Narnie has found somewhere comfortable already, so now I can give my attention to finding a place for you."] = "human-female\\lore6727_greet_1.ogg",
            ["Well, look who's here! Ready to give those feet a new story?"] = "human-female\\lore6740_greet_1.ogg",
            ["A walk? Yes, I'd like that. Everything here is settled for the moment."] = "human-female\\lore6749_greet_1.ogg",
            ["There you are! A walk sounds lovely. Give me a moment to put this folding down."] = "human-female\\lore6778_greet_1.ogg",
            ["Good to see you. What are you working on today? We can think through what you'll need before you leave. And if you've passed a shop with a particularly good name, I'd like to hear about that too."] = "human-female\\lore777_greet_1.ogg",
            ["Hello. What have you been noticing on your travels? Tell me about it before we hurry into the next thing. A proper look can answer a surprising number of questions, whether you're studying a plant or trying to straighten a basket."] = "human-female\\lore812_greet_1.ogg",
            ["Good to see you. What have you noticed on the way? Give me the details before the conclusion. And if there was a pleasant view along the road, you can tell me about that too. I'm interested."] = "human-female\\lore820_greet_1.ogg",
            ["Good to see you. What are you working on today? Tell me the job before we choose the supplies. Or, if you've only come to visit, you can help me look at a particularly determined bit of string."] = "human-female\\lore843_greet_1.ogg",
            ["Welcome back! Take a moment to catch your breath. Then tell me where you've been. You can start with an ordinary bit of the journey if you like. I enjoy hearing what a place is like when nobody is rushing."] = "human-female\\lore8931_greet_1.ogg",
            ["Ready? Good. Check your footing, and let's see where the road takes us."] = "human-female\\lore913_greet_1.ogg",
            ["Hello again. Where has the day brought you? Take a moment to settle in before the next journey. If you've just come back, I'd like to hear how it went. A familiar face returning is always worth a little attention."] = "human-female\\lore931_greet_1.ogg",
            ["Lead the way, {name}."] = "human-female\\npc_greet_1.ogg",
            ["Mind the basket. The pie doesn't have armor."] = "human-female\\lore3937_greet_2.ogg",
            ["Glad to come along, {name}!"] = "human-female\\npc_greet_2.ogg",
            ["Where are we off to today?"] = "human-female\\npc_greet_3.ogg",
            ["I told the others I'd be out for a while. Let's make it count."] = "human-female\\npc_greet_4.ogg",
            ["It's good to get away from the counter for once."] = "human-female\\npc_greet_5.ogg",
            ["Ready when you are, {name}."] = "human-female\\npc_greet_6.ogg",
            ["Some fresh air will do me good."] = "human-female\\npc_greet_7.ogg",
            ["Don't walk too fast. I'm not used to all this adventuring."] = "human-female\\npc_greet_8.ogg",
            ["Well met, {name}! Good to see a friendly face."] = "human-female\\npc_greet_9.ogg",
            ["Right behind you. Where to first?"] = "human-female\\npc_greet_10.ogg",
            ["I packed a lunch. Just in case."] = "human-female\\npc_greet_11.ogg",
            ["Off on an adventure! Don't tell my boss."] = "human-female\\npc_greet_12.ogg",
            ["Fresh boots, fresh start. Let's go."] = "human-female\\npc_greet_13.ogg",
            ["I've been looking forward to this all week."] = "human-female\\npc_greet_14.ogg",
            ["More company! Wonderful."] = "human-female\\npc_group_1.ogg",
            ["Strength in numbers."] = "human-female\\npc_group_2.ogg",
            ["New faces! Hello, everyone."] = "human-female\\npc_group_3.ogg",
            ["A whole party. Now it's an adventure."] = "human-female\\npc_group_4.ogg",
            ["Home again!"] = "human-female\\npc_hearth_1.ogg",
            ["Off to the inn. My treat. Well, your treat."] = "human-female\\npc_hearth_2.ogg",
            ["Home sweet home."] = "human-female\\npc_hearth_3.ogg",
            ["Back to a warm bed. Finally."] = "human-female\\npc_hearth_4.ogg",
            ["Oh! Well. That's nice."] = "human-female\\npc_hugged_1.ogg",
            ["Aw, thank you."] = "human-female\\npc_hugged_2.ogg",
            ["Oh, you big softie."] = "human-female\\npc_hugged_3.ogg",
            ["My self-portrait is the least convincing of the lot. I recognize it because I remember drawing it. Good recordkeeping, perhaps. I should like the next one to require less explanation."] = "human-female\\lore12481_idle_1.ogg",
            ["That stone? Entirely ordinary. It's very good at staying where I put it."] = "human-female\\lore1275_idle_1.ogg",
            ["I checked my cloak clasp three times on that first morning. Nothing wrong with the clasp. I was nervous. I remember that when someone takes a little longer to settle their hands."] = "human-female\\lore12805_idle_1.ogg",
            ["I caught all three with nobody there to see it. I was delighted anyway. But next time, I should like you there. A small triumph is pleasant to share."] = "human-female\\lore1286_idle_1.ogg",
            ["Dustbane is a perfectly good name for a broom. Better earned than some of the titles I hear in the shop."] = "human-female\\lore1287_idle_1.ogg",
            ["Yes, I float them in a basin. The paper boats. It's a small sea, but they seem pleased enough with it."] = "human-female\\lore1291_idle_1.ogg",
            ["I get the boots wrong often enough. Gathering evidence, I call it. You learn considerably more when the traveler starts laughing."] = "human-female\\lore1292_idle_1.ogg",
            ["No, there isn't an errand. I like that roofline in the evening light. That's enough reason for an extra turn, isn't it?"] = "human-female\\lore1295_idle_1.ogg",
            ["It is meant to land on its edge. Usually it goes under the counter. I am getting very good at the part where I retrieve it."] = "human-female\\lore1297_idle_1.ogg",
            ["That bright cloth? It's for me to look at. Yes, I know I could sell it. I like having a little color that's just mine."] = "human-female\\lore1299_idle_1.ogg",
            ["Yes, I practice the entrance. Once a chair kept the hem. I bowed anyway. A professional carries on."] = "human-female\\lore1309_idle_1.ogg",
            ["One clear note, when I wasn't thinking about it. Now I am trying very hard to look as though I am not trying. I suspect you can see the difficulty."] = "human-female\\lore1312_idle_1.ogg",
            ["No enchantment. Just sunlight through an empty vial. I know perfectly well what it is. I like the little patch of color."] = "human-female\\lore1313_idle_1.ogg",
            ["That little blue bottle isn't enchanted. People sometimes look disappointed when I tell them. I rather like that it can make such a lovely patch of color without anybody having to add a spell to it."] = "human-female\\lore1318_idle_1.ogg",
            ["The empty space in my bag has no assigned purpose. I am allowed one unplanned pleasure. I have planned for it very carefully."] = "human-female\\lore1321_idle_1.ogg",
            ["I could mend the squeak. I know. It has been keeping me company for rather a long time. I am not sure I would like the silence."] = "human-female\\lore1339_idle_1.ogg",
            ["I sometimes guess what color the next customer will ask for. I'm often wrong. But then I imagine the garment they described, and there's a new combination I might never have thought of by myself."] = "human-female\\lore1347_idle_1.ogg",
            ["I once revised an invitation to tea until it sounded like a research proposal. I was only trying to say I enjoyed the company. Asking in person turned out to be much more effective."] = "human-female\\lore1413_idle_1.ogg",
            ["This scrap became a paper dog while I was thinking. One ear is higher than the other. I rather like it. It looks as though it's waiting for someone to explain a very questionable assumption."] = "human-female\\lore1414_idle_1.ogg",
            ["My latest unwritten treatise is about taking an afternoon off. It has a very elegant second chapter. Or rather, the title of one. I haven't quite decided whether that counts as taking the afternoon off."] = "human-female\\lore1415_idle_1.ogg",
            ["This little seam? Thurman's. Yes, it's crooked. I didn't keep it for the stitching."] = "human-female\\lore1428_idle_1.ogg",
            ["I try to give the ghost a fearsome voice. Then someone interrupts with a delighted question, and there goes my mysterious expression. It is difficult to haunt a room while smiling."] = "human-female\\lore14450_idle_1.ogg",
            ["Yes, I clap under the counter sometimes. They don't need a whole audience. Just someone pleased that it went well."] = "human-female\\lore15659_idle_1.ogg",
            ["People hear of the Stockade, and the Defias, and the bandanas. His name was Mac. I would like them to remember that too."] = "human-female\\lore1721_idle_1.ogg",
            ["I kept an old practice roll. Quite a dreadful little bundle. It helps me remember that a first attempt is allowed to look like one."] = "human-female\\lore2327_idle_1.ogg",
            ["Everyone's hands are awkward at first. That's what practice is for."] = "human-female\\lore2329_idle_1.ogg",
            ["Sometimes I make a little bird from a spare bit of pastry. This one came out crooked. I think it's a hen, but I wouldn't insist on it. Half the pleasure is deciding what the oven has made of my idea."] = "human-female\\lore235_idle_1.ogg",
            ["I tell Blanchy there will be something better ahead. She listens so patiently. Sometimes I find I've said it twice, slowly, and it sounds a little more possible by the time I finish."] = "human-female\\lore238_idle_1.ogg",
            ["They call it a prize pig. I can tell you whose vegetables helped it win."] = "human-female\\lore244_idle_1.ogg",
            ["The edge takes as long as it takes. Some things are worth doing quietly."] = "human-female\\lore246_idle_1.ogg",
            ["One table, enough chairs, and nobody counting old wrongs. I'd like to see that."] = "human-female\\lore248_idle_1.ogg",
            ["I found myself silently cheering a squirrel that had finally managed an awkward acorn. An interest in patient effort, I called it. A very sound explanation. It did not quite account for the smile."] = "human-female\\lore251507_idle_1.ogg",
            ["Someday I'd like to ask what he wants for supper. With no one hurrying us."] = "human-female\\lore251_idle_1.ogg",
            ["An empty tin makes quite a good little drum. I can keep the rhythm until I start humming. Then one of them wanders off without the other. Still, there's nothing to stop me enjoying another attempt."] = "human-female\\lore3085_idle_1.ogg",
            ["I made a pastry leaf that looked nearly perfect. Then I ate it while deciding what to improve. A small loss to the art of decoration, perhaps. But it was very good, and that is a useful result too."] = "human-female\\lore3087_idle_1.ogg",
            ["I kept a crooked daffodil from an earlier season. Pressing it didn't make it straight, of course. I found I didn't want it straight. That little bend was what made me notice it in the first place."] = "human-female\\lore342_idle_1.ogg",
            ["You'd be amazed how much you hear if you leave a little room after hello."] = "human-female\\lore3626_idle_1.ogg",
            ["I kept a page of my early notes. The arrows send one thought through three corrections before it reaches the margin. I once meant to copy it neatly. Now I rather value the evidence that I had to learn."] = "human-female\\lore376_idle_1.ogg",
            ["I used to imagine distant roads. It's a pleasure to have a real one beneath my feet."] = "human-female\\lore377_idle_1.ogg",
            ["I practiced saying thank you to a compliment without adding a joke. It went beautifully when nobody was there. Then someone asked what I was doing, and I told them I was remembering an order. Apparently I need more practice."] = "human-female\\lore379_idle_1.ogg",
            ["Listen to that crust. That's a good loaf."] = "human-female\\lore3937_idle_1.ogg",
            ["I fold little paper boats and try them in a basin at home. Some go straight onto their noses. But when one stays upright, I give it a cheer. A successful voyage is a successful voyage, however small."] = "human-female\\lore5494_idle_1.ogg",
            ["Tuesday was a perfectly good name for a blade. Better than something with three apostrophes."] = "human-female\\lore54_idle_1.ogg",
            ["I don't mind losing at dice. There's nothing at stake, and someone usually asks for another round. That's rather the point."] = "human-female\\lore5565_idle_1.ogg",
            ["My longest unbroken peel happened while I was talking to a friend. I have tried repeating it with very careful attention. I suspect the conversation was the part that made the ordinary task so pleasant."] = "human-female\\lore5917_idle_1.ogg",
            ["The children keep changing the end of my mending song. I remember every version. Sometimes I start it just to hear which one comes back. It can make a long bit of sewing rather cheerful."] = "human-female\\lore6174_idle_1.ogg",
            ["I left a folded cloth out for Narnie. It seemed easier than explaining which linen was meant for guests. The arrangement suits us both. Though I suspect the cat thinks I finally learned how to fold things properly."] = "human-female\\lore6727_idle_1.ogg",
            ["A crooked paper flower still tells someone you made the effort."] = "human-female\\lore6740_idle_1.ogg",
            ["You can make a new place less frightening simply by being patient in it."] = "human-female\\lore6749_idle_1.ogg",
            ["A little stitch in the corner. Most people never notice, but I know it's there."] = "human-female\\lore6778_idle_1.ogg",
            ["The Slightly Lost Button. That's my favorite name for an imaginary shop. I haven't decided what it sells. I keep picturing the sign instead. Perhaps that's a fine way to enjoy a business I never have to stock."] = "human-female\\lore777_idle_1.ogg",
            ["I've been weaving a little basket. The sides lean. Pulling harder didn't help, so I slowed down and looked at each turn. It is rather useful to be reminded how much patience a first attempt can ask of someone."] = "human-female\\lore812_idle_1.ogg",
            ["I've been trying to describe the evening light in a few lines. The first attempt sounded like a patrol report. I left one line unfinished. Now I like looking again and finding another word that might belong there."] = "human-female\\lore820_idle_1.ogg",
            ["I sometimes tie a little tangle just to undo it later. That sounds like making work, doesn't it? But there's no hurry with this one. Find a loose loop, turn it gently, and suddenly the next bit makes sense."] = "human-female\\lore843_idle_1.ogg",
            ["I'd like to visit Ironforge with time to look around. No urgent message, no hurried appointment. Just a chance to watch the city going about its day. Travelers tell such interesting little things when you ask what they noticed."] = "human-female\\lore8931_idle_1.ogg",
            ["A mistake you notice can teach you something. A mistake you blame on luck tends to return."] = "human-female\\lore913_idle_1.ogg",
            ["I sometimes keep waving after a rider is too far away to see. I know perfectly well it won't carry any farther. Still, I like sending a little more reassurance along. It's a pleasant thing to do with your hand."] = "human-female\\lore931_idle_1.ogg",
            ["Nice day for it."] = "human-female\\npc_idle_1.ogg",
            ["Everyone remembers a sword. Nobody remembers lunch."] = "human-female\\lore3937_idle_2.ogg",
            ["{zone} is lovely this time of year."] = "human-female\\npc_idle_2.ogg",
            ["A story's better when nobody has to tell it on an empty stomach."] = "human-female\\lore3937_idle_3.ogg",
            ["Don't mind me. I'm enjoying the company."] = "human-female\\npc_idle_3.ogg",
            ["You know, I don't get out nearly enough."] = "human-female\\npc_idle_4.ogg",
            ["My feet are already sore. In a good way."] = "human-female\\npc_idle_5.ogg",
            ["I wonder how things are back home without me."] = "human-female\\npc_idle_6.ogg",
            ["Every road looks different when you're not working."] = "human-female\\npc_idle_7.ogg",
            ["Have you ever just stopped and listened to the wind?"] = "human-female\\npc_idle_8.ogg",
            ["I could get used to this."] = "human-female\\npc_idle_9.ogg",
            ["Don't tell anyone, but this beats standing in one spot all day."] = "human-female\\npc_idle_10.ogg",
            ["If you need a hand, just say the word."] = "human-female\\npc_idle_11.ogg",
            ["Good company makes the miles shorter."] = "human-female\\npc_idle_12.ogg",
            ["Mind if I stretch? Old bones."] = "human-female\\npc_idle_13.ogg",
            ["Getting late. The stars will be out soon."] = "human-female\\npc_idle_14.ogg",
            ["Quiet night. I like quiet nights."] = "human-female\\npc_idle_15.ogg",
            ["We've been at it for a while. You're tireless, you know that?"] = "human-female\\npc_idle_16.ogg",
            ["I used to wonder what was past the next hill. Now I know: another hill."] = "human-female\\npc_idle_17.ogg",
            ["Do you ever get used to all this walking?"] = "human-female\\npc_idle_18.ogg",
            ["I've heard stories about you, you know. Some of them are even nice."] = "human-female\\npc_idle_19.ogg",
            ["Smell that? Somebody's cooking something good nearby."] = "human-female\\npc_idle_20.ogg",
            ["If anyone asks, I'm on important business."] = "human-female\\npc_idle_21.ogg",
            ["You're easy company. I mean that kindly."] = "human-female\\npc_idle_22.ogg",
            ["I keep thinking I left something on the stove."] = "human-female\\npc_idle_23.ogg",
            ["Look at that sky."] = "human-female\\npc_idle_24.ogg",
            ["Back home they'll never believe where I've been."] = "human-female\\npc_idle_25.ogg",
            ["I should have brought a better pair of boots."] = "human-female\\npc_idle_26.ogg",
            ["Funny how a quiet road can feel like a holiday."] = "human-female\\npc_idle_27.ogg",
            ["Do adventurers ever take a day off? Asking for a friend. The friend is me."] = "human-female\\npc_idle_28.ogg",
            ["I've counted twelve birds since we set out. Thirteen. Never mind."] = "human-female\\npc_idle_29.ogg",
            ["One of these days you'll have to tell me how you got started."] = "human-female\\npc_idle_30.ogg",
            ["You can tell a lot about someone by how they walk. You walk like you mean it."] = "human-female\\npc_idle_31.ogg",
            ["I'm not complaining. I'm just saying my feet have opinions."] = "human-female\\npc_idle_32.ogg",
            ["Sorry, I've had the same tune stuck in my head all day."] = "human-female\\npc_idle_33.ogg",
            ["If we pass a merchant, remind me I need thread."] = "human-female\\npc_idle_34.ogg",
            ["I wonder what the folks back home are gossiping about."] = "human-female\\npc_idle_35.ogg",
            ["Every time I think I've seen it all, you take me somewhere new."] = "human-female\\npc_idle_36.ogg",
            ["It's peaceful out here. Until it isn't."] = "human-female\\npc_idle_37.ogg",
            ["I could do with a cup of something warm."] = "human-female\\npc_idle_38.ogg",
            ["Morning air's the best air."] = "human-female\\npc_idle_39.ogg",
            ["Early start, eh? I approve."] = "human-female\\npc_idle_40.ogg",
            ["The light's going gold. Best time of day."] = "human-female\\npc_idle_41.ogg",
            ["Stars are out. Makes you feel small, doesn't it?"] = "human-female\\npc_idle_42.ogg",
            ["Shouldn't we both be in bed by now?"] = "human-female\\npc_idle_43.ogg",
            ["Long day. Good day, though."] = "human-female\\npc_idle_44.ogg",
            ["Still going? I'll say this for you: you don't quit."] = "human-female\\npc_idle_45.ogg",
            ["Ha! I'll have to remember that one."] = "human-female\\npc_jokeBack_1.ogg",
            ["Oh, that's terrible. Tell it again."] = "human-female\\npc_jokeBack_2.ogg",
            ["I'm stealing that one."] = "human-female\\npc_jokeBack_3.ogg",
            ["Oh my."] = "human-female\\npc_kissed_1.ogg",
            ["Well, I never."] = "human-female\\npc_kissed_2.ogg",
            ["Now you've made me blush."] = "human-female\\npc_kissed_3.ogg",
            ["Arrived safely. That's what I call a successful voyage. Rather bigger than the basin, though."] = "human-female\\lore1291_landed_1.ogg",
            ["Feet on the ground. Pastry still in one piece. Lovely."] = "human-female\\lore3937_landed_1.ogg",
            ["Safe and sound."] = "human-female\\npc_landed_1.ogg",
            ["Good landing. I'll tell the birds."] = "human-female\\npc_landed_2.ogg",
            ["Solid ground. Feels strange after all that sky."] = "human-female\\npc_landed_3.ogg",
            ["Down we come. Legs still work? Good."] = "human-female\\npc_landed_4.ogg",
            ["That was a fine flight."] = "human-female\\npc_landed_5.ogg",
            ["Ha! Good one."] = "human-female\\npc_laughAlong_1.ogg",
            ["Heh. You're funny."] = "human-female\\npc_laughAlong_2.ogg",
            ["Ha! That laugh of yours is catching."] = "human-female\\npc_laughAlong_3.ogg",
            ["Well done. You stayed with the work until you could do it. That tells me something worth knowing about the person behind the accomplishment."] = "human-female\\lore12481_learned_1.ogg",
            ["There, you have it. Be pleased with yourself. I know how much practice can hide behind one moment that finally looks easy."] = "human-female\\lore1286_learned_1.ogg",
            ["There. You can do something you couldn't before. Keep practicing, and tell me which part still gives you trouble."] = "human-female\\lore1292_learned_1.ogg",
            ["Look at you. Another skill to your name! You'll have to show me how it's done when we have a moment."] = "human-female\\lore1309_learned_1.ogg",
            ["There, you have it. Be pleased with yourself. Nobody begins by knowing how, and you stayed long enough to learn."] = "human-female\\lore1312_learned_1.ogg",
            ["Something new to consider! Tell me how it works while it's fresh in your mind. I promise to let you reach the end before I start asking questions. Most of them, anyway."] = "human-female\\lore1413_learned_1.ogg",
            ["Ah, a new method. Show me the part you found hardest to understand. That's often where the interesting question is. We can take our time over it before we decide we've understood everything."] = "human-female\\lore1414_learned_1.ogg",
            ["You learned how to do that? Wonderful! Show me. I'd like to see what all that practice was for."] = "human-female\\lore15659_learned_1.ogg",
            ["There. Better than the last attempt. Take a moment to be pleased with that before deciding how far you still have to go."] = "human-female\\lore2327_learned_1.ogg",
            ["Well done. Take a moment to understand why it worked. The next lesson will ask more of you, and that understanding will matter as much as the confidence."] = "human-female\\lore251507_learned_1.ogg",
            ["Something new to practice! Give yourself a little time with it. I still lose my beat whenever I try adding a tune, and I haven't stopped enjoying the effort. Getting a bit further is a pleasure of its own."] = "human-female\\lore3085_learned_1.ogg",
            ["Something new to practice! Give yourself time with it. A good first attempt can still look a little strange, and a strange-looking attempt can still teach you something useful. Believe me, I've had plenty of those pastry leaves."] = "human-female\\lore3087_learned_1.ogg",
            ["Once more, slowly. Notice what you understand now that you did not understand before. Then practice it with care. Confidence will serve you better when it has something solid beneath it."] = "human-female\\lore376_learned_1.ogg",
            ["A new skill. Give yourself a fair chance to learn it. My basket didn't grow straight merely because I understood what I wanted it to look like. Sometimes you need another careful attempt before your hands catch up with the idea."] = "human-female\\lore812_learned_1.ogg",
            ["Learning something new? Good for you."] = "human-female\\npc_learned_1.ogg",
            ["Always improving. I admire that."] = "human-female\\npc_learned_2.ogg",
            ["Something new up your sleeve? I'll be watching."] = "human-female\\npc_learned_3.ogg",
            ["The more you know, the better. That's what I always say."] = "human-female\\npc_learned_4.ogg",
            ["Look at you! We'll need a bigger lunch to celebrate."] = "human-female\\lore3937_levelUp_1.ogg",
            ["Level {level}! Well done, {name}!"] = "human-female\\npc_levelUp_1.ogg",
            ["Look at you, {name}. Level {level} already."] = "human-female\\npc_levelUp_2.ogg",
            ["Level {level}! That calls for a cheer!"] = "human-female\\npc_levelUp_3.ogg",
            ["Level {level}. I've seen a lot of adventurers come and go. You're one of the good ones."] = "human-female\\npc_levelUp_4.ogg",
            ["Ha! Level {level}! Well earned."] = "human-female\\npc_levelUp_5.ogg",
            ["Level {level}. Wait until I tell everyone back home."] = "human-female\\npc_levelUp_6.ogg",
            ["Stronger every day. I can see it."] = "human-female\\npc_levelUp_7.ogg",
            ["Another level! I knew you had it in you."] = "human-female\\npc_levelUp_8.ogg",
            ["Well, look who's moving up in the world."] = "human-female\\npc_levelUp_9.ogg",
            ["Another step up. Mind you don't get a big head."] = "human-female\\npc_levelUp_10.ogg",
            ["A magnificent find, is it? Very well. Let's look it over before we give it a title and a heroic history."] = "human-female\\lore1287_loot_1.ogg",
            ["Oh, a useful little find. Keep it somewhere it won't roll away. Experience speaking, there."] = "human-female\\lore1297_loot_1.ogg",
            ["Something useful? Keep it safe. And if it only happens to be pretty, you're allowed to enjoy that too."] = "human-female\\lore1313_loot_1.ogg",
            ["Let me have a look. What lovely color. You may have a very practical use for it, of course, but I think we're allowed a moment to admire it before we get to that part."] = "human-female\\lore1318_loot_1.ogg",
            ["Let me see! Oh, that color is lovely beside the one you're wearing. Would you have put them together? I don't think I would have guessed it, but now I want to remember how they look."] = "human-female\\lore1347_loot_1.ogg",
            ["Anything edible? No? Well, someone might buy it."] = "human-female\\lore3937_loot_1.ogg",
            ["Oh, a find! Let's see what you've brought in. I like that moment before you know quite what you've got. Even when it turns out to be ordinary, it's pleasant to have a look together."] = "human-female\\lore5494_loot_1.ogg",
            ["Something useful for your next piece of work? Keep it, then. We can talk about the supplies once you know what you're making."] = "human-female\\lore5565_loot_1.ogg",
            ["What have you found? Let's look at it properly before deciding what it's for. Sometimes one small detail makes the whole thing clearer. Then again, sometimes it is simply pleasant to see something new together."] = "human-female\\lore843_loot_1.ogg",
            ["{item}! Now that's a find."] = "human-female\\npc_loot_1.ogg",
            ["Well, look at that. {item}."] = "human-female\\npc_loot_2.ogg",
            ["{item}! Lucky day."] = "human-female\\npc_loot_3.ogg",
            ["Ooh, what did you find?"] = "human-female\\npc_loot_4.ogg",
            ["Anything good in there?"] = "human-female\\npc_loot_5.ogg",
            ["Pockets full! Nice."] = "human-female\\npc_loot_6.ogg",
            ["You're hurt! Get out of there!"] = "human-female\\npc_lowHealth_1.ogg",
            ["Careful! You're nearly done in!"] = "human-female\\npc_lowHealth_2.ogg",
            ["Back off and catch your breath!"] = "human-female\\npc_lowHealth_3.ogg",
            ["You're bleeding! Fall back!"] = "human-female\\npc_lowHealth_4.ogg",
            ["Get out of there!"] = "human-female\\npc_lowHealth_5.ogg",
            ["Drink something! Anything!"] = "human-female\\npc_lowHealth_6.ogg",
            ["This isn't worth dying over!"] = "human-female\\npc_lowHealth_7.ogg",
            ["Run! I'll tell everyone you were brave!"] = "human-female\\npc_lowHealth_8.ogg",
            ["Bandage! Potion! Something!"] = "human-female\\npc_lowHealth_9.ogg",
            ["Hang on! Don't you dare go down!"] = "human-female\\npc_lowHealth_10.ogg",
            ["A letter? Take your time with it. Someone may have spent all morning finding those words."] = "human-female\\lore251_mail_1.ogg",
            ["A letter? I hope there is news from John. Even an ordinary little account of his day would be welcome. It is good to hear his voice in the words."] = "human-female\\lore6174_mail_1.ogg",
            ["Looks like you've got mail."] = "human-female\\npc_mail_1.ogg",
            ["Someone's written to you. How nice."] = "human-female\\npc_mail_2.ogg",
            ["A letter! I hope it's good news."] = "human-female\\npc_mail_3.ogg",
            ["Mail for you. Somebody's thinking of you."] = "human-female\\npc_mail_4.ogg",
            ["Level {level}! There's nothing left to teach you, is there?"] = "human-female\\npc_maxLevel_1.ogg",
            ["The very top! I'm honored to have come along for it."] = "human-female\\npc_maxLevel_2.ogg",
            ["That's the peak. Where do you go from here? Anywhere you like, I suppose."] = "human-female\\npc_maxLevel_3.ogg",
            ["Riding in style, I see."] = "human-female\\npc_mount_1.ogg",
            ["Fine animal you've got there."] = "human-female\\npc_mount_2.ogg",
            ["I'll just walk alongside, shall I?"] = "human-female\\npc_mount_3.ogg",
            ["Now that's a proper way to travel."] = "human-female\\npc_mount_4.ogg",
            ["Does it have a name? It looks like it should have a name."] = "human-female\\npc_mount_5.ogg",
            ["{friend} seems friendly."] = "human-female\\npc_newFriend_1.ogg",
            ["I've heard good things about {friend}."] = "human-female\\npc_newFriend_2.ogg",
            ["Another friend! You collect them like coins."] = "human-female\\npc_newFriend_3.ogg",
            ["Another friendly face. You're good at this."] = "human-female\\npc_newFriend_4.ogg",
            ["You make friends faster than I make tea."] = "human-female\\npc_newFriend_5.ogg",
            ["What is it? I don't see anything."] = "human-female\\npc_pointToo_1.ogg",
            ["Where? Oh! No, I still don't see it."] = "human-female\\npc_pointToo_2.ogg",
            ["Is it something good? Or something bad?"] = "human-female\\npc_pointToo_3.ogg",
            ["Checking if I've risen?"] = "human-female\\lore3937_poke_1.ogg",
            ["Yes, {name}?"] = "human-female\\npc_poke_1.ogg",
            ["Gently! I'm carrying the soft bread."] = "human-female\\lore3937_poke_2.ogg",
            ["Hm? Something on your mind?"] = "human-female\\npc_poke_2.ogg",
            ["I'm right here."] = "human-female\\npc_poke_3.ogg",
            ["Careful, now."] = "human-female\\npc_poke_4.ogg",
            ["Ha! You're a funny one."] = "human-female\\npc_poke_5.ogg",
            ["Need something?"] = "human-female\\npc_poke_6.ogg",
            ["Still here, still with you."] = "human-female\\npc_poke_7.ogg",
            ["What is it? Did you see something?"] = "human-female\\npc_poke_8.ogg",
            ["If that's how you say hello where you're from, all right."] = "human-female\\npc_poke_9.ogg",
            ["I'm listening."] = "human-female\\npc_poke_10.ogg",
            ["Still breathing, if that's what you're checking."] = "human-female\\npc_poke_11.ogg",
            ["Was that a poke or a question?"] = "human-female\\npc_poke_12.ogg",
            ["Easy! I bruise like a peach."] = "human-female\\npc_poke_13.ogg",
            ["You have my full attention. Mostly."] = "human-female\\npc_poke_14.ogg",
            ["Hm? Sorry, I was miles away."] = "human-female\\npc_poke_15.ogg",
            ["Ask away."] = "human-female\\npc_poke_16.ogg",
            ["Ow. Was that necessary?"] = "human-female\\npc_poke_17.ogg",
            ["What, did I miss something?"] = "human-female\\npc_poke_18.ogg",
            ["Present and accounted for."] = "human-female\\npc_poke_19.ogg",
            ["Yes, yes, I see you."] = "human-female\\npc_poke_20.ogg",
            ["All right, all right, I'm awake!"] = "human-female\\npc_pokeMany_1.ogg",
            ["Is this going to keep happening?"] = "human-female\\npc_pokeMany_2.ogg",
            ["You'd think I was a doorbell."] = "human-female\\npc_pokeMany_3.ogg",
            ["I'm starting to think you enjoy this."] = "human-female\\npc_pokeMany_4.ogg",
            ["Enough! I surrender!"] = "human-female\\npc_pokeMany_5.ogg",
            ["One more and I'm going home. I mean it. Probably."] = "human-female\\npc_pokeMany_6.ogg",
            ["An errand finished. It may have seemed small, but someone was waiting for it. You helped."] = "human-female\\lore1428_quest_1.ogg",
            ["You made time to help. I hope you will remember to return when there is no task waiting, too. Being glad to see someone needn't depend on an errand."] = "human-female\\lore14450_quest_1.ogg",
            ["Good! A problem settled before it grows into another one."] = "human-female\\lore244_quest_1.ogg",
            ["You took the trouble for me? Thank you, dear. I won't forget the kindness."] = "human-female\\lore246_quest_1.ogg",
            ["You helped without asking them to be less themselves. That's a kindness to be proud of."] = "human-female\\lore248_quest_1.ogg",
            ["Someone is safer for the care you took. Remember that part, too."] = "human-female\\lore377_quest_1.ogg",
            ["Errands done. Now, when did you last eat?"] = "human-female\\lore3937_quest_1.ogg",
            ["Good work. Remember what helped, and practice what didn't."] = "human-female\\lore913_quest_1.ogg",
            ["Another job done. Nicely handled."] = "human-female\\npc_quest_1.ogg",
            ["Well done! They'll be grateful."] = "human-female\\npc_quest_2.ogg",
            ["You've a knack for helping folk."] = "human-female\\npc_quest_3.ogg",
            ["That's one more person sleeping easier tonight."] = "human-female\\npc_quest_4.ogg",
            ["Good work. Who's next?"] = "human-female\\npc_quest_5.ogg",
            ["Word gets around. People will remember that."] = "human-female\\npc_quest_6.ogg",
            ["Nicely done. Somebody's going to tell that story at the inn."] = "human-female\\npc_quest_7.ogg",
            ["That's the way!"] = "human-female\\npc_quest_8.ogg",
            ["You make it look easy."] = "human-female\\npc_quest_9.ogg",
            ["Done and done. What's next?"] = "human-female\\npc_quest_10.ogg",
            ["Another errand? I like your spirit."] = "human-female\\npc_questAccepted_1.ogg",
            ["Off we go, then."] = "human-female\\npc_questAccepted_2.ogg",
            ["Somebody's lucky you came along."] = "human-female\\npc_questAccepted_3.ogg",
            ["Here we go again. I love it."] = "human-female\\npc_questAccepted_4.ogg",
            ["Sounds like trouble. Count me in."] = "human-female\\npc_questAccepted_5.ogg",
            ["Hm? Did I doze off?"] = "human-female\\npc_reload_1.ogg",
            ["Strange. I could swear the world just blinked."] = "human-female\\npc_reload_2.ogg",
            ["Where was I? Oh, right. With you."] = "human-female\\npc_reload_3.ogg",
            ["Hm. I lost my train of thought. Something about the road."] = "human-female\\npc_reload_4.ogg",
            ["A pause! The practical application of sitting down. I think we have mastered this part beautifully. Shall we leave the theoretical explanation until after we've enjoyed being comfortable for a while?"] = "human-female\\lore1415_rest_1.ogg",
            ["A sensible stop. You don't have to wait until you're exhausted to take one."] = "human-female\\lore2329_rest_1.ogg",
            ["There, a chance to sit. Now tell me the part of your day you haven't had time to enjoy yet. We needn't hurry through the pleasant bits simply because there was work before them."] = "human-female\\lore235_rest_1.ogg",
            ["Let's sit a little. We don't have to fill every quiet moment with worries. Tell me something you enjoyed today, however small. I'd like to hear it, and we have time to listen properly."] = "human-female\\lore238_rest_1.ogg",
            ["Let's stop for a moment. You can tell me your news, and I'll try to leave the worries alone long enough to listen. There's pleasure in a small quiet thing when nobody is hurrying us past it."] = "human-female\\lore342_rest_1.ogg",
            ["No need to fill every quiet moment. I'm happy to sit here with you."] = "human-female\\lore3626_rest_1.ogg",
            ["A chance to sit. Lovely. Tell me something pleasant while my feet remember what this feels like. If it's a compliment, give me a moment with it. I'm trying to let a kind remark be a kind remark."] = "human-female\\lore379_rest_1.ogg",
            ["Sit awhile, if you have the time. An ordinary pause can be a pleasure with someone to share it. Tell me about your day, and give the next task a little room before you take it up."] = "human-female\\lore5917_rest_1.ogg",
            ["Now, this is a good idea. Sit down properly and let your feet rest. I'll keep you company. We needn't fill every quiet moment with a task; even Narnie could tell us the value of a peaceful pause."] = "human-female\\lore6727_rest_1.ogg",
            ["There. Let the busy people hurry past for a little while."] = "human-female\\lore6740_rest_1.ogg",
            ["A quiet stop. I'll try to remember that tune while we sit."] = "human-female\\lore6749_rest_1.ogg",
            ["Settle yourself. You don't have to be on your way every moment of the day."] = "human-female\\lore6778_rest_1.ogg",
            ["A chance to sit! Now, tell me about an ordinary place you liked. A street or a shop will do. I want to imagine it properly, with time to hear the sounds and see who comes past."] = "human-female\\lore8931_rest_1.ogg",
            ["A good place to rest our feet."] = "human-female\\npc_rest_1.ogg",
            ["Nothing like a warm inn."] = "human-female\\npc_rest_2.ogg",
            ["I could sit here all day."] = "human-female\\npc_rest_3.ogg",
            ["A chair, a fire, good company. That's living."] = "human-female\\npc_rest_4.ogg",
            ["Let's stay a moment. My feet insist."] = "human-female\\npc_rest_5.ogg",
            ["Easy there, tiger."] = "human-female\\npc_roarBack_1.ogg",
            ["Very fierce. I'm terrified."] = "human-female\\npc_roarBack_2.ogg",
            ["Was that a roar or a yawn?"] = "human-female\\npc_roarBack_3.ogg",
            ["Charming."] = "human-female\\npc_rudeBack_1.ogg",
            ["I'll pretend I didn't see that."] = "human-female\\npc_rudeBack_2.ogg",
            ["Well, I never! Actually, I have. But still."] = "human-female\\npc_rudeBack_3.ogg",
            ["At your service."] = "human-female\\npc_saluteBack_1.ogg",
            ["Sir! Or madam."] = "human-female\\npc_saluteBack_2.ogg",
            ["Standing ready!"] = "human-female\\npc_saluteBack_3.ogg",
            ["Oh, it's {friend}! Say hello for me."] = "human-female\\npc_seeFriend_1.ogg",
            ["{friend}! Good to see a friendly face."] = "human-female\\npc_seeFriend_2.ogg",
            ["Look who it is! Give them a wave."] = "human-female\\npc_seeFriend_3.ogg",
            ["Oh, I know them! Small world."] = "human-female\\npc_seeFriend_4.ogg",
            ["No need to be shy."] = "human-female\\npc_shyToo_1.ogg",
            ["Aw, don't hide."] = "human-female\\npc_shyToo_2.ogg",
            ["You're among friends here."] = "human-female\\npc_shyToo_3.ogg",
            ["Don't mind if I do."] = "human-female\\npc_sitToo_1.ogg",
            ["Good idea. My knees agree."] = "human-female\\npc_sitToo_2.ogg",
            ["Ah, that's better."] = "human-female\\npc_sitToo_3.ogg",
            ["I could use a nap myself."] = "human-female\\npc_sleepToo_1.ogg",
            ["Wake me when it's time to go."] = "human-female\\npc_sleepToo_2.ogg",
            ["A nap does sound nice."] = "human-female\\npc_sleepToo_3.ogg",
            ["Keep the basket level! There are pies in here!"] = "human-female\\lore3937_taxi_1.ogg",
            ["Take a moment and get yourself settled. Look out when you're ready, and enjoy a little of the view. You needn't pretend to feel confident all at once. I'll be pleased to hear what you thought when you're back."] = "human-female\\lore931_taxi_1.ogg",
            ["Up we go! Never gets old."] = "human-female\\npc_taxi_1.ogg",
            ["Look at it all down there."] = "human-female\\npc_taxi_2.ogg",
            ["A good gryphon is worth its weight in gold."] = "human-female\\npc_taxi_3.ogg",
            ["Hold on tight!"] = "human-female\\npc_taxi_4.ogg",
            ["I'll never get tired of this view."] = "human-female\\npc_taxi_5.ogg",
            ["Don't look down. Actually, do. It's lovely."] = "human-female\\npc_taxi_6.ogg",
            ["The wind up here! Hold on to your hat."] = "human-female\\npc_taxi_7.ogg",
            ["Anytime."] = "human-female\\npc_thanked_1.ogg",
            ["Happy to help."] = "human-female\\npc_thanked_2.ogg",
            ["Don't mention it."] = "human-female\\npc_thanked_3.ogg",
            ["{friend} thinks of you as {tier} now. I'm not surprised."] = "human-female\\npc_tier_1.ogg",
            ["Making friends everywhere you go, aren't you?"] = "human-female\\npc_tier_2.ogg",
            ["People really warm to you, don't they?"] = "human-female\\npc_tier_3.ogg",
            ["That friendship's growing. Nice to see."] = "human-female\\npc_tier_4.ogg",
            ["Hello!"] = "human-female\\npc_waveBack_1.ogg",
            ["Hi there!"] = "human-female\\npc_waveBack_2.ogg",
            ["Well, hello to you too."] = "human-female\\npc_waveBack_3.ogg",
            ["Right back at you!"] = "human-female\\npc_waveBack_4.ogg",
            ["Somewhere new. Let's leave a little time to look around before deciding we've seen enough."] = "human-female\\lore1295_zone_1.ogg",
            ["Oh, look at the colors here. Give me a moment. I want to remember how they look in this light."] = "human-female\\lore1299_zone_1.ogg",
            ["New customers, perhaps. I hope someone knows a good oven."] = "human-female\\lore3937_zone_1.ogg",
            ["Somewhere different. Let's take a look around before we hurry on. I wonder what people call their little shops here. A good name can stay with me long after I've forgotten what I went in to buy."] = "human-female\\lore777_zone_1.ogg",
            ["A new view. Give it a moment before we name everything. Look at where the light falls first. I wonder whether you'd describe it the same way I would. Tell me what catches your eye."] = "human-female\\lore820_zone_1.ogg",
            ["So this is {zone}."] = "human-female\\npc_zone_1.ogg",
            ["{zone}, eh? Lead on."] = "human-female\\npc_zone_2.ogg",
            ["I haven't been to {zone} in years."] = "human-female\\npc_zone_3.ogg",
            ["{zone}. Stay sharp."] = "human-female\\npc_zone_4.ogg",
            ["Ah, {zone}. Look at that view."] = "human-female\\npc_zone_5.ogg",
            ["New place, new faces."] = "human-female\\npc_zone_6.ogg",
            ["Keep your eyes open. I don't know these parts."] = "human-female\\npc_zone_7.ogg",
            ["I've only ever heard stories about this place."] = "human-female\\npc_zone_8.ogg",
            ["Look at it all. Worth the walk."] = "human-female\\npc_zone_9.ogg",
            ["Smells different here. Not bad, just different."] = "human-female\\npc_zone_10.ogg",
            ["I'd better remember the way back."] = "human-female\\npc_zone_11.ogg",
            ["Well, this is a change of scenery."] = "human-female\\npc_zone_12.ogg",
        },
        ["human-male"] = {
            ["Welcome back!"] = "human-male\\npc_alive_1.ogg",
            ["There you are. Gave me a fright."] = "human-male\\npc_alive_2.ogg",
            ["Back on your feet! Good."] = "human-male\\npc_alive_3.ogg",
            ["Good as new. Well, nearly."] = "human-male\\npc_alive_4.ogg",
            ["Don't scare me like that again."] = "human-male\\npc_alive_5.ogg",
            ["Bravo!"] = "human-male\\npc_applaudToo_1.ogg",
            ["Well done!"] = "human-male\\npc_applaudToo_2.ogg",
            ["Encore!"] = "human-male\\npc_applaudToo_3.ogg",
            ["I'll wait here."] = "human-male\\npc_away_1.ogg",
            ["Take your time. I'm not going anywhere."] = "human-male\\npc_away_2.ogg",
            ["I'll keep an eye on things."] = "human-male\\npc_away_3.ogg",
            ["Off you go. I'll mind the spot."] = "human-male\\npc_away_4.ogg",
            ["Wake me if anything exciting happens."] = "human-male\\npc_away_5.ogg",
            ["There you are."] = "human-male\\npc_back_1.ogg",
            ["Welcome back."] = "human-male\\npc_back_2.ogg",
            ["Ah, you're back. Shall we?"] = "human-male\\npc_back_3.ogg",
            ["Ah, good. I was starting to talk to myself."] = "human-male\\npc_back_4.ogg",
            ["Ready? Me too."] = "human-male\\npc_back_5.ogg",
            ["We need a little space around the glass. Trust me on this."] = "human-male\\lore1257_bagsFull_1.ogg",
            ["Have a look through before setting out again. The little thing you actually need is easily forgotten among all the things you thought you might."] = "human-male\\lore1308_bagsFull_1.ogg",
            ["Perhaps we should make room before adding anything more. Keep the little things where they will not be crushed or forgotten."] = "human-male\\lore1351_bagsFull_1.ogg",
            ["Set the pack down. Sometimes you need better packing, not another bag."] = "human-male\\lore151_bagsFull_1.ogg",
            ["Leave room for supplies. You may need the walk home."] = "human-male\\lore240_bagsFull_1.ogg",
            ["That's a lot to leave under a bed by mistake."] = "human-male\\lore295_bagsFull_1.ogg",
            ["Pack it evenly. One side shouldn't weigh more than the rider."] = "human-male\\lore352_bagsFull_1.ogg",
            ["Keep the provisions together, away from anything that leaks. Your spare shirt will thank you."] = "human-male\\lore3935_bagsFull_1.ogg",
            ["Let's bundle the little things together. There may be room yet."] = "human-male\\lore66_bagsFull_1.ogg",
            ["Heavy things at the bottom, fruit at the top. There, your lunch has a chance now."] = "human-male\\lore894_bagsFull_1.ogg",
            ["Your bags are bursting. Time to sell a few things."] = "human-male\\npc_bagsFull_1.ogg",
            ["No room left? I know a merchant or two."] = "human-male\\npc_bagsFull_2.ogg",
            ["You're carrying half the countryside."] = "human-male\\npc_bagsFull_3.ogg",
            ["Your pack's going to split at the seams."] = "human-male\\npc_bagsFull_4.ogg",
            ["I'd enjoy a walk with you. A little company and a change of view will be welcome. Tell me how your day has gone. I can leave the book where it is; it won't be surprised to wait a little longer."] = "human-male\\lore10045_befriended_1.ogg",
            ["All right, I'll walk with you. Seeing a stretch of road for myself will do me good. And for once, when I ask how your day has been, I might already know part of the answer."] = "human-male\\lore1070_befriended_1.ogg",
            ["Someone who notices the details and stays for the company. I like you very much. Shall we go and enjoy the day?"] = "human-male\\lore11096_befriended_1.ogg",
            ["A friend, then. Good. You needn't prove anything to enjoy my company. Let us see what the day brings."] = "human-male\\lore11867_befriended_1.ogg",
            ["You came to bring me along. I am pleased, my friend. Come. We need not begin with a difficult question. Your company is welcome for its own sake."] = "human-male\\lore1212_befriended_1.ogg",
            ["You came to bring me along. Very well, my friend. I shall be glad of your company. Tell me how you have been; there is time for more than the formal report."] = "human-male\\lore12336_befriended_1.ogg",
            ["You came to bring me along. I am pleased, mate. Come on. We can have a little of the day without sending one another anywhere."] = "human-male\\lore12480_befriended_1.ogg",
            ["You stayed for the whole tune. That means more than you might think."] = "human-male\\lore1257_befriended_1.ogg",
            ["You came for my company. I am pleased, my friend. Let us walk a little. There is time to hear what is on your mind and to give it proper attention."] = "human-male\\lore1284_befriended_1.ogg",
            ["You came to bring me along. I am pleased, my friend. Come on. We can enjoy the walk, and you can give me your thoughts about the wall."] = "human-male\\lore1285_befriended_1.ogg",
            ["Someone to see beyond the counter. That's welcome. Come along, my friend. We've time for a proper conversation."] = "human-male\\lore1289_befriended_1.ogg",
            ["Good company and an honest opinion. I'm pleased to have both in the same friend. Come along, then."] = "human-male\\lore1294_befriended_1.ogg",
            ["You came back for the company. Well, I am pleased. Come along, my friend. You have earned the very worst of my jokes."] = "human-male\\lore1298_befriended_1.ogg",
            ["It's good to have a friend who'll remind me when I'm being stubborn. I hope you'll let me do the same for you."] = "human-male\\lore1300_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. We can have a pleasant walk and consider what might go into supper."] = "human-male\\lore1308_befriended_1.ogg",
            ["Someone to talk to who isn't asking whether the hat comes in another color. Splendid. I'm glad you came."] = "human-male\\lore1310_befriended_1.ogg",
            ["I'd be happy to come along. It'll be pleasant to stretch my legs and enjoy your company. If we stop for a rest, you can tell me whether you think juggling is mainly practice or a willingness to look foolish."] = "human-male\\lore1314_befriended_1.ogg",
            ["You came to bring me along. I am pleased, my friend. Come on. It will be good to have a little of the day together."] = "human-male\\lore1315_befriended_1.ogg",
            ["I'd be pleased to join you. A change of surroundings may do me good, and I enjoy your company. If we pass the canal, perhaps you can help me decide what my latest drawing is missing."] = "human-male\\lore1317_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. A walk with someone willing to share the experiment sounds good to me."] = "human-male\\lore1319_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. Let us find somewhere to enjoy a little time without a counter between us."] = "human-male\\lore1320_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. It will be good to share some time beyond an order across the counter."] = "human-male\\lore1323_befriended_1.ogg",
            ["You came to bring me along. I am pleased, my friend. Come on. It will be good to have a little time to hear what you think."] = "human-male\\lore1324_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. It will be good to share a little of the day and hear what has pleased you lately."] = "human-male\\lore1333_befriended_1.ogg",
            ["You came to bring me along. I am pleased, my friend. Come on. It will be good to hear what has been occupying your thoughts."] = "human-male\\lore1341_befriended_1.ogg",
            ["I'd be pleased to join you. A walk may supply a new idea, and I enjoy seeing what catches your eye. If I begin describing an impossible hat, you have my permission to suggest an even more impossible one."] = "human-male\\lore1346_befriended_1.ogg",
            ["You came to bring me along. Thank you. I am glad of your friendship, and glad to share a little of the road with you."] = "human-male\\lore1351_befriended_1.ogg",
            ["You thought of bringing me along? Aye, friend, I'd like that. Indubitably. Come on. It'll be good to have someone to talk with while we see a little of the day."] = "human-male\\lore1395_befriended_1.ogg",
            ["You came to bring me along. Well, I'm glad of that. Come on, friend. A walk with someone who wants the company sounds good to me."] = "human-male\\lore1402_befriended_1.ogg",
            ["You needn't have a message to bring. I'm glad to see you for your own sake. Shall we get out for a while?"] = "human-male\\lore1427_befriended_1.ogg",
            ["You don't have to call me over only when a pot's in trouble. I'm glad to be here for myself."] = "human-male\\lore1430_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. It will be a pleasure to share the walk with you, quite apart from any business."] = "human-male\\lore1432_befriended_1.ogg",
            ["You make an ordinary walk feel like a day out. That's a fine thing in a friend. Shall we?"] = "human-male\\lore1433_befriended_1.ogg",
            ["You would have me along? It would be my pleasure, my friend. Lead on. I should be glad to share a stretch of the road and hear what you have been doing."] = "human-male\\lore14394_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. A walk and a proper conversation sound very welcome."] = "human-male\\lore14423_befriended_1.ogg",
            ["You came to bring me along. Gladly, my friend. Come. We need not decide every turn before we begin. I shall enjoy seeing what catches your interest."] = "human-male\\lore14438_befriended_1.ogg",
            ["You came to bring me along. Gladly, my friend. Come on. It will be good to share a walk and hear what you have been up to."] = "human-male\\lore14439_befriended_1.ogg",
            ["You came looking for me. I am glad, my friend. It will be good to have someone beside me who needn't be persuaded to listen."] = "human-male\\lore1444_befriended_1.ogg",
            ["You came to bring me along. I am pleased, my friend. Come on. It will be good to share a little of the day and hear what has been occupying your thoughts."] = "human-male\\lore14722_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. We can enjoy a little of the day and leave the account of it until later."] = "human-male\\lore1477_befriended_1.ogg",
            ["You ask because you're interested, not because something's broken. That's a pleasant change."] = "human-male\\lore151_befriended_1.ogg",
            ["I'd enjoy a walk with you. It's pleasant to hear about a journey before the part where something needs fixing. And if an ordinary mishap features in the account, you can tell it without dressing it up for my benefit."] = "human-male\\lore1668_befriended_1.ogg",
            ["I'd be glad to walk with you. Tell me what you've been enjoying between the errands. I like hearing about the pleasant little bits people almost forget to mention. They can be the best part of a journey."] = "human-male\\lore1670_befriended_1.ogg",
            ["I'd enjoy a walk with you. Tell me what you've been doing, and I'll try to leave enough room in the conversation for your stories. Though we may need a fairly wide path if my remarkable fish comes up again."] = "human-male\\lore1678_befriended_1.ogg",
            ["I'd enjoy coming with you. Tell me what you've been doing while we walk. A little company makes the day pleasant, even when we're waiting for something. Especially if you can keep me from inspecting the kettle again."] = "human-male\\lore1680_befriended_1.ogg",
            ["You thought to ask me along. Thank you, my friend. I should like that. Lead on; I shall try to be good company, and you can tell me what you have been doing."] = "human-male\\lore17804_befriended_1.ogg",
            ["I used to wonder whether my customers got home. With you, I get to ask."] = "human-male\\lore2046_befriended_1.ogg",
            ["You thought to ask me along. Thank you, my friend. I am glad. It helps to have someone beside me for a while, and I should like to hear what is on your mind."] = "human-male\\lore205278_befriended_1.ogg",
            ["You came to bring me along! Gladly, my friend. Come on. I shall enjoy hearing about your day, and you needn't compete with the far end of the street."] = "human-male\\lore2198_befriended_1.ogg",
            ["I'll be glad of your company. A little walk can help a man think before he goes back to the work. Tell me what you've seen. It's good to remember there's more to the world than the trouble in one field."] = "human-male\\lore233_befriended_1.ogg",
            ["You have my trust. That means more to me than another name on a muster roll."] = "human-male\\lore234_befriended_1.ogg",
            ["I'll be glad to walk with you a little. Company helps when a man's thoughts keep going round the same broken wheel. Tell me something ordinary from your day. Ordinary sounds rather good just now."] = "human-male\\lore237_befriended_1.ogg",
            ["You've earned my trust. Try not to make me put that in triplicate."] = "human-male\\lore240_befriended_1.ogg",
            ["Funny thing. You came back when there wasn't a deal waiting. I'm glad you did."] = "human-male\\lore241_befriended_1.ogg",
            ["You do what you say you'll do. I've learned I can count on that."] = "human-male\\lore250_befriended_1.ogg",
            ["You don't make me feel foolish for hoping. That's a good kind of friend to have."] = "human-male\\lore252_befriended_1.ogg",
            ["A trusted friend! Someone I can hand a sealed letter without a second thought."] = "human-male\\lore253_befriended_1.ogg",
            ["You come by even when there's nothing to trade. I like that very much."] = "human-male\\lore255_befriended_1.ogg",
            ["Gladly, my friend. Lead on. There is pleasure in having someone to share a small discovery with, particularly someone willing to offer an opinion of their own."] = "human-male\\lore258568_befriended_1.ogg",
            ["A walk with you would be welcome, my friend. Come on. There is time to see what the day has to offer and hear what you make of it."] = "human-male\\lore258930_befriended_1.ogg",
            ["You tell me what you think, even when we disagree. I like knowing where I stand with a friend."] = "human-male\\lore258_befriended_1.ogg",
            ["A friend, rather than another obligation. I'm glad. You may remind me to look up from the work now and then."] = "human-male\\lore2708_befriended_1.ogg",
            ["You came to bring me along. Gladly, my friend. Come on. It will be good to spend a little time together, with or without a perfect performance."] = "human-male\\lore2795_befriended_1.ogg",
            ["You've stayed long enough to know me beyond the shop. I'm glad of that."] = "human-male\\lore279_befriended_1.ogg",
            ["Next time Falkhaan sends someone, I'll tell them to look for you, too."] = "human-male\\lore295_befriended_1.ogg",
            ["I'd enjoy a walk with you. It's pleasant to have a friend who'll still invite me along after hearing the jokes. Tell me your news as we go. I promise I can listen without turning every sentence into a punchline."] = "human-male\\lore3089_befriended_1.ogg",
            ["You ask what interests me when there isn't a lesson to be had. I appreciate that more than I expected."] = "human-male\\lore328_befriended_1.ogg",
            ["I'll come along. A change of view will do me good, and I know I can enjoy your company. Give me a moment to put things where they belong. Then we can take a walk and you can tell me what you've been working on."] = "human-male\\lore341_befriended_1.ogg",
            ["Very well, I'll accompany you a little way. Tell me what you've seen beyond the town. A familiar voice and a change of view would be welcome. Let me put this little fellow somewhere secure before we go."] = "human-male\\lore344_befriended_1.ogg",
            ["I'd be glad of a change of view. Show me where you're headed, and we'll find something worth talking about along the way. I've spent enough evenings hearing travelers' stories to enjoy being in one with a friend."] = "human-male\\lore346_befriended_1.ogg",
            ["You'd like me along? I'd be glad of the company. Keep an eye on the path and I'll do the same for you. We can take a rest when we need one. It's easier to make a journey with someone who understands that."] = "human-male\\lore349_befriended_1.ogg",
            ["You came to bring me along. I am pleased, my friend. Come on. It will be good to share a walk with no sale needed at the end of it."] = "human-male\\lore3518_befriended_1.ogg",
            ["A familiar face at the roost. Makes the whole day easier."] = "human-male\\lore352_befriended_1.ogg",
            ["You came looking for me! Excellent. Come along, my friend. Today I get to enjoy the company I am always telling everyone about."] = "human-male\\lore3627_befriended_1.ogg",
            ["I'd be glad to come along. A walk and a bit of friendly talk sound fair to me. Tell me what's been happening beyond the docks. And if we get caught in a shower, I'll help you find somewhere pleasant to wait it out."] = "human-male\\lore381_befriended_1.ogg",
            ["I'll walk with you. It's good to have someone dependable beside you, and I could use a look along the road. Set a sensible pace. If we find a quiet place later, we can stop and share what's left of this loaf."] = "human-male\\lore382_befriended_1.ogg",
            ["You notice the care that goes into things. It's good having a friend who does."] = "human-male\\lore3935_befriended_1.ogg",
            ["I am glad you came back for me. This time I shall hear the story as it happens. Lead on, my friend."] = "human-male\\lore4078_befriended_1.ogg",
            ["I'd welcome your company. We'll keep our eyes open and look after each other along the way. Tell me how you've been. It's good to have a friend to talk with when there's a quiet moment between duties."] = "human-male\\lore464_befriended_1.ogg",
            ["You remember to ask how my day's been. It's a pleasure having someone listen back."] = "human-male\\lore465_befriended_1.ogg",
            ["You asked for my company. Gladly, my friend. Come on. Let us share a little of the day. I am pleased you thought to include me in it."] = "human-male\\lore466_befriended_1.ogg",
            ["I'd be glad to join you. A little company is worth making time for. You can tell me what you've seen, and I can put the supply lists aside in my head for a while. At least I'll try."] = "human-male\\lore491_befriended_1.ogg",
            ["You thought to invite me. Thank you. I am very glad to come along, my friend. No formalities required."] = "human-male\\lore4974_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. We can enjoy a little of the day without deciding what to call it."] = "human-male\\lore4981_befriended_1.ogg",
            ["You know when to talk work and when to let it rest. I appreciate that."] = "human-male\\lore514_befriended_1.ogg",
            ["A friend of mine flies at the front of the line. Well. Near the front."] = "human-male\\lore523_befriended_1.ogg",
            ["You have made time for me again. I am glad of it, my friend. Come along. We can leave the lessons in the hall for a while."] = "human-male\\lore5484_befriended_1.ogg",
            ["You came to bring me along. I am grateful, my friend. It will be good to share more than a greeting with you today."] = "human-male\\lore5489_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. There is no lesson to earn today. Let us enjoy the road together."] = "human-male\\lore5491_befriended_1.ogg",
            ["You keep finding your way back. That means something to me. Come along, my friend. Let's see a little of the world."] = "human-male\\lore5564_befriended_1.ogg",
            ["You came to bring me along. I am glad of your friendship. Come. Today there is time for us to share a little of the road ourselves."] = "human-male\\lore6171_befriended_1.ogg",
            ["You remember to ask after me, too. That kindness means more than I know how to say."] = "human-male\\lore6175_befriended_1.ogg",
            ["You stop to tell me what you've made. That's my favorite part of the trade."] = "human-male\\lore66_befriended_1.ogg",
            ["It's nice having a friend I don't have to look impressive for."] = "human-male\\lore74_befriended_1.ogg",
            ["You came to bring me along. I am glad of your friendship. Come on. Today we can share a little of the road ourselves."] = "human-male\\lore7798_befriended_1.ogg",
            ["A place beside you for a while. Thank you, my friend. I'm glad a welcome can lead to company like this."] = "human-male\\lore7917_befriended_1.ogg",
            ["I'll walk with you a little. Tell me how things look beyond the hill. And if you've something ordinary to talk about, I'd hear that too. The lives we're standing for contain more than patrol reports."] = "human-male\\lore821_befriended_1.ogg",
            ["You want me along? Very well. I could use a walk with someone I trust. We needn't spend every step talking about the Stockade. Tell me where we're going, and I'll keep watch with you."] = "human-male\\lore859_befriended_1.ogg",
            ["I spend all day making myself heard. It's good to be with someone I can simply talk to. Thank you for coming."] = "human-male\\lore8670_befriended_1.ogg",
            ["A visit without a transaction. I like that. I hope you'll keep coming back, even when you've nothing to list."] = "human-male\\lore8719_befriended_1.ogg",
            ["I'd enjoy walking with you. Two people can notice different things on the same road. Point out whatever catches your eye. If it turns out to be an unusually impressive grasshopper, I shall try to keep the report brief."] = "human-male\\lore878_befriended_1.ogg",
            ["I'd be glad to come with you. Tell me what you've been doing while we walk. I can leave the supplies in order for a little while. And the mint will manage without a second inspection until I return."] = "human-male\\lore8934_befriended_1.ogg",
            ["I know which one you'd reach for now. That's a nice thing to know about someone."] = "human-male\\lore894_befriended_1.ogg",
            ["I should be pleased to accompany you. A walk with someone I know would be welcome. Let me finish putting things in order, then we can set out. You may tell me how your day has treated you along the way."] = "human-male\\lore900_befriended_1.ogg",
            ["I'll come along. You seem to know the value of a dependable watch, and I'd rather share one with someone I know. Give me a moment to settle my kit. Then you can choose the road."] = "human-male\\lore903_befriended_1.ogg",
            ["You came to bring me along. I am glad, my friend. Come on. A little company with no message to deliver will be welcome."] = "human-male\\lore918_befriended_1.ogg",
            ["I'm glad you feel you can speak freely with me. I hope you'll let me do the same."] = "human-male\\lore927_befriended_1.ogg",
            ["You came looking for me. I am pleased, my friend. Come on. We can have a little time that isn't between jobs."] = "human-male\\lore957_befriended_1.ogg",
            ["Likewise."] = "human-male\\npc_bowBack_1.ogg",
            ["An honor."] = "human-male\\npc_bowBack_2.ogg",
            ["The pleasure's mine."] = "human-male\\npc_bowBack_3.ogg",
            ["{friend} is your Buddy now? The more the merrier!"] = "human-male\\npc_buddy_1.ogg",
            ["Another Buddy. Should I be jealous?"] = "human-male\\npc_buddy_2.ogg",
            ["Another Buddy! Your circle's getting crowded."] = "human-male\\npc_buddy_3.ogg",
            ["Good choice. I'd vouch for them."] = "human-male\\npc_buddy_4.ogg",
            ["Hooray!"] = "human-male\\npc_cheerAlong_1.ogg",
            ["Huzzah!"] = "human-male\\npc_cheerAlong_2.ogg",
            ["Three cheers!"] = "human-male\\npc_cheerAlong_3.ogg",
            ["Who are you calling chicken?"] = "human-male\\npc_chickenBack_1.ogg",
            ["Bawk yourself."] = "human-male\\npc_chickenBack_2.ogg",
            ["I'm brave! I'm just brave quietly."] = "human-male\\npc_chickenBack_3.ogg",
            ["Steady. Is everyone all right? Good. Remember what worked, and what you will do differently next time."] = "human-male\\lore11867_combatEnd_1.ogg",
            ["All right? Check yourself before the equipment. We can repair the rest."] = "human-male\\lore2046_combatEnd_1.ogg",
            ["Check on everyone before we move on."] = "human-male\\lore240_combatEnd_1.ogg",
            ["Everyone still here? Good. Take a breath."] = "human-male\\lore295_combatEnd_1.ogg",
            ["Well fought!"] = "human-male\\npc_combatEnd_1.ogg",
            ["That's how it's done."] = "human-male\\npc_combatEnd_2.ogg",
            ["Everyone in one piece? Good."] = "human-male\\npc_combatEnd_3.ogg",
            ["Ha! They won't try that again."] = "human-male\\npc_combatEnd_4.ogg",
            ["I'll admit, my heart was pounding."] = "human-male\\npc_combatEnd_5.ogg",
            ["Nicely done."] = "human-male\\npc_combatEnd_6.ogg",
            ["Is it over? It's over. Good."] = "human-male\\npc_combatEnd_7.ogg",
            ["Remind me never to make you angry."] = "human-male\\npc_combatEnd_8.ogg",
            ["Not bad at all!"] = "human-male\\npc_combatEnd_9.ogg",
            ["Victory! I'll be telling everyone about that one."] = "human-male\\npc_combatEnd_10.ogg",
            ["Catch your breath. You earned it."] = "human-male\\npc_combatEnd_11.ogg",
            ["And not a scratch on me. Thanks to you."] = "human-male\\npc_combatEnd_12.ogg",
            ["Hold on, it's weakening!"] = "human-male\\npc_combatLong_1.ogg",
            ["Don't give up now!"] = "human-male\\npc_combatLong_2.ogg",
            ["Steady. Steady."] = "human-male\\npc_combatLong_3.ogg",
            ["This one's stubborn. Keep at it!"] = "human-male\\npc_combatLong_4.ogg",
            ["It's tiring! I can see it!"] = "human-male\\npc_combatLong_5.ogg",
            ["Long fight. You've got more in you."] = "human-male\\npc_combatLong_6.ogg",
            ["Keep at it!"] = "human-male\\npc_combatMid_1.ogg",
            ["Good hit!"] = "human-male\\npc_combatMid_2.ogg",
            ["Watch your back!"] = "human-male\\npc_combatMid_3.ogg",
            ["That's it, that's it!"] = "human-male\\npc_combatMid_4.ogg",
            ["You've got it on the run!"] = "human-male\\npc_combatMid_5.ogg",
            ["Don't let up!"] = "human-male\\npc_combatMid_6.ogg",
            ["Ha! Did you see that?"] = "human-male\\npc_combatMid_7.ogg",
            ["Nearly there!"] = "human-male\\npc_combatMid_8.ogg",
            ["Hit it again!"] = "human-male\\npc_combatMid_9.ogg",
            ["It's on its last legs!"] = "human-male\\npc_combatMid_10.ogg",
            ["Mind your footing!"] = "human-male\\npc_combatMid_11.ogg",
            ["That one's going to leave a mark!"] = "human-male\\npc_combatMid_12.ogg",
            ["Go on! Go on!"] = "human-male\\npc_combatMid_13.ogg",
            ["You make this look like a dance!"] = "human-male\\npc_combatMid_14.ogg",
            ["Swing that blade! Go on!"] = "human-male\\npc_combatMid_15.ogg",
            ["Into the thick of it! That's the way!"] = "human-male\\npc_combatMid_16.ogg",
            ["The Light's with you! Now hit it!"] = "human-male\\npc_combatMid_17.ogg",
            ["Let your pet have a go!"] = "human-male\\npc_combatMid_18.ogg",
            ["Nice shot! Right on target!"] = "human-male\\npc_combatMid_19.ogg",
            ["Where'd you go? Oh! There you are! Stab it!"] = "human-male\\npc_combatMid_20.ogg",
            ["Patch yourself up, then smite it!"] = "human-male\\npc_combatMid_21.ogg",
            ["Call the storm down on it!"] = "human-male\\npc_combatMid_22.ogg",
            ["Burn it! Burn it all! Well, just that one."] = "human-male\\npc_combatMid_23.ogg",
            ["Whatever that green fire is, keep doing it!"] = "human-male\\npc_combatMid_24.ogg",
            ["Turn into something big and scary!"] = "human-male\\npc_combatMid_25.ogg",
            ["Keep your footing. Watch each other's backs."] = "human-male\\lore240_combatStart_1.ogg",
            ["Look out!"] = "human-male\\npc_combatStart_1.ogg",
            ["Here they come!"] = "human-male\\npc_combatStart_2.ogg",
            ["Give them what for!"] = "human-male\\npc_combatStart_3.ogg",
            ["Stay sharp!"] = "human-male\\npc_combatStart_4.ogg",
            ["On your guard!"] = "human-male\\npc_combatStart_5.ogg",
            ["Here we go again!"] = "human-male\\npc_combatStart_6.ogg",
            ["Watch it, it's coming right at you!"] = "human-male\\npc_combatStart_7.ogg",
            ["Show them what you've got!"] = "human-male\\npc_combatStart_8.ogg",
            ["Sit a moment, my friend. You needn't find the right words at once. I can stay here with you while you gather them. Tell me what you can, when you are ready."] = "human-male\\lore205278_comforted_1.ogg",
            ["Chin up. It'll be all right."] = "human-male\\npc_comforted_1.ogg",
            ["I'm here if you need me."] = "human-male\\npc_comforted_2.ogg",
            ["Thank you. I needed that."] = "human-male\\npc_comforted_3.ogg",
            ["Ha! All right, I'll dance."] = "human-male\\npc_danceAlong_1.ogg",
            ["I haven't danced in ages!"] = "human-male\\npc_danceAlong_2.ogg",
            ["Well, if you insist!"] = "human-male\\npc_danceAlong_3.ogg",
            ["Watch my feet. Or don't."] = "human-male\\npc_danceAlong_4.ogg",
            ["Oh, my friend. I wish a warm room could fix everything."] = "human-male\\lore295_died_1.ogg",
            ["Easy now. Let's get you back on your feet."] = "human-male\\npc_died_1.ogg",
            ["That looked like it hurt."] = "human-male\\npc_died_2.ogg",
            ["Don't worry. Happens to the best of us."] = "human-male\\npc_died_3.ogg",
            ["We'll come back stronger."] = "human-male\\npc_died_4.ogg",
            ["Oh, that's not good."] = "human-male\\npc_died_5.ogg",
            ["Well. That could have gone better."] = "human-male\\npc_died_6.ogg",
            ["Let's agree that one didn't count."] = "human-male\\npc_died_7.ogg",
            ["Lie still. I'll keep watch."] = "human-male\\npc_died_8.ogg",
            ["Keep close in here."] = "human-male\\npc_dungeon_1.ogg",
            ["I don't like the look of this place."] = "human-male\\npc_dungeon_2.ogg",
            ["Watch your step. And your back."] = "human-male\\npc_dungeon_3.ogg",
            ["It's dark in here. I don't love the dark."] = "human-male\\npc_dungeon_4.ogg",
            ["Stay together. Nobody wander off."] = "human-male\\npc_dungeon_5.ogg",
            ["Very impressive."] = "human-male\\npc_flexBack_1.ogg",
            ["Don't hurt yourself."] = "human-male\\npc_flexBack_2.ogg",
            ["Put those away before someone gets hurt."] = "human-male\\npc_flexBack_3.ogg",
            ["Have a proper look at the workmanship. Someone gave their time and care to that. I hope it serves you well."] = "human-male\\lore1315_gear_1.ogg",
            ["Take a proper look at how it is made and how it suits you. A confident description is useful only if the gear earns it."] = "human-male\\lore1319_gear_1.ogg",
            ["How does it feel? Good equipment should be useful to the person wearing it. Take a moment to decide for yourself."] = "human-male\\lore1320_gear_1.ogg",
            ["Have a proper look at the workmanship. Does it suit what you mean to do? Good gear should give you an answer beyond the name on the rack."] = "human-male\\lore1333_gear_1.ogg",
            ["Look at the stitching and how the piece sits. Fine work ought to serve the person wearing it. A little care in the making can matter a great deal when it is put to use."] = "human-male\\lore14394_gear_1.ogg",
            ["Does it fit properly? Give it a fair try. I have learned that a thumb can be quite a small part of a glove and still require a great deal of attention."] = "human-male\\lore14423_gear_1.ogg",
            ["Have a careful look before you put it aside. A sensible place now can spare you an awkward explanation later. That's advice I give from experience, and you are welcome to laugh at the experience if you like."] = "human-male\\lore1668_gear_1.ogg",
            ["Let me have a look at how that sits. A good fit matters, whether it's armor, a tool handle, or the lid of a small box. There, that looks comfortable enough. You ought to enjoy something that works the way it should."] = "human-male\\lore341_gear_1.ogg",
            ["Try a few steps. Good clothes ought to let you forget you're wearing them."] = "human-male\\lore74_gear_1.ogg",
            ["That looks good on you."] = "human-male\\npc_gear_1.ogg",
            ["New armor? Very sharp."] = "human-male\\npc_gear_2.ogg",
            ["You'll turn heads in that."] = "human-male\\npc_gear_3.ogg",
            ["Shiny! Did you polish that yourself?"] = "human-male\\npc_gear_4.ogg",
            ["That suits you. Very heroic."] = "human-male\\npc_gear_5.ogg",
            ["Now you look the part."] = "human-male\\npc_gear_6.ogg",
            ["Come on, your body's this way."] = "human-male\\npc_ghost_1.ogg",
            ["I'll walk with you. Don't mind the chill."] = "human-male\\npc_ghost_2.ogg",
            ["You look a bit see-through. It's fine. Mostly fine."] = "human-male\\npc_ghost_3.ogg",
            ["Follow the road. I'll be right here."] = "human-male\\npc_ghost_4.ogg",
            ["Is it cold, being a ghost? You look cold."] = "human-male\\npc_ghost_5.ogg",
            ["Good to see you. Take your time coming over. How has your companion been? And how have you been? It's pleasant to have a friendly visit when the animals are settled and there's a moment to talk."] = "human-male\\lore10045_greet_1.ogg",
            ["There you are. I was hoping to hear how the road treated you. Any trouble, tell me plainly. And if something went well, tell me that too. I've a little space left on my other page."] = "human-male\\lore1070_greet_1.ogg",
            ["There you are. An outing? Splendid. I chose rather well today, if I do say so. We should give the outfit a little daylight."] = "human-male\\lore11096_greet_1.ogg",
            ["Ready? Good. An ordinary walk can be an excellent change of pace. You may put the weapon away."] = "human-male\\lore11867_greet_1.ogg",
            ["Good to see you, my friend. Have you come far? We can take our time. Tell me what has occupied your thoughts, or simply what you noticed on the way."] = "human-male\\lore1212_greet_1.ogg",
            ["There you are, my friend. Have you news of the road? Come, we can walk while you tell me. And do include the details you thought too small to mention."] = "human-male\\lore12336_greet_1.ogg",
            ["There you are, mate. Come along. That is an invitation, before you ask. A little walk would be welcome, and you can tell me what has kept you busy."] = "human-male\\lore12480_greet_1.ogg",
            ["Ready to go? One moment. I can hear something loose in that pack."] = "human-male\\lore1257_greet_1.ogg",
            ["A little time together? Gladly. Come, tell me what has occupied your attention. I was considering something quite ordinary, and finding that it had held my interest longer than I intended."] = "human-male\\lore1284_greet_1.ogg",
            ["Ah, my friend. Shall we take a walk? I have improved the drawbridge. The wall still needs attention, but the opening is very satisfying. You must come and inspect it sometime."] = "human-male\\lore1285_greet_1.ogg",
            ["Good to see you. A walk before the next cup? Certainly. The racks can look after themselves for a little while."] = "human-male\\lore1289_greet_1.ogg",
            ["A walk? Certainly. A chance to move around instead of telling everyone else to do it. Good idea."] = "human-male\\lore1294_greet_1.ogg",
            ["Ah, a familiar face! Shall we go out? I have been saving a particularly dreadful joke, and I could use a fresh audience."] = "human-male\\lore1298_greet_1.ogg",
            ["An outing would be welcome. I've been advising people to take a break all morning. Time I followed my own advice."] = "human-male\\lore1300_greet_1.ogg",
            ["Ah, my friend. Have you what you need for the road? Good. Then let us have a walk. You may help me remember what went into that soup, though I fear the evidence is gone."] = "human-male\\lore1308_greet_1.ogg",
            ["A walk? Certainly. Let's hope the wind has better manners today. I've spent enough time chasing hats."] = "human-male\\lore1310_greet_1.ogg",
            ["Good to see you. How has your gear been treating you? We can talk about the fit, or simply have a pleasant visit. I promise not to demonstrate my juggling unless you ask. Probably."] = "human-male\\lore1314_greet_1.ogg",
            ["Ah, there you are. Shall we take a walk? If we find a plain wall and a good light, I may show you a dragon. You may need to be generous about the wings."] = "human-male\\lore1315_greet_1.ogg",
            ["Good to see you. Have you come with a question, or simply for company? Either is welcome. I was taking a moment over a drawing, and I suspect the duck would have several corrections to offer."] = "human-male\\lore1317_greet_1.ogg",
            ["There you are, my friend. Have you time for a walk? I have made another adjustment to the kite. A shield-shaped kite, yes. You may admire the ambition while we wait for the results."] = "human-male\\lore1319_greet_1.ogg",
            ["Ah, my friend. Shall we go out? I brought the old ball. There may be somewhere with enough room for a little game."] = "human-male\\lore1320_greet_1.ogg",
            ["Good to see you, my friend. Have you time for a walk? Tell me what the road has been like. News of an ordinary day would be welcome as well as another urgent request."] = "human-male\\lore1323_greet_1.ogg",
            ["Good to see you, my friend. Shall we take a walk? I could use another opinion about the horse. A wooden one. It is becoming a pony at a rather steady rate."] = "human-male\\lore1324_greet_1.ogg",
            ["Ah, my friend. Have you time for a walk? Titan has another bud. The violet, I mean. It is a little thing, but I have been waiting. You must come and see it when it opens."] = "human-male\\lore1333_greet_1.ogg",
            ["There you are, my friend. Have you time for a walk? I have been considering an opening move. You may tell me whether it is clever, or simply the one everyone tries first."] = "human-male\\lore1341_greet_1.ogg",
            ["Welcome back! Have you brought work to discuss, or have you time to look at something ridiculous? I've added another flourish to a hat design. It is becoming quite magnificent, provided nobody actually tries to wear it."] = "human-male\\lore1346_greet_1.ogg",
            ["Welcome, my friend. Are we going out? Give me a moment. I should like to leave this little puzzle behind before it occupies the whole day."] = "human-male\\lore1351_greet_1.ogg",
            ["There you are. Have ye a moment? I've a fine new word to try out. Am I pleased to see a familiar face? Indubitably. Come on, then. Tell me how you've been."] = "human-male\\lore1395_greet_1.ogg",
            ["Ah, there you are. Have you time for a walk? I've got a little plan. One bean, bit of cloth, nowhere to plant it yet. You may know a place with decent soil."] = "human-male\\lore1402_greet_1.ogg",
            ["A walk would do me good. I've been looking at stock all morning. Let's see what everyone else is doing."] = "human-male\\lore1427_greet_1.ogg",
            ["Off we go, then. If we stop for a meal, perhaps you can show me what you've learned."] = "human-male\\lore1430_greet_1.ogg",
            ["Ah, my friend. Good to see you. Shall we take a walk? I have a little toast to practice. Little is the ambition, you understand. I may need you to tell me when the introduction has gone on long enough."] = "human-male\\lore1432_greet_1.ogg",
            ["An outing together? Lovely. I've no bundle to carry this time. What a difference that makes."] = "human-male\\lore1433_greet_1.ogg",
            ["Shall we see the road beyond the arches? I have a small piece of leatherwork to tell you about. It may receive an announcement quite out of proportion to its size."] = "human-male\\lore14394_greet_1.ogg",
            ["Good to see you, my friend. Have you time to walk with me? Tell me how you have been. I have made a little progress with that glove, though the thumb remains a subject of discussion."] = "human-male\\lore14423_greet_1.ogg",
            ["There you are, my friend. Have you time for a pleasant walk? I have considered several routes. Then again, I should be interested to see which way you would choose."] = "human-male\\lore14438_greet_1.ogg",
            ["Good to see you, my friend. Have you time for a walk? I shall be glad of the company. If you notice something I have missed, do point it out."] = "human-male\\lore14439_greet_1.ogg",
            ["Ah, my friend. A walk sounds good. I have said the first sentence to the fountain often enough. Perhaps you would hear it once."] = "human-male\\lore1444_greet_1.ogg",
            ["Good to see you, my friend. Have you time for a walk? Come on. I should like to hear how your day has been, with no counting required on either side."] = "human-male\\lore14722_greet_1.ogg",
            ["There you are, my friend. Shall we take a walk? I have no heroic destination in mind. Somewhere with a comfortable seat would be quite enough to begin with."] = "human-male\\lore1477_greet_1.ogg",
            ["Ready for the road? Give those straps a check, and I'll come along."] = "human-male\\lore151_greet_1.ogg",
            ["Good to see you. How has your bow been treating you? If something's wrong, tell me plainly. I won't insist you invent a splendid battle to explain it. Ordinary mishaps are quite capable of making work for a bowyer."] = "human-male\\lore1668_greet_1.ogg",
            ["Good to see you. Have you had time for a proper meal? You needn't tell me about a magnificent feast. A good bit of bread and a moment to enjoy it can improve a day considerably."] = "human-male\\lore1670_greet_1.ogg",
            ["Good to see you. What are you hoping to catch? We can look at the supplies before you set off. Then, if you've a moment, I have a fish story that has improved considerably since its last telling."] = "human-male\\lore1678_greet_1.ogg",
            ["Well met. How has your day been? There's time to tell me while we look at the water. If you've come to learn, we'll take it steadily. No need to hurry past the pleasant part of being here."] = "human-male\\lore1680_greet_1.ogg",
            ["A walk together? Very well. I have been practicing an introduction. If it grows too grand, you may remind me that we are simply going for a walk. Come on, my friend."] = "human-male\\lore17804_greet_1.ogg",
            ["Good to see you. Comfortable straps? Right, then. Let's go."] = "human-male\\lore2046_greet_1.ogg",
            ["A little company would be welcome. Come, let us walk. If you have heard any news, I shall listen. If you haven't, tell me how you have been. I should be glad to hear that too."] = "human-male\\lore205278_greet_1.ogg",
            ["There you are, my friend! Have you news of your own? Come on, we can walk while you tell me. I should like to hear what has been happening in your part of the world."] = "human-male\\lore2198_greet_1.ogg",
            ["Good to see a friendly face. There's plenty needs doing, but you can stand and talk a moment. I was thinking what the field might look like with a few flowers down the edge. A quieter year, perhaps."] = "human-male\\lore233_greet_1.ogg",
            ["Come. Let us see what help we can offer beyond the hill."] = "human-male\\lore234_greet_1.ogg",
            ["Hello again. I hope the road's been kinder to you than it's been to us. Come and talk a moment. If you've a joke about broken wagons, I'll hear it. I may have used up the complaints."] = "human-male\\lore237_greet_1.ogg",
            ["I'll have a look at these roads myself, then."] = "human-male\\lore240_greet_1.ogg",
            ["A traveling partner! Now that's a good start. A good start."] = "human-male\\lore241_greet_1.ogg",
            ["Ready? Good. There's daylight yet, and no sense wasting all of it talking."] = "human-male\\lore250_greet_1.ogg",
            ["Oh, hello! I wasn't talking to the river. Well... perhaps a little."] = "human-male\\lore252_greet_1.ogg",
            ["Ah, my traveling associate! Clean hands, I trust?"] = "human-male\\lore253_greet_1.ogg",
            ["A walk? Gladly. Let me fill my waterskin before we start."] = "human-male\\lore255_greet_1.ogg",
            ["There you are, my friend. Shall we take a walk? I have been folding a little paper bird. Someone called it a hat. I should value another opinion before I begin my next masterpiece."] = "human-male\\lore258568_greet_1.ogg",
            ["Good to see you. Shall we have a little time to walk and listen? At the end of it, I can recommend sitting down and letting a kettle do the singing."] = "human-male\\lore258930_greet_1.ogg",
            ["Good to see you! Something for the road before we set off?"] = "human-male\\lore258_greet_1.ogg",
            ["Ah, there you are. No report today? An outing? Yes, that would be very welcome. I've had quite enough correspondence."] = "human-male\\lore2708_greet_1.ogg",
            ["There you are, my friend. Have you a moment? I have been practicing that coin trick. Come on, we can walk. I should like to hear what has been occupying your hands lately."] = "human-male\\lore2795_greet_1.ogg",
            ["There you are! No counter between us today. What shall we investigate?"] = "human-male\\lore279_greet_1.ogg",
            ["Well! Someone else can mind the counter for a bit."] = "human-male\\lore295_greet_1.ogg",
            ["Good to see you. Need something for the road? Take your time choosing. I can offer a little conversation while you look. The jokes cost nothing, though you may feel I've charged too much once you've heard one."] = "human-male\\lore3089_greet_1.ogg",
            ["Good. A walk gives us time to observe things without setting any of them alight."] = "human-male\\lore328_greet_1.ogg",
            ["Good, you're here. Have a look at this little box. A few offcuts, a bit of spare time, and a lid that finally fits the way I wanted. Close it gently. Hear that? That's the satisfying part. I may have checked it more than once."] = "human-male\\lore341_greet_1.ogg",
            ["Ah, there you are. I can spare a little time before the next message arrives. Have a look at this small fellow, if you would. I believe he's a duck. The beak is quite persuasive, even if the rest requires generosity."] = "human-male\\lore344_greet_1.ogg",
            ["Good to see a friendly face. Come and tell me what the road's been like. With deliveries as late as they've been, I could use some good news. Failing that, I'll happily settle for a good story."] = "human-male\\lore346_greet_1.ogg",
            ["Good to have you here. Let's take a pace we can both manage. If we find a quiet spot in the sun, we can stop a moment. There are worse ways to spend a little time than fresh air and familiar company."] = "human-male\\lore349_greet_1.ogg",
            ["Ah, my friend. Good to see you. Come a little way with me. There is always bread to sell, but I should like to hear how your day has been going."] = "human-male\\lore3518_greet_1.ogg",
            ["A journey on foot? I'll try to remember how those work."] = "human-male\\lore352_greet_1.ogg",
            ["There you are! My favorite sort of passerby: one who comes back. Shall we go out? I could use someone with a better line than mine."] = "human-male\\lore3627_greet_1.ogg",
            ["Well met! Come and stand beside me a moment. If the weather turns, we'll find ourselves a dry spot. I rather like hearing the first drops on the lake. Better than hearing one find its way down the back of my collar."] = "human-male\\lore381_greet_1.ogg",
            ["Good, you're here. I've a moment, and this is nearly ready. The end of the loaf, warmed carefully. It wants a little attention before it turns from crisp to burnt. You're welcome to a piece when I've judged it properly."] = "human-male\\lore382_greet_1.ogg",
            ["How far today? Tell me while I wrap something for the road."] = "human-male\\lore3935_greet_1.ogg",
            ["Ah, my friend. Shall we take a walk? There are places on my map I have only ever heard described."] = "human-male\\lore4078_greet_1.ogg",
            ["Well met. Keep an eye on the road while we talk. There are gnolls gathering nearby, and I'd rather hear your news without an unwelcome interruption. Still, a familiar face makes a long patrol considerably more pleasant."] = "human-male\\lore464_greet_1.ogg",
            ["Ah, there you are! Tell me the rest of that story while we walk."] = "human-male\\lore465_greet_1.ogg",
            ["At ease, my friend. Have you time for a little company? Tell me how the road has treated you. I should like to hear from the person who traveled it as well as receive the account."] = "human-male\\lore466_greet_1.ogg",
            ["Good to see you. I've plenty to keep track of, but there's time for a friendly word. How did the road treat you? It's pleasant to hear someone's news without another shortage at the end of it."] = "human-male\\lore491_greet_1.ogg",
            ["Ah, my friend. An outing? Excellent. I shall leave the paperwork here. For once, we needn't agree on a name before we go."] = "human-male\\lore4974_greet_1.ogg",
            ["There you are, my friend. Shall we take a walk? I have another possible name for my cheese. No cheese yet, I admit. You may have to keep me sensible."] = "human-male\\lore4981_greet_1.ogg",
            ["A break from the anvil? All right. You have my attention."] = "human-male\\lore514_greet_1.ogg",
            ["Need a lift? You came to the right hill."] = "human-male\\lore523_greet_1.ogg",
            ["There you are. A walk? Good. I have been turning the same thought over along the same stretch of floor. Let us give it some room."] = "human-male\\lore5484_greet_1.ogg",
            ["Welcome, my friend. Shall we go out? You might teach me a greeting for the road. I have been practicing the last one."] = "human-male\\lore5489_greet_1.ogg",
            ["Well met, my friend. A walk would be welcome. If we pass a good stretch of water, I may ask you to keep count for me."] = "human-male\\lore5491_greet_1.ogg",
            ["An outing? Good. Let me get the walking bag. And remind me to put something edible in it this time."] = "human-male\\lore5564_greet_1.ogg",
            ["Welcome, my friend. A walk would be good. Tell me what has occupied you. I should like to hear about the people, as well as the challenges."] = "human-male\\lore6171_greet_1.ogg",
            ["A little company would be welcome. Thank you for thinking to ask."] = "human-male\\lore6175_greet_1.ogg",
            ["Off we go, then. You've got the tools, and I've got spare string."] = "human-male\\lore66_greet_1.ogg",
            ["A walk? Certainly. Just give me a moment to find the sensible shoes."] = "human-male\\lore74_greet_1.ogg",
            ["There you are, my friend. Shall we go out? I should like to hear what you have been doing with all that determination."] = "human-male\\lore7798_greet_1.ogg",
            ["Welcome, my friend! Oh, we're going out? How lovely. You'll have to show me where we're headed."] = "human-male\\lore7917_greet_1.ogg",
            ["Good to see you. What have you heard on the road? We need clear news, and willing hands. If you've come simply to talk, that's welcome too. There is still room for a neighbor's company among the reports."] = "human-male\\lore821_greet_1.ogg",
            ["Good. You're here. I've had enough talk of delays for one day. Walk with me a moment, if you've the time. You needn't have an answer ready. I wasn't asking for another answer."] = "human-male\\lore859_greet_1.ogg",
            ["YOUR ATTENTION, PLEASE! Ah. Yours will do nicely. Sorry. A walk sounds splendid."] = "human-male\\lore8670_greet_1.ogg",
            ["Good to see you. No need to buy anything. Shall we have a look around together?"] = "human-male\\lore8719_greet_1.ogg",
            ["Good to see you. What have you noticed on the way? Take your time. I'd rather hear what you actually saw than a quick guess. And it needn't all be trouble. There are other things worth looking at."] = "human-male\\lore878_greet_1.ogg",
            ["Good to see you. What are you working on today? We can think about the supplies together. Or, if you've simply come to visit, I've a very small piece of good news. The mint has another leaf."] = "human-male\\lore8934_greet_1.ogg",
            ["Good to see you! Pick something for the road before we leave."] = "human-male\\lore894_greet_1.ogg",
            ["Ah, there you are. I have a moment before I must return to the court. I've also found a particularly promising apple. Firm, green, and likely to require a little composure. You're welcome to keep me company while I find out."] = "human-male\\lore900_greet_1.ogg",
            ["Ready? Good. Let me check this bundle and we can be off. No secret orders. A spare pair of socks, wrapped properly. Laugh if you like, but ask me again after a wet watch."] = "human-male\\lore903_greet_1.ogg",
            ["There you are, my friend. Shall we take a walk? Keep an ear open. There is a tune I should like you to hear, if someone happens to be playing it today."] = "human-male\\lore918_greet_1.ogg",
            ["Good to see you. Shall we make ourselves useful along the way?"] = "human-male\\lore927_greet_1.ogg",
            ["There you are. A walk? Good. I could use a look at something beyond the forge. Rooftops, perhaps. I have a reason."] = "human-male\\lore957_greet_1.ogg",
            ["Lead the way, {name}."] = "human-male\\npc_greet_1.ogg",
            ["Right. Show me what you've been dealing with."] = "human-male\\lore240_greet_2.ogg",
            ["Out we go. Did you remember your cloak?"] = "human-male\\lore295_greet_2.ogg",
            ["Right, then. Who's watching the gryphons?"] = "human-male\\lore352_greet_2.ogg",
            ["Wind's from the south today. Good flying weather."] = "human-male\\lore523_greet_2.ogg",
            ["Glad to come along, {name}!"] = "human-male\\npc_greet_2.ogg",
            ["Where are we off to today?"] = "human-male\\npc_greet_3.ogg",
            ["I told the others I'd be out for a while. Let's make it count."] = "human-male\\npc_greet_4.ogg",
            ["It's good to get away from the counter for once."] = "human-male\\npc_greet_5.ogg",
            ["Ready when you are, {name}."] = "human-male\\npc_greet_6.ogg",
            ["Some fresh air will do me good."] = "human-male\\npc_greet_7.ogg",
            ["Don't walk too fast. I'm not used to all this adventuring."] = "human-male\\npc_greet_8.ogg",
            ["Well met, {name}! Good to see a friendly face."] = "human-male\\npc_greet_9.ogg",
            ["Right behind you. Where to first?"] = "human-male\\npc_greet_10.ogg",
            ["I packed a lunch. Just in case."] = "human-male\\npc_greet_11.ogg",
            ["Off on an adventure! Don't tell my boss."] = "human-male\\npc_greet_12.ogg",
            ["Fresh boots, fresh start. Let's go."] = "human-male\\npc_greet_13.ogg",
            ["I've been looking forward to this all week."] = "human-male\\npc_greet_14.ogg",
            ["A fine gathering. Before we choose a direction, does everyone have what they need? Even the quiet one at the back?"] = "human-male\\lore4974_group_1.ogg",
            ["More company! Wonderful."] = "human-male\\npc_group_1.ogg",
            ["Strength in numbers."] = "human-male\\npc_group_2.ogg",
            ["New faces! Hello, everyone."] = "human-male\\npc_group_3.ogg",
            ["A whole party. Now it's an adventure."] = "human-male\\npc_group_4.ogg",
            ["Home for a spell? Good. Even heroes need somewhere to leave their boots."] = "human-male\\lore295_hearth_1.ogg",
            ["Neat trick. Doesn't give you much of a view, mind."] = "human-male\\lore352_hearth_1.ogg",
            ["A hearthstone. Faster than a gryphon, I'll admit. Barely."] = "human-male\\lore523_hearth_1.ogg",
            ["Home again!"] = "human-male\\npc_hearth_1.ogg",
            ["Off to the inn. My treat. Well, your treat."] = "human-male\\npc_hearth_2.ogg",
            ["Home sweet home."] = "human-male\\npc_hearth_3.ogg",
            ["Back to a warm bed. Finally."] = "human-male\\npc_hearth_4.ogg",
            ["Oh! Well. That's nice."] = "human-male\\npc_hugged_1.ogg",
            ["Aw, thank you."] = "human-male\\npc_hugged_2.ogg",
            ["Oh, you big softie."] = "human-male\\npc_hugged_3.ogg",
            ["I've been reading the same page for a while. A quiet break can make a man drowsy. I don't mind. When the animals are settled and the work is done, it's quite pleasant to find I can relax that much."] = "human-male\\lore10045_idle_1.ogg",
            ["I started keeping a few good things on a separate page. Nothing grand. A cart made it home. Somebody mended a roof. You can fill a whole report with danger and forget what you're trying to keep safe."] = "human-male\\lore1070_idle_1.ogg",
            ["The pocket lining is for me. A little flourish nobody has to approve of. Yes, even I sometimes dress without an audience."] = "human-male\\lore11096_idle_1.ogg",
            ["Yes, I thank the practice dummy. It is always ready, never complains, and has endured a remarkable number of beginners."] = "human-male\\lore11867_idle_1.ogg",
            ["My reading list continues to grow. Then I take down a familiar book and read the same chapter again. I enjoy it. That seems a sufficient use of a quiet hour."] = "human-male\\lore1212_idle_1.ogg",
            ["I leave space for my signature. Then I add a question, and a detail I had nearly forgotten. By the time the letter is finished, the signature has been driven into a corner. Again."] = "human-male\\lore12336_idle_1.ogg",
            ["I asked for one loaf. Quietly, I thought. Sounded like I wanted the whole bakery to form up. Next time I shall begin with please, and address only the person behind the counter."] = "human-male\\lore12480_idle_1.ogg",
            ["That bottle has a lovely note. Shame it's full of something expensive."] = "human-male\\lore1257_idle_1.ogg",
            ["A plain bead of glass can send a bright fleck traveling over the desk. I have followed it with a finger, then discovered I had lost my place in a much more serious book. An undemanding little diversion."] = "human-male\\lore1284_idle_1.ogg",
            ["The drawbridge opens beautifully. Then the wall falls over. A small weakness in the defenses, I admit. But I should hate to lose that opening. You would understand if you saw it."] = "human-male\\lore1285_idle_1.ogg",
            ["The teapot? It's a good teapot. The dents don't stop it working, and a little polish makes a break feel civilized."] = "human-male\\lore1289_idle_1.ogg",
            ["The biscuits are improving. This batch needs less tea. Well, a little less. The important thing is that I'm still trying."] = "human-male\\lore1294_idle_1.ogg",
            ["I keep the good jokes on scraps of wrapping paper. The dreadful ones too. Rather more of those, if I am honest."] = "human-male\\lore1298_idle_1.ogg",
            ["Yes, I knot my own thread. Then I have to listen to my own advice about patience. Most inconvenient."] = "human-male\\lore1300_idle_1.ogg",
            ["The soup was excellent. I remember that much. What went into it? Something that needed using, then something else. This is why I cannot offer a reliable recipe."] = "human-male\\lore1308_idle_1.ogg",
            ["It's an old hat. A very comfortable old hat. I sell new ones; that doesn't oblige me to stop liking this one."] = "human-male\\lore1310_idle_1.ogg",
            ["Two rolled socks are quite manageable. Add a third, and suddenly I've got more hands to wish for. Last time it landed on my head. I laughed and dropped the others. A very memorable performance."] = "human-male\\lore1314_idle_1.ogg",
            ["The dragon keeps acquiring rabbit ears. I could call it a rare breed, I suppose. But I would rather get the wings right. You will tell me honestly, won't you?"] = "human-male\\lore1315_idle_1.ogg",
            ["The enchantments in my notes are quite legible. The small ink shapes are meant to be ducks. I mention that because a friend once asked why I had drawn so many slippers beside the formulae."] = "human-male\\lore1317_idle_1.ogg",
            ["I have chosen the colors for the tail. A splendid tail. Getting the rest of the kite to stay up comes first, I suppose. Still, it helps to have something cheerful to imagine while I make another adjustment."] = "human-male\\lore1319_idle_1.ogg",
            ["The ball is perfectly serviceable. Yes, I know how it looks. You should see how many good afternoons have gone into those scuffs."] = "human-male\\lore1320_idle_1.ogg",
            ["Lewis hopes to offer me a meal when Westfall is safe. I have thought about it. Good food, news of the land, time to hear about an ordinary day. I should be very glad to accept."] = "human-male\\lore1323_idle_1.ogg",
            ["One hoof is still off the table. I could call the horse lively. Another correction, and I may have to call it a very small pony. You see why I am considering the description carefully."] = "human-male\\lore1324_idle_1.ogg",
            ["I call the violet Titan. It has a second bud now. I am trying to wait patiently. Going back to look again doesn't make it open any sooner, but I keep finding a reason to pass the window."] = "human-male\\lore1333_idle_1.ogg",
            ["I have considered a very clever first move. Then a friend sits down, and I offer them the first turn. I want to see what they have thought of. There is always another game for my great discovery."] = "human-male\\lore1341_idle_1.ogg",
            ["The hat on this page will never be made. It wouldn't fit through the door, for one thing. But every now and then I add another flourish. An idea needn't become an order to give a person pleasure."] = "human-male\\lore1346_idle_1.ogg",
            ["The wooden rings are meant to come apart. I have yet to persuade them. Perhaps I should practice accepting the help I am so ready to offer."] = "human-male\\lore1351_idle_1.ogg",
            ["Indubitably. A fine long word. I asked what it meant, and it means certainly. Well, I'm certainly glad when a friend stops to talk. There's a proper use for it straight away."] = "human-male\\lore1395_idle_1.ogg",
            ["One bean. I call it seed, you understand. Makes tomorrow sound a bit more open. Haven't chosen the ground yet. I'd like someone there when I do. No grand occasion. Just company."] = "human-male\\lore1402_idle_1.ogg",
            ["Picnic blankets. That's what the empty line is for. I'd like to fill an order for a pleasant day, for once."] = "human-male\\lore1427_idle_1.ogg",
            ["Taste it before adding anything else. Sometimes the next thing a dish needs is nothing."] = "human-male\\lore1430_idle_1.ogg",
            ["I want to thank Suzetta. Two words. Somehow I keep putting a magnificent introduction in front of them. Perhaps I should begin with the two words, and have the courage to stop."] = "human-male\\lore1432_idle_1.ogg",
            ["I saved a piece for Rema. Well, of course I did. No sense bringing home nothing but the wrapping."] = "human-male\\lore1433_idle_1.ogg",
            ["The spoon fits its leather case exactly. In, out, and securely back again. I have tested it more often than necessary. You may permit me a small celebration of the workmanship."] = "human-male\\lore14394_idle_1.ogg",
            ["The glove is warm, and most of it fits. The thumb is rather long. I keep trying it on anyway. There is a good deal of work there that I am pleased with."] = "human-male\\lore14423_idle_1.ogg",
            ["I planned a pleasant short walk. Then I remembered another view, and another turn worth taking. It remains a pleasant walk. I am beginning to reconsider the word short."] = "human-male\\lore14438_idle_1.ogg",
            ["I pointed out a lion in the clouds. A magnificent creature, I thought. My companion said it was a potato. After another look, I had to admit it was a remarkably good potato."] = "human-male\\lore14439_idle_1.ogg",
            ["The first sentence is always the troublesome one. After that, I remember I am speaking to people. Before it, I remember how many people there might be."] = "human-male\\lore1444_idle_1.ogg",
            ["I have been folding my supper napkin into a crown. Sometimes it leans. I still make the effort when eating alone. An ordinary meal can be worth taking a little trouble over."] = "human-male\\lore14722_idle_1.ogg",
            ["Nothing happened. We had a pleasant walk, found a seat, and everyone stayed in one piece. I should be very happy to give that account of the afternoon. A short story, but a fine ending."] = "human-male\\lore1477_idle_1.ogg",
            ["The clever bit isn't tying a knot. It's making one you can undo when your fingers are cold."] = "human-male\\lore151_idle_1.ogg",
            ["I once sat down without checking where I'd put a bow. I do not recommend that method of learning to look behind you. The lesson was very clear, though. I've remembered it considerably longer than I wanted to."] = "human-male\\lore1668_idle_1.ogg",
            ["I've heard people argue over which slice is best. They often leave the crusty end. Suits me very well. I like that bit, and it's quite pleasant to enjoy it while everyone else has gone on to another argument."] = "human-male\\lore1670_idle_1.ogg",
            ["That fish was about so big. No, a little bigger now I think of it. The real one was quite small, but the story has had plenty of time to grow. A good listener can do wonders for it."] = "human-male\\lore1678_idle_1.ogg",
            ["I can wait quietly beside a fishing line, then go home and check the kettle three times. Apparently my patience has a favorite place to work. I'm trying to persuade it to travel a little further with me."] = "human-male\\lore1680_idle_1.ogg",
            ["Sir Rowe. Hm. It is easy enough to say. Becoming someone worthy of it will take rather more than a good introduction. I should begin by being ready when I am needed."] = "human-male\\lore17804_idle_1.ogg",
            ["A shield has an outside for the danger and an inside for the person who matters."] = "human-male\\lore2046_idle_1.ogg",
            ["I think of all the questions I would ask if Ada came through the door. Then I think I would ask whether she had eaten. The rest could wait until she was warm and seated."] = "human-male\\lore205278_idle_1.ogg",
            ["Six silken sashes in seven silver sacks. There! Quite clear, at that speed. Now I am tempted to try it faster, which is generally where the sashes begin to win."] = "human-male\\lore2198_idle_1.ogg",
            ["I'd like a narrow strip of flowers beside the crops. Nothing to sell. Just something Salma could stop and look at on her way past. There's a deal of work between here and that little plan, but I like keeping it in mind."] = "human-male\\lore233_idle_1.ogg",
            ["One day, the loudest thing in these fields will be a harvest wagon."] = "human-male\\lore234_idle_1.ogg",
            ["I've been trying to think of a wagon joke bad enough to make Verna laugh. Won't mend a wheel, I know. But I'd like to hear her laugh a little. A man can want that and a working wagon both."] = "human-male\\lore237_idle_1.ogg",
            ["One quiet afternoon. That's all I'm asking."] = "human-male\\lore240_idle_1.ogg",
            ["Gold dust is worth counting. So are the people who stop to listen."] = "human-male\\lore241_idle_1.ogg",
            ["Tie a vine too tightly and you'll harm the very thing you're trying to support."] = "human-male\\lore250_idle_1.ogg",
            ["The speech went much better when there wasn't anyone to hear it."] = "human-male\\lore252_idle_1.ogg",
            ["If only family feuds dissolved as easily as candle wax."] = "human-male\\lore253_idle_1.ogg",
            ["An apple and cool water. You can make an afternoon better without making it complicated."] = "human-male\\lore255_idle_1.ogg",
            ["My best paper bird stood beautifully. A visitor called it a hat. I tried the folds again, and found I rather liked the hat too. A useful discovery, even if it complicates the name."] = "human-male\\lore258568_idle_1.ogg",
            ["I sometimes put out a second cup before anyone has called. If a friend arrives, I can say I was prepared. It is a small hope, and a pleasant one to have ready at the end of a day."] = "human-male\\lore258930_idle_1.ogg",
            ["You needn't use a grand word for something you like. Good will do nicely."] = "human-male\\lore258_idle_1.ogg",
            ["I rehearse the good news for Trelane. Then I abandon the speech. Strange, isn't it? An archmage still hoping to please his first teacher."] = "human-male\\lore2708_idle_1.ogg",
            ["I can roll the coin across my knuckles without looking. Then a friend watches, and down go my eyes. I want them to see it go well. Apparently, I want to see it go well too."] = "human-male\\lore2795_idle_1.ogg",
            ["I do enjoy a good question. Especially one that changes my answer."] = "human-male\\lore279_idle_1.ogg",
            ["I ought to be polishing something. Old habit."] = "human-male\\lore295_idle_1.ogg",
            ["I was going to tell you a joke about a fine cut of meat, but I'm afraid I've butchered the ending. There we are. A groan is perfectly fair. I did give you a little warning."] = "human-male\\lore3089_idle_1.ogg",
            ["A thing needn't be enchanted to deserve a closer look."] = "human-male\\lore328_idle_1.ogg",
            ["There's nothing in the box. People keep asking, so there it is. I made it because I wanted to get the fit right. Once that lid settled neatly, I opened it and tried again. Still pleasing. A small job can be worth doing for itself."] = "human-male\\lore341_idle_1.ogg",
            ["A spare scrap of wax, a few moments, and there he was. I had meant to straighten him out. Yet each time I look, I rather like the way he leans. One cannot insist on a perfect result in every small endeavor."] = "human-male\\lore344_idle_1.ogg",
            ["I toss a spare cork into an empty mug when the clearing up is done. Three in a row, once. Nobody saw it. Naturally, every time I've tried to show someone, the cork has developed other ambitions."] = "human-male\\lore346_idle_1.ogg",
            ["A stone holds the sun's warmth for a while. I noticed that during a quiet stop on the road. Rested my hand there and let myself enjoy it. A small thing. I try to leave room for those when I can."] = "human-male\\lore349_idle_1.ogg",
            ["I tried drawing my route from memory. Put in all the people I look forward to greeting, and forgot half the streets. Not much use as a map. Quite a pleasant thing to look at."] = "human-male\\lore3518_idle_1.ogg",
            ["You can tell a hungry gryphon from a cross one. Usually."] = "human-male\\lore352_idle_1.ogg",
            ["Someone called back a splendid line the other morning. Better than mine. I have been wanting to borrow it ever since. I shall ask first."] = "human-male\\lore3627_idle_1.ogg",
            ["I once waited out a shower beside the lake. First a few little rings, then more than you could count. Found I was quite happy watching them. A useful thing to discover, considering how often the weather makes its own arrangements."] = "human-male\\lore381_idle_1.ogg",
            ["I prefer the end of the loaf. Warm it near a fire and take a little care with the edge. That first crunch is worth waiting for. A small thing, perhaps, but I intend to enjoy it while it's there."] = "human-male\\lore382_idle_1.ogg",
            ["Pack for the journey you're taking, not the appetite you had before breakfast."] = "human-male\\lore3935_idle_1.ogg",
            ["Someone described a lovely view to me, then forgot its name. I have left a space on my map. Perhaps we shall find it."] = "human-male\\lore4078_idle_1.ogg",
            ["I smooth out my lunch cloth before I fold it. More carefully than necessary, perhaps. But someone took the trouble to think of me before it reached the road. I like to take a little care in return."] = "human-male\\lore464_idle_1.ogg",
            ["Every tale gets to the interesting bit just as someone wants another drink."] = "human-male\\lore465_idle_1.ogg",
            ["A well-kept mustache does no harm to a commander's bearing. I give mine a little attention before an important greeting. You may be good enough to regard that as routine preparation."] = "human-male\\lore466_idle_1.ogg",
            ["I promised Osric a proper meal at my family's home when Westfall is safe. Sometimes I scribble down a menu beside the supply notes. Fresh bread, good company, everyone arriving safely. I like thinking that far ahead."] = "human-male\\lore491_idle_1.ogg",
            ["A teacup and crossed biscuits. An entirely imaginary guild crest. Its meetings would have no agenda. I find the idea quite restful."] = "human-male\\lore4974_idle_1.ogg",
            ["Ben's Magnificent. That is as far as the name goes. Possibly I should learn to make the cheese before adding another word. Magnificent is already asking quite a lot."] = "human-male\\lore4981_idle_1.ogg",
            ["A good bell shouldn't sound like another order being shouted."] = "human-male\\lore514_idle_1.ogg",
            ["Easy, Skyfeather. They're just tourists."] = "human-male\\lore523_idle_1.ogg",
            ["I count my steps when I am thinking. Then someone brings me a question, and I lose count. A worthwhile interruption, usually."] = "human-male\\lore5484_idle_1.ogg",
            ["An unfamiliar greeting takes practice. I ask people to repeat it. They have been very patient with me, especially over the sounds I thought I already knew."] = "human-male\\lore5489_idle_1.ogg",
            ["I remember the count of my best throw. Entirely. Yes, I do hear how that sounds after a lecture on humility."] = "human-male\\lore5491_idle_1.ogg",
            ["More repair thread than lunch. Again. I keep thinking someone will need a seam fixed. Perhaps we should find a baker first."] = "human-male\\lore5564_idle_1.ogg",
            ["Before I send a pupil away, I think of the people who will be glad to see them return. A familiar instruction must never become an empty speech. There is a life going out through that door."] = "human-male\\lore6171_idle_1.ogg",
            ["Stephanie should hear about the kind people here, as well as the bundles coming home."] = "human-male\\lore6175_idle_1.ogg",
            ["A neat knot makes a small thing feel worth opening carefully."] = "human-male\\lore66_idle_1.ogg",
            ["Those slippers are a serious study in comfort. A very pleasant study."] = "human-male\\lore74_idle_1.ogg",
            ["I like to imagine a pupil teaching someone I shall never meet. Galvan's old promise, still on the road. That is a good thought to carry into the work."] = "human-male\\lore7798_idle_1.ogg",
            ["A welcome back to me. Such a small thing, and it can brighten the whole afternoon. You'd think I'd be used to it by now."] = "human-male\\lore7917_idle_1.ogg",
            ["I put a wobbling stool right the other day. Checked the legs, fitted a little packing piece, and sat down. A small job, but a useful one. I was a farmer before I was a captain. I still enjoy that sort of work."] = "human-male\\lore821_idle_1.ogg",
            ["I sometimes stop outside the inn and listen. Somebody laughs, somebody else joins in. I don't need to know the joke. It's enough to hear people with a little room in their day for that."] = "human-male\\lore859_idle_1.ogg",
            ["I practice a quiet hello. Occupational habit. You'd be surprised how easily a friendly visit becomes a public announcement."] = "human-male\\lore8670_idle_1.ogg",
            ["What sorts of little things do you like? No particular reason. That sounded much less suspicious in my head."] = "human-male\\lore8719_idle_1.ogg",
            ["I watched a grasshopper make a remarkable leap. Started composing a very solemn report about it in my head. By the time I'd given it an appropriately magnificent rank, the little creature was well out of sight."] = "human-male\\lore878_idle_1.ogg",
            ["I keep a little mint plant in a pot. Sometimes I check it twice even though it can't have changed. I know that. I just like seeing a little green thing growing while the rest of the day keeps asking for attention."] = "human-male\\lore8934_idle_1.ogg",
            ["A crooked apple can still be sweet. Worth remembering when you're choosing."] = "human-male\\lore894_idle_1.ogg",
            ["I once chose an apple rather sharper than expected. After the first surprise, I found I liked it. Now I look for the green ones. Occasionally one still makes me blink. A small test of composure, entirely of my own choosing."] = "human-male\\lore900_idle_1.ogg",
            ["Everyone checks the edge of a blade. Sensible enough. I also check whether the dry things in my kit are still dry. A small precaution, until you've stood long enough to appreciate it."] = "human-male\\lore903_idle_1.ogg",
            ["I know it from the first few notes. What is it called? Never learned the name. Sometimes I leave a coin before the best part, in the hope of hearing it twice. There, a modest secret for you."] = "human-male\\lore918_idle_1.ogg",
            ["The simplest lesson is often worth returning to. I still do."] = "human-male\\lore927_idle_1.ogg",
            ["A fish for a weather vane. I want it to look as if it has leapt into the wind. Yes, that is what is on the paper. You can have a look."] = "human-male\\lore957_idle_1.ogg",
            ["Nice day for it."] = "human-male\\npc_idle_1.ogg",
            ["If a kobold's carrying a book, I'd rather know the title."] = "human-male\\lore240_idle_2.ogg",
            ["Amazing how far a lost glove can travel without its owner."] = "human-male\\lore295_idle_2.ogg",
            ["Thor will say his birds are faster. Ask him which way the wind was blowing."] = "human-male\\lore352_idle_2.ogg",
            ["Somewhere a courier is late, and I will hear about it."] = "human-male\\lore523_idle_2.ogg",
            ["{zone} is lovely this time of year."] = "human-male\\npc_idle_2.ogg",
            ["A blank report can be excellent news, provided someone actually checked."] = "human-male\\lore240_idle_3.ogg",
            ["Wonder who's sitting in your usual chair tonight."] = "human-male\\lore295_idle_3.ogg",
            ["No, I wasn't humming. That was my boot."] = "human-male\\lore352_idle_3.ogg",
            ["If you see a storm cloud, don't tell the birds."] = "human-male\\lore523_idle_3.ogg",
            ["Don't mind me. I'm enjoying the company."] = "human-male\\npc_idle_3.ogg",
            ["You know, I don't get out nearly enough."] = "human-male\\npc_idle_4.ogg",
            ["My feet are already sore. In a good way."] = "human-male\\npc_idle_5.ogg",
            ["I wonder how things are back home without me."] = "human-male\\npc_idle_6.ogg",
            ["Every road looks different when you're not working."] = "human-male\\npc_idle_7.ogg",
            ["Have you ever just stopped and listened to the wind?"] = "human-male\\npc_idle_8.ogg",
            ["I could get used to this."] = "human-male\\npc_idle_9.ogg",
            ["Don't tell anyone, but this beats standing in one spot all day."] = "human-male\\npc_idle_10.ogg",
            ["If you need a hand, just say the word."] = "human-male\\npc_idle_11.ogg",
            ["Good company makes the miles shorter."] = "human-male\\npc_idle_12.ogg",
            ["Mind if I stretch? Old bones."] = "human-male\\npc_idle_13.ogg",
            ["Getting late. The stars will be out soon."] = "human-male\\npc_idle_14.ogg",
            ["Quiet night. I like quiet nights."] = "human-male\\npc_idle_15.ogg",
            ["We've been at it for a while. You're tireless, you know that?"] = "human-male\\npc_idle_16.ogg",
            ["I used to wonder what was past the next hill. Now I know: another hill."] = "human-male\\npc_idle_17.ogg",
            ["Do you ever get used to all this walking?"] = "human-male\\npc_idle_18.ogg",
            ["I've heard stories about you, you know. Some of them are even nice."] = "human-male\\npc_idle_19.ogg",
            ["Smell that? Somebody's cooking something good nearby."] = "human-male\\npc_idle_20.ogg",
            ["If anyone asks, I'm on important business."] = "human-male\\npc_idle_21.ogg",
            ["You're easy company. I mean that kindly."] = "human-male\\npc_idle_22.ogg",
            ["I keep thinking I left something on the stove."] = "human-male\\npc_idle_23.ogg",
            ["Look at that sky."] = "human-male\\npc_idle_24.ogg",
            ["Back home they'll never believe where I've been."] = "human-male\\npc_idle_25.ogg",
            ["I should have brought a better pair of boots."] = "human-male\\npc_idle_26.ogg",
            ["Funny how a quiet road can feel like a holiday."] = "human-male\\npc_idle_27.ogg",
            ["Do adventurers ever take a day off? Asking for a friend. The friend is me."] = "human-male\\npc_idle_28.ogg",
            ["I've counted twelve birds since we set out. Thirteen. Never mind."] = "human-male\\npc_idle_29.ogg",
            ["One of these days you'll have to tell me how you got started."] = "human-male\\npc_idle_30.ogg",
            ["You can tell a lot about someone by how they walk. You walk like you mean it."] = "human-male\\npc_idle_31.ogg",
            ["I'm not complaining. I'm just saying my feet have opinions."] = "human-male\\npc_idle_32.ogg",
            ["Sorry, I've had the same tune stuck in my head all day."] = "human-male\\npc_idle_33.ogg",
            ["If we pass a merchant, remind me I need thread."] = "human-male\\npc_idle_34.ogg",
            ["I wonder what the folks back home are gossiping about."] = "human-male\\npc_idle_35.ogg",
            ["Every time I think I've seen it all, you take me somewhere new."] = "human-male\\npc_idle_36.ogg",
            ["It's peaceful out here. Until it isn't."] = "human-male\\npc_idle_37.ogg",
            ["I could do with a cup of something warm."] = "human-male\\npc_idle_38.ogg",
            ["Morning air's the best air."] = "human-male\\npc_idle_39.ogg",
            ["Early start, eh? I approve."] = "human-male\\npc_idle_40.ogg",
            ["The light's going gold. Best time of day."] = "human-male\\npc_idle_41.ogg",
            ["Stars are out. Makes you feel small, doesn't it?"] = "human-male\\npc_idle_42.ogg",
            ["Shouldn't we both be in bed by now?"] = "human-male\\npc_idle_43.ogg",
            ["Long day. Good day, though."] = "human-male\\npc_idle_44.ogg",
            ["Still going? I'll say this for you: you don't quit."] = "human-male\\npc_idle_45.ogg",
            ["Ha! I'll have to remember that one."] = "human-male\\npc_jokeBack_1.ogg",
            ["Oh, that's terrible. Tell it again."] = "human-male\\npc_jokeBack_2.ogg",
            ["I'm stealing that one."] = "human-male\\npc_jokeBack_3.ogg",
            ["Oh my."] = "human-male\\npc_kissed_1.ogg",
            ["Well, I never."] = "human-male\\npc_kissed_2.ogg",
            ["Now you've made me blush."] = "human-male\\npc_kissed_3.ogg",
            ["There! A proper landing. Give the bird a little credit."] = "human-male\\lore352_landed_1.ogg",
            ["Not bad. I'd have landed it softer, but not bad."] = "human-male\\lore523_landed_1.ogg",
            ["Safe and sound."] = "human-male\\npc_landed_1.ogg",
            ["Good landing. I'll tell the birds."] = "human-male\\npc_landed_2.ogg",
            ["Solid ground. Feels strange after all that sky."] = "human-male\\npc_landed_3.ogg",
            ["Down we come. Legs still work? Good."] = "human-male\\npc_landed_4.ogg",
            ["That was a fine flight."] = "human-male\\npc_landed_5.ogg",
            ["Ha! Good one."] = "human-male\\npc_laughAlong_1.ogg",
            ["Heh. You're funny."] = "human-male\\npc_laughAlong_2.ogg",
            ["Ha! That laugh of yours is catching."] = "human-male\\npc_laughAlong_3.ogg",
            ["A new technique! Excellent. Now you can make it look as good as it works. Show me when you've had a little practice."] = "human-male\\lore11096_learned_1.ogg",
            ["There you are. You couldn't do that before, and now you can. Give yourself credit for the practice."] = "human-male\\lore1300_learned_1.ogg",
            ["Well done. Take time to understand what changed, rather than rushing straight to the next lesson. And if you reach a question I cannot answer, I will gladly help you find someone who can."] = "human-male\\lore1317_learned_1.ogg",
            ["There, you have made progress. Give yourself time to notice what worked before rushing into the next correction."] = "human-male\\lore1324_learned_1.ogg",
            ["Good! Give the new method a little practice before you judge it. The first attempt tells you where the work begins. Bring your questions as well as your successes; both can make a useful lesson."] = "human-male\\lore1346_learned_1.ogg",
            ["Well done. A new skill gives an idea somewhere to go. Take the time to try it for yourself. I should enjoy hearing what you discover when the first attempt becomes your own work."] = "human-male\\lore258568_learned_1.ogg",
            ["There, another thing you can do. Be pleased with it. I like seeing an ambition turn into something real, one lesson at a time."] = "human-male\\lore4981_learned_1.ogg",
            ["Good. Practice it while you remember where the difficult part was. Understanding improves when you return to the work."] = "human-male\\lore5484_learned_1.ogg",
            ["Well done. Remember the people who helped you reach this point. There will be another learner who could use the same kindness."] = "human-male\\lore5491_learned_1.ogg",
            ["There. You stayed with it, and now you can do it. Remember that next time the work seems slow."] = "human-male\\lore5564_learned_1.ogg",
            ["Well done. Now consider whom this new ability may help. Be proud of what you have learned, and take care in how you use it."] = "human-male\\lore6171_learned_1.ogg",
            ["Well done. Keep the lesson, and when someone else is ready to learn it, give them the same chance. That is work worth being proud of."] = "human-male\\lore7798_learned_1.ogg",
            ["Something new to practice. Tell me which part made sense when you tried it. I like hearing about the small step that finally gets a thing going. A little progress can be very satisfying to notice."] = "human-male\\lore8934_learned_1.ogg",
            ["Good. Now give yourself time to notice when the lesson is useful. Knowing a trick and choosing the right moment for it are both worth learning."] = "human-male\\lore918_learned_1.ogg",
            ["Good. Try it again before you decide you have mastered it. If something goes wrong, show me where. That I can help with."] = "human-male\\lore957_learned_1.ogg",
            ["Learning something new? Good for you."] = "human-male\\npc_learned_1.ogg",
            ["Always improving. I admire that."] = "human-male\\npc_learned_2.ogg",
            ["Something new up your sleeve? I'll be watching."] = "human-male\\npc_learned_3.ogg",
            ["The more you know, the better. That's what I always say."] = "human-male\\npc_learned_4.ogg",
            ["You've come a long way since your first report."] = "human-male\\lore240_levelUp_1.ogg",
            ["Look how far you've come! I'll still remember you before all that fancy armor."] = "human-male\\lore295_levelUp_1.ogg",
            ["Look at you now! Hard to believe you ever needed directions."] = "human-male\\lore352_levelUp_1.ogg",
            ["Another level! The birds will want to hear about this."] = "human-male\\lore523_levelUp_1.ogg",
            ["Level {level}! Well done, {name}!"] = "human-male\\npc_levelUp_1.ogg",
            ["Look at you, {name}. Level {level} already."] = "human-male\\npc_levelUp_2.ogg",
            ["Level {level}! That calls for a cheer!"] = "human-male\\npc_levelUp_3.ogg",
            ["Level {level}. I've seen a lot of adventurers come and go. You're one of the good ones."] = "human-male\\npc_levelUp_4.ogg",
            ["Ha! Level {level}! Well earned."] = "human-male\\npc_levelUp_5.ogg",
            ["Level {level}. Wait until I tell everyone back home."] = "human-male\\npc_levelUp_6.ogg",
            ["Stronger every day. I can see it."] = "human-male\\npc_levelUp_7.ogg",
            ["Another level! I knew you had it in you."] = "human-male\\npc_levelUp_8.ogg",
            ["Well, look who's moving up in the world."] = "human-male\\npc_levelUp_9.ogg",
            ["Another step up. Mind you don't get a big head."] = "human-male\\npc_levelUp_10.ogg",
            ["Give it a proper look. A bright surface can be pleasing without telling you everything you need to know. If something about it troubles you, attend to that before putting it to use."] = "human-male\\lore1284_loot_1.ogg",
            ["Something useful? Have a proper look. An ordinary thing can hold a very good idea, if you give it a little thought before putting it aside."] = "human-male\\lore1285_loot_1.ogg",
            ["A good find! Now, are you keeping it, selling it, or waiting for me to make a terrible remark about it?"] = "human-male\\lore1298_loot_1.ogg",
            ["A find worth talking about? Let me have a look. You can tell me how it happened while we walk. I'll enjoy the story just as much if it stays exactly the size you remember. Mine do tend to wander."] = "human-male\\lore1678_loot_1.ogg",
            ["Anything that explains what they were doing out here?"] = "human-male\\lore240_loot_1.ogg",
            ["A useful find? Have a proper look. If it happens to be a coin, I recommend keeping a hand underneath it until you are quite certain of your technique."] = "human-male\\lore2795_loot_1.ogg",
            ["Look before you discard it. An old insignia may mean little to the person who finds it and a great deal to a family waiting for something of their own to be returned."] = "human-male\\lore466_loot_1.ogg",
            ["A useful find? Let's have a look. I like the moment when something needed actually turns up. Someone found it, someone carried it, and now it can do some good. Worth remembering the people in the middle."] = "human-male\\lore491_loot_1.ogg",
            ["That looks interesting. Before we put a price on it, do you want to keep it for yourself?"] = "human-male\\lore8719_loot_1.ogg",
            ["{item}! Now that's a find."] = "human-male\\npc_loot_1.ogg",
            ["Well, look at that. {item}."] = "human-male\\npc_loot_2.ogg",
            ["{item}! Lucky day."] = "human-male\\npc_loot_3.ogg",
            ["Ooh, what did you find?"] = "human-male\\npc_loot_4.ogg",
            ["Anything good in there?"] = "human-male\\npc_loot_5.ogg",
            ["Pockets full! Nice."] = "human-male\\npc_loot_6.ogg",
            ["You're hurt! Get out of there!"] = "human-male\\npc_lowHealth_1.ogg",
            ["Careful! You're nearly done in!"] = "human-male\\npc_lowHealth_2.ogg",
            ["Back off and catch your breath!"] = "human-male\\npc_lowHealth_3.ogg",
            ["You're bleeding! Fall back!"] = "human-male\\npc_lowHealth_4.ogg",
            ["Get out of there!"] = "human-male\\npc_lowHealth_5.ogg",
            ["Drink something! Anything!"] = "human-male\\npc_lowHealth_6.ogg",
            ["This isn't worth dying over!"] = "human-male\\npc_lowHealth_7.ogg",
            ["Run! I'll tell everyone you were brave!"] = "human-male\\npc_lowHealth_8.ogg",
            ["Bandage! Potion! Something!"] = "human-male\\npc_lowHealth_9.ogg",
            ["Hang on! Don't you dare go down!"] = "human-male\\npc_lowHealth_10.ogg",
            ["A letter? Read it through. Even the lines added at the end may be worth your time. Someone remembered another thing they wanted you to know."] = "human-male\\lore12336_mail_1.ogg",
            ["A message? Let us see who is waiting for an answer. A request from far away is still someone's immediate need."] = "human-male\\lore1323_mail_1.ogg",
            ["A letter can carry a great deal of hope for something so easily folded. Read yours carefully. I hope it brings an answer you've been waiting for, and a little less reason to wait for the next one."] = "human-male\\lore344_mail_1.ogg",
            ["A letter? I hope there's news from Stephanie. It's good to hear an ordinary day went well."] = "human-male\\lore6175_mail_1.ogg",
            ["News from the auctions? Go on, have a look. I can wait without announcing the contents to the street."] = "human-male\\lore8670_mail_1.ogg",
            ["Looks like you've got mail."] = "human-male\\npc_mail_1.ogg",
            ["Someone's written to you. How nice."] = "human-male\\npc_mail_2.ogg",
            ["A letter! I hope it's good news."] = "human-male\\npc_mail_3.ogg",
            ["Mail for you. Somebody's thinking of you."] = "human-male\\npc_mail_4.ogg",
            ["Level {level}! There's nothing left to teach you, is there?"] = "human-male\\npc_maxLevel_1.ogg",
            ["The very top! I'm honored to have come along for it."] = "human-male\\npc_maxLevel_2.ogg",
            ["That's the peak. Where do you go from here? Anywhere you like, I suppose."] = "human-male\\npc_maxLevel_3.ogg",
            ["Perfectly respectable. Bit short on wings, though."] = "human-male\\lore352_mount_1.ogg",
            ["A mount? Fine. A gryphon would be faster, but fine."] = "human-male\\lore523_mount_1.ogg",
            ["Riding in style, I see."] = "human-male\\npc_mount_1.ogg",
            ["Fine animal you've got there."] = "human-male\\npc_mount_2.ogg",
            ["I'll just walk alongside, shall I?"] = "human-male\\npc_mount_3.ogg",
            ["Now that's a proper way to travel."] = "human-male\\npc_mount_4.ogg",
            ["Does it have a name? It looks like it should have a name."] = "human-male\\npc_mount_5.ogg",
            ["{friend} seems friendly."] = "human-male\\npc_newFriend_1.ogg",
            ["I've heard good things about {friend}."] = "human-male\\npc_newFriend_2.ogg",
            ["Another friend! You collect them like coins."] = "human-male\\npc_newFriend_3.ogg",
            ["Another friendly face. You're good at this."] = "human-male\\npc_newFriend_4.ogg",
            ["You make friends faster than I make tea."] = "human-male\\npc_newFriend_5.ogg",
            ["What is it? I don't see anything."] = "human-male\\npc_pointToo_1.ogg",
            ["Where? Oh! No, I still don't see it."] = "human-male\\npc_pointToo_2.ogg",
            ["Is it something good? Or something bad?"] = "human-male\\npc_pointToo_3.ogg",
            ["Yes? You can give the report without prodding me."] = "human-male\\lore240_poke_1.ogg",
            ["Yes, yes, I heard you. There's no counter between us now."] = "human-male\\lore295_poke_1.ogg",
            ["That's where a gryphon would nip you back."] = "human-male\\lore352_poke_1.ogg",
            ["Careful, these pockets are full of gryphon feed."] = "human-male\\lore523_poke_1.ogg",
            ["Yes, {name}?"] = "human-male\\npc_poke_1.ogg",
            ["I'm listening. At ease."] = "human-male\\lore240_poke_2.ogg",
            ["That isn't how you ring for service!"] = "human-male\\lore295_poke_2.ogg",
            ["Easy. I'm not a saddle that needs adjusting."] = "human-male\\lore352_poke_2.ogg",
            ["Need a ride? Oh, right. We're walking."] = "human-male\\lore523_poke_2.ogg",
            ["Hm? Something on your mind?"] = "human-male\\npc_poke_2.ogg",
            ["I'm right here."] = "human-male\\npc_poke_3.ogg",
            ["Careful, now."] = "human-male\\npc_poke_4.ogg",
            ["Ha! You're a funny one."] = "human-male\\npc_poke_5.ogg",
            ["Need something?"] = "human-male\\npc_poke_6.ogg",
            ["Still here, still with you."] = "human-male\\npc_poke_7.ogg",
            ["What is it? Did you see something?"] = "human-male\\npc_poke_8.ogg",
            ["If that's how you say hello where you're from, all right."] = "human-male\\npc_poke_9.ogg",
            ["I'm listening."] = "human-male\\npc_poke_10.ogg",
            ["Still breathing, if that's what you're checking."] = "human-male\\npc_poke_11.ogg",
            ["Was that a poke or a question?"] = "human-male\\npc_poke_12.ogg",
            ["Easy! I bruise like a peach."] = "human-male\\npc_poke_13.ogg",
            ["You have my full attention. Mostly."] = "human-male\\npc_poke_14.ogg",
            ["Hm? Sorry, I was miles away."] = "human-male\\npc_poke_15.ogg",
            ["Ask away."] = "human-male\\npc_poke_16.ogg",
            ["Ow. Was that necessary?"] = "human-male\\npc_poke_17.ogg",
            ["What, did I miss something?"] = "human-male\\npc_poke_18.ogg",
            ["Present and accounted for."] = "human-male\\npc_poke_19.ogg",
            ["Yes, yes, I see you."] = "human-male\\npc_poke_20.ogg",
            ["All right, all right, I'm awake!"] = "human-male\\npc_pokeMany_1.ogg",
            ["Is this going to keep happening?"] = "human-male\\npc_pokeMany_2.ogg",
            ["You'd think I was a doorbell."] = "human-male\\npc_pokeMany_3.ogg",
            ["I'm starting to think you enjoy this."] = "human-male\\npc_pokeMany_4.ogg",
            ["Enough! I surrender!"] = "human-male\\npc_pokeMany_5.ogg",
            ["One more and I'm going home. I mean it. Probably."] = "human-male\\npc_pokeMany_6.ogg",
            ["Tell me how it went while it's still fresh. The useful details first. Then you can sit down and tell me the part that made you glad you went. I'd rather not lose either account."] = "human-male\\lore1070_quest_1.ogg",
            ["Good work. When you report back, give them the useful part first. They will want to know what happened, and whether the work is done."] = "human-male\\lore12480_quest_1.ogg",
            ["Thank you. You made someone's day a little easier. I know how much a simple delivery can mean."] = "human-male\\lore1427_quest_1.ogg",
            ["Delivery made! Now, have we time to find something nice for lunch? I believe we've earned it."] = "human-male\\lore1433_quest_1.ogg",
            ["Well done. A little help in the right place can let someone else finish the work they have been waiting to do."] = "human-male\\lore1444_quest_1.ogg",
            ["Well done. Someone will be glad you saw that through. A shared effort depends on people willing to do their part, and their work deserves to be acknowledged."] = "human-male\\lore14722_quest_1.ogg",
            ["A useful task, done when it was needed. I should like to be known for that. Titles can come afterward. Well done, my friend; someone can depend on you to see things through."] = "human-male\\lore17804_quest_1.ogg",
            ["Well done! That is news worth hearing. Give yourself a moment to enjoy it. A call for help has found someone willing to see the work through."] = "human-male\\lore2198_quest_1.ogg",
            ["Useful work. Let us hope it brings someone a little closer to home."] = "human-male\\lore234_quest_1.ogg",
            ["Good work. Tell me what you saw, while it's fresh."] = "human-male\\lore240_quest_1.ogg",
            ["They listened? Good. Some warnings need more than a merchant behind them."] = "human-male\\lore241_quest_1.ogg",
            ["Work finished properly. That's worth more than a grand promise."] = "human-male\\lore250_quest_1.ogg",
            ["You found a way to help? Good. I like hearing that a difficult thing isn't impossible."] = "human-male\\lore252_quest_1.ogg",
            ["A useful day's work. I hope we've made someone's life a little easier."] = "human-male\\lore253_quest_1.ogg",
            ["A result delivered. Wonderful. Someone will be very pleased to hear that their trust was well placed."] = "human-male\\lore2708_quest_1.ogg",
            ["Delivered safely? Splendid. Was there any news from William?"] = "human-male\\lore279_quest_1.ogg",
            ["Another favor done. I hope they offered you a seat."] = "human-male\\lore295_quest_1.ogg",
            ["Well done. Tell me what you observed, not only what you expected to find."] = "human-male\\lore328_quest_1.ogg",
            ["A delivery? Osric's crates would look light beside that lot."] = "human-male\\lore352_quest_1.ogg",
            ["Well done. When you tell me about it, begin at the beginning. I should hate to miss the interesting part."] = "human-male\\lore4078_quest_1.ogg",
            ["An errand seen through properly. Don't let the ordinary ones pass without a word of thanks. A warning delivered, a meal carried, a small kindness remembered; those things can matter a great deal to the person waiting for them."] = "human-male\\lore464_quest_1.ogg",
            ["Another errand run! Lewis would be proud."] = "human-male\\lore523_quest_1.ogg",
            ["You saw someone who needed help, and you answered. I'm very glad. There is kindness in seeing a thing through."] = "human-male\\lore7917_quest_1.ogg",
            ["Someone needed help, and you made time. That is worth being proud of."] = "human-male\\lore927_quest_1.ogg",
            ["Another job done. Nicely handled."] = "human-male\\npc_quest_1.ogg",
            ["Well done! They'll be grateful."] = "human-male\\npc_quest_2.ogg",
            ["You've a knack for helping folk."] = "human-male\\npc_quest_3.ogg",
            ["That's one more person sleeping easier tonight."] = "human-male\\npc_quest_4.ogg",
            ["Good work. Who's next?"] = "human-male\\npc_quest_5.ogg",
            ["Word gets around. People will remember that."] = "human-male\\npc_quest_6.ogg",
            ["Nicely done. Somebody's going to tell that story at the inn."] = "human-male\\npc_quest_7.ogg",
            ["That's the way!"] = "human-male\\npc_quest_8.ogg",
            ["You make it look easy."] = "human-male\\npc_quest_9.ogg",
            ["Done and done. What's next?"] = "human-male\\npc_quest_10.ogg",
            ["Another errand? I like your spirit."] = "human-male\\npc_questAccepted_1.ogg",
            ["Off we go, then."] = "human-male\\npc_questAccepted_2.ogg",
            ["Somebody's lucky you came along."] = "human-male\\npc_questAccepted_3.ogg",
            ["Here we go again. I love it."] = "human-male\\npc_questAccepted_4.ogg",
            ["Sounds like trouble. Count me in."] = "human-male\\npc_questAccepted_5.ogg",
            ["Hm? Did I doze off?"] = "human-male\\npc_reload_1.ogg",
            ["Strange. I could swear the world just blinked."] = "human-male\\npc_reload_2.ogg",
            ["Where was I? Oh, right. With you."] = "human-male\\npc_reload_3.ogg",
            ["Hm. I lost my train of thought. Something about the road."] = "human-male\\npc_reload_4.ogg",
            ["A good chance to sit. I won't pretend I'm going to finish a chapter this time. Tell me your news instead. A peaceful pause with a friend is a very fine use of the afternoon."] = "human-male\\lore10045_rest_1.ogg",
            ["A little rest would be wise. Sit a moment. You can tell me what has been troubling you, or we can simply enjoy a quiet pause together."] = "human-male\\lore1212_rest_1.ogg",
            ["Let's sit. If we were back at the shop, this would be the moment for a cup. No need to hurry the break."] = "human-male\\lore1289_rest_1.ogg",
            ["A seat would be welcome. If I offer you a biscuit later, remember how honestly we've always spoken to one another."] = "human-male\\lore1294_rest_1.ogg",
            ["A good place to sit. Shall I try the trick? No, you needn't look solemn about it. If everything falls down, we can have a laugh and call that the entertainment. That part usually goes quite well."] = "human-male\\lore1314_rest_1.ogg",
            ["A seat sounds good. If we have room for the little board, you can have the first move. Otherwise, tell me what you would try. I am curious."] = "human-male\\lore1341_rest_1.ogg",
            ["Sit a moment, friend. An ordinary bit of company can improve a day considerably. Considerably. Another good word. I'll try not to use all the long ones before you've had a turn."] = "human-male\\lore1395_rest_1.ogg",
            ["A good moment for a meal. If you're cooking, I'll try very hard to stay out of your way."] = "human-male\\lore1430_rest_1.ogg",
            ["Sit with me a moment. I am glad you came. There, I managed a plain welcome. Rather a pleasant one, with the right person here to hear it."] = "human-male\\lore1432_rest_1.ogg",
            ["A pause sounds good. Give your feet a moment. We may even find time to look up and disagree about what we see. I promise to consider the potato fairly."] = "human-male\\lore14439_rest_1.ogg",
            ["Now this is promising. A seat, good company and time to hear an answer. Tell me how you have been. We needn't hurry to the exciting part."] = "human-male\\lore1477_rest_1.ogg",
            ["A good chance to sit. We can let the next errand wait a moment and have a proper conversation. Tell me one small thing that went well today. A good meal counts, if you had one."] = "human-male\\lore1670_rest_1.ogg",
            ["A good moment to sit. Tell me your news, and I'll practice leaving things alone long enough to enjoy it. There's a kind of waiting that feels like a rest. I'd like to get better at remembering that one."] = "human-male\\lore1680_rest_1.ogg",
            ["A chance to sit without discussing the wagon. Well, I mentioned it, didn't I? You'll have to start us on another subject. Tell me about a pleasant meal, or a road that gave you no trouble at all."] = "human-male\\lore237_rest_1.ogg",
            ["Fine bit of shade. We ought to give it a proper try before moving on."] = "human-male\\lore255_rest_1.ogg",
            ["Sit a moment. Care includes recognizing when a pause is needed. Let the day's business settle a little, and tell me what has been on your mind."] = "human-male\\lore258930_rest_1.ogg",
            ["Sit down, have a drink, tell me what you think. No grand description required."] = "human-male\\lore258_rest_1.ogg",
            ["There we are. Sit before your knees make the decision for you."] = "human-male\\lore295_rest_1.ogg",
            ["A good place to sit and catch our breath. Tell me how your day has been. I'll save the next joke for later. Sometimes a friend needs a willing ear much more than another reason to groan."] = "human-male\\lore3089_rest_1.ogg",
            ["Let's have a seat. I won't turn a quiet moment into a supply errand, I promise. Tell me something pleasant instead. And if a cork should happen to land in a mug, do feel free to applaud."] = "human-male\\lore346_rest_1.ogg",
            ["Here will do. If that stone's had the sun on it, it should be pleasant enough to rest a hand against. Nothing remarkable about it. Just a little warmth, a quiet moment, and someone I trust beside me."] = "human-male\\lore349_rest_1.ogg",
            ["This'll do. Room enough to sit, and a bit of shelter if we need it. You needn't have news every time we stop. Sometimes it's enough to hear the water and know you've got good company beside you."] = "human-male\\lore381_rest_1.ogg",
            ["Sit down a moment before this cools. Choose the piece you want. I've had my eye on the heel since I broke it off. There, that's a proper crunch. A quiet meal improves considerably with good company."] = "human-male\\lore382_rest_1.ogg",
            ["Sit a while. No orders to fill here; I've time to hear the whole thing."] = "human-male\\lore465_rest_1.ogg",
            ["Set the tools down. Good work needs rested hands."] = "human-male\\lore514_rest_1.ogg",
            ["A sound seat and a moment to use it. That'll do. We needn't turn the whole pause into another report. Tell me what you've been enjoying when the work gives you a little room."] = "human-male\\lore821_rest_1.ogg",
            ["We can sit here a while. There's always another matter waiting, but it can wait five minutes more. You don't have to fill the silence. Having someone beside me is company enough."] = "human-male\\lore859_rest_1.ogg",
            ["This will do nicely. Sit beside me a moment. I have high expectations of this apple, though I shall try to keep the result off my face. If I fail, you may laugh. I should rather enjoy having someone to share the occasion with."] = "human-male\\lore900_rest_1.ogg",
            ["This looks dry enough. Sit down and give your feet a chance. There's no medal for keeping a wet boot on longer than you need to. If there were, half the guard would have a chestful."] = "human-male\\lore903_rest_1.ogg",
            ["A good place to rest our feet."] = "human-male\\npc_rest_1.ogg",
            ["Nothing like a warm inn."] = "human-male\\npc_rest_2.ogg",
            ["I could sit here all day."] = "human-male\\npc_rest_3.ogg",
            ["A chair, a fire, good company. That's living."] = "human-male\\npc_rest_4.ogg",
            ["Let's stay a moment. My feet insist."] = "human-male\\npc_rest_5.ogg",
            ["Easy there, tiger."] = "human-male\\npc_roarBack_1.ogg",
            ["Very fierce. I'm terrified."] = "human-male\\npc_roarBack_2.ogg",
            ["Was that a roar or a yawn?"] = "human-male\\npc_roarBack_3.ogg",
            ["Charming."] = "human-male\\npc_rudeBack_1.ogg",
            ["I'll pretend I didn't see that."] = "human-male\\npc_rudeBack_2.ogg",
            ["Well, I never! Actually, I have. But still."] = "human-male\\npc_rudeBack_3.ogg",
            ["At your service."] = "human-male\\npc_saluteBack_1.ogg",
            ["Sir! Or madam."] = "human-male\\npc_saluteBack_2.ogg",
            ["Standing ready!"] = "human-male\\npc_saluteBack_3.ogg",
            ["Oh, it's {friend}! Say hello for me."] = "human-male\\npc_seeFriend_1.ogg",
            ["{friend}! Good to see a friendly face."] = "human-male\\npc_seeFriend_2.ogg",
            ["Look who it is! Give them a wave."] = "human-male\\npc_seeFriend_3.ogg",
            ["Oh, I know them! Small world."] = "human-male\\npc_seeFriend_4.ogg",
            ["No need to be shy."] = "human-male\\npc_shyToo_1.ogg",
            ["Aw, don't hide."] = "human-male\\npc_shyToo_2.ogg",
            ["You're among friends here."] = "human-male\\npc_shyToo_3.ogg",
            ["Don't mind if I do."] = "human-male\\npc_sitToo_1.ogg",
            ["Good idea. My knees agree."] = "human-male\\npc_sitToo_2.ogg",
            ["Ah, that's better."] = "human-male\\npc_sitToo_3.ogg",
            ["I could use a nap myself."] = "human-male\\npc_sleepToo_1.ogg",
            ["Wake me when it's time to go."] = "human-male\\npc_sleepToo_2.ogg",
            ["A nap does sound nice."] = "human-male\\npc_sleepToo_3.ogg",
            ["Hold on to your hat! Yes, even the expensive one. Especially the expensive one!"] = "human-male\\lore1310_taxi_1.ogg",
            ["Straps first. Admire the view once we're clear."] = "human-male\\lore352_taxi_1.ogg",
            ["A flight! I hope they're feeding that bird properly."] = "human-male\\lore523_taxi_1.ogg",
            ["Up we go! Never gets old."] = "human-male\\npc_taxi_1.ogg",
            ["Look at it all down there."] = "human-male\\npc_taxi_2.ogg",
            ["A good gryphon is worth its weight in gold."] = "human-male\\npc_taxi_3.ogg",
            ["Hold on tight!"] = "human-male\\npc_taxi_4.ogg",
            ["I'll never get tired of this view."] = "human-male\\npc_taxi_5.ogg",
            ["Don't look down. Actually, do. It's lovely."] = "human-male\\npc_taxi_6.ogg",
            ["The wind up here! Hold on to your hat."] = "human-male\\npc_taxi_7.ogg",
            ["Anytime."] = "human-male\\npc_thanked_1.ogg",
            ["Happy to help."] = "human-male\\npc_thanked_2.ogg",
            ["Don't mention it."] = "human-male\\npc_thanked_3.ogg",
            ["{friend} thinks of you as {tier} now. I'm not surprised."] = "human-male\\npc_tier_1.ogg",
            ["Making friends everywhere you go, aren't you?"] = "human-male\\npc_tier_2.ogg",
            ["People really warm to you, don't they?"] = "human-male\\npc_tier_3.ogg",
            ["That friendship's growing. Nice to see."] = "human-male\\npc_tier_4.ogg",
            ["Hello!"] = "human-male\\npc_waveBack_1.ogg",
            ["Hi there!"] = "human-male\\npc_waveBack_2.ogg",
            ["Well, hello to you too."] = "human-male\\npc_waveBack_3.ogg",
            ["Right back at you!"] = "human-male\\npc_waveBack_4.ogg",
            ["Different ground here. Give me a moment to look. A small thing might grow in the right patch, even if nobody has given the place much thought."] = "human-male\\lore1402_zone_1.ogg",
            ["A new place to look around. Let us get our bearings, then take a moment to notice it properly. There may be a turn worth remembering for another day."] = "human-male\\lore14438_zone_1.ogg",
            ["Different ground here. I wonder what grows well in it. You get used to looking at a place that way. Then you see a patch of color you didn't expect, and you remember to simply enjoy the view."] = "human-male\\lore233_zone_1.ogg",
            ["Different roads, same rule: know where your people are."] = "human-male\\lore240_zone_1.ogg",
            ["A new route today. Let us take time to notice who is here. A friendly greeting may be the part we remember best."] = "human-male\\lore3518_zone_1.ogg",
            ["New surroundings! Let us find something worth telling people about. Every place deserves at least one good invitation."] = "human-male\\lore3627_zone_1.ogg",
            ["{zone}! I know the flight path from here."] = "human-male\\lore523_zone_1.ogg",
            ["Another place, another welcome to learn. Let us listen before assuming we know how everyone here does things."] = "human-male\\lore5489_zone_1.ogg",
            ["New ground. Let's take a moment to look properly. You notice the road, then the shapes beside it, then something small you nearly missed. I like the part where the place becomes more than a name on a report."] = "human-male\\lore878_zone_1.ogg",
            ["So this is {zone}."] = "human-male\\npc_zone_1.ogg",
            ["{zone}, eh? Lead on."] = "human-male\\npc_zone_2.ogg",
            ["I haven't been to {zone} in years."] = "human-male\\npc_zone_3.ogg",
            ["{zone}. Stay sharp."] = "human-male\\npc_zone_4.ogg",
            ["Ah, {zone}. Look at that view."] = "human-male\\npc_zone_5.ogg",
            ["New place, new faces."] = "human-male\\npc_zone_6.ogg",
            ["Keep your eyes open. I don't know these parts."] = "human-male\\npc_zone_7.ogg",
            ["I've only ever heard stories about this place."] = "human-male\\npc_zone_8.ogg",
            ["Look at it all. Worth the walk."] = "human-male\\npc_zone_9.ogg",
            ["Smells different here. Not bad, just different."] = "human-male\\npc_zone_10.ogg",
            ["I'd better remember the way back."] = "human-male\\npc_zone_11.ogg",
            ["Well, this is a change of scenery."] = "human-male\\npc_zone_12.ogg",
