            ["Two hours in! You're a legend. I'm a tiny legend."] = "male\\idle_68.ogg",
            ["Still going strong! Should we hydrate? I'll hydrate."] = "male\\idle_69.ogg",
            ["Low level, big dreams. That's the gnome way."] = "male\\idle_70.ogg",
            ["We're getting good at this. Like, really good."] = "male\\idle_71.ogg",
