            ["Another Buddy. Should I be jealous?"] = "nightelf-female\\npc_buddy_2.ogg",
            ["Another Buddy! Your circle's getting crowded."] = "nightelf-female\\npc_buddy_3.ogg",
            ["Good choice. I'd vouch for them."] = "nightelf-female\\npc_buddy_4.ogg",
