            ["Don't hurt yourself."] = "skyborne-female\\npc_flexBack_2.ogg",
            ["Put those away before someone gets hurt."] = "skyborne-female\\npc_flexBack_3.ogg",
            ["That looks good on you."] = "skyborne-female\\npc_gear_1.ogg",
