            ["Lead the way, {name}."] = "skyborne-female\\npc_greet_1.ogg",
            ["Glad to come along, {name}!"] = "skyborne-female\\npc_greet_2.ogg",
            ["Where are we off to today?"] = "skyborne-female\\npc_greet_3.ogg",
            ["I told the others I'd be out for a while. Let's make it count."] = "skyborne-female\\npc_greet_4.ogg",
            ["It's good to get away from the counter for once."] = "skyborne-female\\npc_greet_5.ogg",
            ["Ready when you are, {name}."] = "skyborne-female\\npc_greet_6.ogg",
            ["Some fresh air will do me good."] = "skyborne-female\\npc_greet_7.ogg",
            ["Don't walk too fast. I'm not used to all this adventuring."] = "skyborne-female\\npc_greet_8.ogg",
            ["Well met, {name}! Good to see a friendly face."] = "skyborne-female\\npc_greet_9.ogg",
