            ["{zone} is lovely this time of year."] = "skyborne-female\\npc_idle_2.ogg",
            ["Don't mind me. I'm enjoying the company."] = "skyborne-female\\npc_idle_3.ogg",
            ["You know, I don't get out nearly enough."] = "skyborne-female\\npc_idle_4.ogg",
            ["My feet are already sore. In a good way."] = "skyborne-female\\npc_idle_5.ogg",
