            ["If anyone asks, I'm on important business."] = "skyborne-female\\npc_idle_21.ogg",
            ["You're easy company. I mean that kindly."] = "skyborne-female\\npc_idle_22.ogg",
            ["I keep thinking I left something on the stove."] = "skyborne-female\\npc_idle_23.ogg",
            ["Look at that sky."] = "skyborne-female\\npc_idle_24.ogg",
