            ["Sorry, I've had the same tune stuck in my head all day."] = "skyborne-female\\npc_idle_33.ogg",
            ["If we pass a merchant, remind me I need thread."] = "skyborne-female\\npc_idle_34.ogg",
            ["I wonder what the folks back home are gossiping about."] = "skyborne-female\\npc_idle_35.ogg",
            ["Every time I think I've seen it all, you take me somewhere new."] = "skyborne-female\\npc_idle_36.ogg",
            ["It's peaceful out here. Until it isn't."] = "skyborne-female\\npc_idle_37.ogg",
            ["I could do with a cup of something warm."] = "skyborne-female\\npc_idle_38.ogg",
            ["Morning air's the best air."] = "skyborne-female\\npc_idle_39.ogg",
